window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-2/eaif-2","titre":"EAIF II","sources":[{"t":"Exercices — Force","q":"qcm/qcm-exercices-force.html","f":"fiches/exercices-force.html"},{"t":"Exercices — Introduction","q":"qcm/qcm-exercices-intro.html","f":"fiches/exercices-intro.html"},{"t":"Exercices — Mobilité","q":"qcm/qcm-exercices-mobilite.html","f":"fiches/exercices-mobilite.html"},{"t":"Exercices — Pliométrie","q":"qcm/qcm-exercices-pliometrie.html","f":"fiches/exercices-pliometrie.html"},{"t":"Exercices — RSM","q":"qcm/qcm-exercices-rsm.html","f":"fiches/exercices-rsm.html"},{"t":"Exercices — Souplesse","q":"qcm/qcm-exercices-souplesse.html","f":"fiches/exercices-souplesse.html"},{"t":"Goniométrie Cours 1 — Concepts","q":"qcm/qcm-goniometrie-cours-1.html","f":"fiches/goniometrie-cours-1.html"},{"t":"Goniométrie Cours 2 — Procédures","q":"qcm/qcm-goniometrie-cours-2.html","f":"fiches/goniometrie-cours-2.html"},{"t":"Immobilisation Sélective","q":"qcm/qcm-immobilisation.html","f":"fiches/immobilisation-selective.html"},{"t":"Mob. Accessoire Cours 1","q":"qcm/qcm-mob-cours-1.html","f":"fiches/mob-cours-1.html"},{"t":"Mob. Accessoire Cours 2 — Maitland","q":"qcm/qcm-mob-cours-2.html","f":"fiches/mob-cours-2.html"},{"t":"Mob. Accessoire Cours 3 — Colonne vertébrale","q":"qcm/qcm-mob-cours-3.html","f":"fiches/mob-cours-3.html"},{"t":"Mob. Accessoire Cours 4 — Posture","q":"qcm/qcm-mob-cours-4.html","f":"fiches/mob-cours-4.html"},{"t":"Test musculaire","q":"qcm/qcm-testing.html","f":"fiches/testing.html"}],"questions":[{"q":"Combien de principes fondamentaux régissent l'entraînement musculaire ?","o":["2","3","4","6"],"r":2,"e":"4 principes : surcharge, spécificité, maintien/réversibilité, action retardée.","s":0},{"q":"Le principe de SURCHARGE stipule :","o":["Toujours utiliser sa charge maximale","Pour ↑ force, le muscle doit être surchargé (exigence progressive)","Toujours réduire la charge","Aucun principe"],"r":1,"e":"Surcharge progressive : ↑ exigence pour ↑ adaptation.","s":0},{"q":"Le principe de SPÉCIFICITÉ :","o":["Tous les muscles s'entraînent identiquement","Seuls les systèmes sollicités s'adaptent","Chaque exercice a un seul effet","Pas de spécificité"],"r":1,"e":"Spécificité : adaptation des systèmes sollicités selon les besoins.","s":0},{"q":"Le principe de MAINTIEN / RÉVERSIBILITÉ :","o":["Les gains sont éternels","Si le muscle n'est pas exercé, il revient à son état initial","Aucune perte possible","Toujours détérioration"],"r":1,"e":"Réversibilité : pertes en cas d'arrêt.","s":0},{"q":"Le principe d'ACTION RETARDÉE :","o":["Résultats immédiats","Résultats apparaissent en différé (surcompensation)","Pas d'effet","Effets aléatoires"],"r":1,"e":"Surcompensation = adaptation différée.","s":0},{"q":"Les fibres de TYPE I sont :","o":["Rapides, fatigables","Lentes, oxydatives, peu fatigables","Mixtes","Inactives"],"r":1,"e":"Type I = lentes, posturales, oxydatives, peu fatigables.","s":0},{"q":"Les fibres de TYPE IIb sont :","o":["Lentes","Très rapides, glycolytiques + ATP-CP, très fatigables","Aérobies","Toniques"],"r":1,"e":"Type IIb = rapides explosives, anaérobies, fatigables.","s":0},{"q":"Les fibres de TYPE IIa sont :","o":["Lentes pures","Intermédiaires (glycolytiques + oxydatives, rapides, modérément fatigables)","Identiques à IIb","Aérobies pures"],"r":1,"e":"Type IIa = intermédiaires.","s":0},{"q":"Les mitochondries sont nombreuses dans :","o":["IIb uniquement","I et IIa (oxydatives)","Aucune fibre","Toutes identiquement"],"r":1,"e":"Type I et IIa = beaucoup de mitochondries (métabolisme oxydatif).","s":0},{"q":"La myoglobine est élevée dans :","o":["IIb","I et IIa","Aucune fibre","Indépendant du type"],"r":1,"e":"Myoglobine élevée dans les fibres oxydatives (I et IIa).","s":0},{"q":"Le système ATP-CP fournit l'énergie pour :","o":["1-2 heures","< 30 sec (sprint, sauts)","30 min","Aucun usage"],"r":1,"e":"ATP-CP : 1/2 sec ATP, 2-10 sec CP. < 30 sec d'effort intense.","s":0},{"q":"La voie glycolytique (anaérobie lactique) couvre :","o":["< 5 sec","Jusqu'à 60 sec (glycogène musculaire), 1-3 min (hépatique)","> 30 min","Aucun effort"],"r":1,"e":"Glycolyse : 30 sec - 3 min selon le glycogène.","s":0},{"q":"La voie aérobie (oxydative) est :","o":["Très limitée","Illimitée (glucides puis lipides)","Inactive","Uniquement anaérobie"],"r":1,"e":"Aérobie : illimitée en capacité, mais puissance faible.","s":0},{"q":"Facteur limitant de la voie glycolytique :","o":["Manque d'O2","Acidose (acide lactique, ions H) → inhibition glycolyse","Manque d'ATP","Manque de glucose seul"],"r":1,"e":"Métabolites acides → acidose → inhibition.","s":0},{"q":"Un sprint 100 m utilise :","o":["ATP-PC principalement","Glycolytique secondairement","Aérobie principalement","Lipides"],"r":[0,1],"e":"Effort < 30 sec : ATP-PC, glycolytique en complément.","s":0},{"q":"Un marathon utilise principalement :","o":["ATP-PC","Glycolytique","Aérobie (glucides puis lipides)","Anaérobie alactique"],"r":2,"e":"> 3 min = oxydative.","s":0},{"q":"Un sprint 400 m (30-90 sec) utilise principalement :","o":["ATP-PC","Glycolytique","Aérobie","Lipides"],"r":1,"e":"30-90 sec = glycolytique.","s":0},{"q":"Un faible taux d'innervation (peu de fibres / motoneurone) caractérise :","o":["Quadriceps, biceps","Larynx, globe oculaire, doigts (mouvements précis)","Tous les muscles","Aucun muscle"],"r":1,"e":"Faible ratio = précision motrice (mouvements fins).","s":0},{"q":"Un grand nombre de fibres / motoneurone caractérise :","o":["Mouvements précis","Mouvements grossiers (jumeaux, biceps, quadriceps)","Doigts","Globe oculaire"],"r":1,"e":"Grand ratio = mouvements grossiers, force.","s":0},{"q":"Co-contraction agoniste/antagoniste :","o":["Mouvements rapides balistiques","Mouvements lents avec ↑ stabilité articulaire","Aucune activation","Inversion d'activation"],"r":1,"e":"Co-contraction = stabilité, mouvements lents.","s":0},{"q":"Innervation réciproque :","o":["Co-contraction","Inversion de l'activation agoniste/antagoniste (mouvements rapides, balistiques)","Aucune","Aléatoire"],"r":1,"e":"Réciproque = inversion → rapidité (sport, balistique).","s":0},{"q":"Contraction CONCENTRIQUE :","o":["Maintien","Diminution de longueur (raccourcissement)","Augmentation de longueur","Aucun changement"],"r":1,"e":"Concentrique = raccourcissement.","s":0},{"q":"Contraction EXCENTRIQUE :","o":["Diminution","Augmentation de longueur (allongement sous tension)","Maintien","Repos"],"r":1,"e":"Excentrique = allongement sous tension.","s":0},{"q":"Contraction ISOMÉTRIQUE :","o":["Diminution","Augmentation","Maintien (pas de mouvement, ↑ tension)","Aucune force"],"r":2,"e":"Isométrique = statique, pas de mouvement visible.","s":0},{"q":"Quel type de contraction ↑ la force avec la vitesse ?","o":["Concentrique","Excentrique","Isométrique","Aucune"],"r":1,"e":"Excentrique : ↑ force avec ↑ vitesse (concentrique ↓ force avec ↑ vitesse).","s":0},{"q":"L'isométrique ne doit pas dépasser :","o":["3 min","10 minutes","30 min","1 h"],"r":1,"e":"Isométrie : ≤ 10 min/séance, jamais en apnée.","s":0},{"q":"L'isocinétique est :","o":["Statique","Dynamique à vitesse constante (résistance variable)","Anaérobie pure","Sans matériel"],"r":1,"e":"Isocinétique : vitesse constante, résistance variable proportionnelle.","s":0},{"q":"Avantage majeur de l'isocinétique :","o":["Coût faible","Résistance variable proportionnelle à la force → force max à tous les angles","Pas besoin de matériel","Toujours fonctionnel"],"r":1,"e":"Isocinétique : force max à chaque degré de l'amplitude.","s":0},{"q":"L'isométrique a comme inconvénient majeur :","o":["Aucun","↑ travail cardiaque (Valsalva si apnée), gain limité à l'amplitude travaillée","Toujours douloureuse","Gain immédiat trop important"],"r":1,"e":"Isométrie : limites cardiovasculaires (apnée) et gain limité à l'angle travaillé.","s":0},{"q":"Force ANALYTIQUE :","o":["Groupe musculaire isolé (ex. extension du genou)","Modèle de mouvement complet","Aucune mesure","Force au quotidien"],"r":0,"e":"Analytique = muscle/groupe isolé.","s":0},{"q":"Le principe de surcharge suppose une exigence :","o":["Constante","Progressive","Décroissante","Maximale d'emblée"],"r":1,"e":"Pour augmenter force et résistance, le muscle doit être surchargé, mais de façon graduée.","s":0},{"q":"Les fibres de type IIa se caractérisent par une capillarisation :","o":["Faible","Élevée","Nulle","Variable selon l'âge"],"r":1,"e":"Elles partagent avec les fibres I une capillarisation et un taux de mitochondries élevés, mais s'en distinguent par une contraction rapide.","s":0},{"q":"L'excitabilité des fibres de type I est décrite comme :","o":["Tonique","Phasique","Intermédiaire","Absente"],"r":0,"e":"Les fibres IIb sont phasiques et les IIa intermédiaires.","s":0},{"q":"La myoglobine des fibres de type IIa est :","o":["Faible","Modérément élevée","Nulle","Identique à celle des IIb"],"r":1,"e":"Elle est élevée dans les fibres I et faible dans les fibres IIb.","s":0},{"q":"La voie anaérobie alactique fournit de l'énergie pendant :","o":["Une demi-seconde pour l'ATP et 2 à 10 secondes pour la créatine-phosphate","Jusqu'à 60 secondes","1 à 3 minutes","Plus de 3 minutes"],"r":0,"e":"Sa puissance est très élevée mais sa capacité très limitée.","s":0},{"q":"La voie aérobie se caractérise par :","o":["Une capacité illimitée et une puissance faible","Une capacité limitée et une puissance élevée","Une capacité et une puissance très élevées","Une durée inférieure à 30 secondes"],"r":0,"e":"La voie anaérobie alactique a au contraire une puissance très élevée pour une capacité très limitée.","s":0},{"q":"Une activité de 90 à 180 secondes, comme une course de 800 mètres ou la boxe, mobilise :","o":["L'ATP-PC seul","Les voies glycolytique et oxydative","La voie oxydative seule","La voie alactique"],"r":1,"e":"Au-delà de 3 minutes, la voie oxydative domine ; en deçà de 30 secondes, l'ATP-PC.","s":0},{"q":"Une activité de 30 à 90 secondes, comme un sprint de 400 mètres ou la natation, mobilise principalement :","o":["Le système ATP-PC","Le système glycolytique","Le système oxydatif","Aucun des trois"],"r":1,"e":"Le glycogène hépatique y est sollicité de 1 à 3 minutes, la voie couvrant jusqu'à 60 secondes.","s":0},{"q":"La co-contraction agoniste/antagoniste correspond à :","o":["Des mouvements lents, avec une stabilité articulaire accrue","Des mouvements rapides et balistiques","Une inversion de l'activation","Une contraction isolée"],"r":0,"e":"L'innervation réciproque, par inversion de l'activation, sous-tend au contraire les mouvements rapides et balistiques.","s":0},{"q":"La force analytique se travaille :","o":["Sur un groupe musculaire isolé, comme l'extension du genou","Sur un modèle de mouvement, comme le contrôle actif de l'épaule","En chaîne fermée uniquement","Avec un partenaire"],"r":0,"e":"La force fonctionnelle s'organise, elle, autour d'un modèle de mouvement.","s":0},{"q":"La contraction excentrique se caractérise, par rapport à la concentrique, par :","o":["Un gain de force à court terme et une acquisition précoce","Un gain de force à long terme et une acquisition plus tardive","Une moindre exigence de coordination","Une diminution de force avec la vitesse"],"r":1,"e":"Elle exige aussi davantage de coordination et voit sa force augmenter avec la vitesse.","s":0},{"q":"La contraction concentrique se caractérise par :","o":["Une augmentation de force avec la vitesse","Une diminution de force avec l'augmentation de la vitesse","Une longueur constante","Une vitesse constante imposée"],"r":1,"e":"Elle apporte un gain de force à court terme, s'acquiert plus tôt et exige moins de coordination.","s":0},{"q":"La contraction isométrique se caractérise sur le plan tissulaire par :","o":["Une modification de la taille des fibres","Aucune modification de la taille des fibres, mais une modification de la tension","Un allongement des fibres","Un raccourcissement des fibres"],"r":1,"e":"Elle est courante dans les muscles posturaux et stabilisateurs.","s":0},{"q":"Parmi les avantages de la contraction isométrique, le cours cite :","o":["Sa praticabilité n'importe où, un matériel minimal et un gain de force rapide","Un gain sur toute l'amplitude","Une variété importante","Une absence d'effet cardiaque"],"r":0,"e":"Ses inconvénients sont l'augmentation du travail cardiaque par l'apnée, la monotonie et un gain limité à l'amplitude travaillée.","s":0},{"q":"La durée totale de travail isométrique dans une séance ne doit pas dépasser :","o":["5 minutes","10 minutes","20 minutes","30 minutes"],"r":1,"e":"L'apnée y est par ailleurs proscrite, et un étirement avec relaxation est recommandé à la fin.","s":0},{"q":"La contraction isocinétique se définit par :","o":["Une charge constante","Une vitesse constante, par exemple 60°/s, avec une résistance variable","Une absence de mouvement","Une résistance constante"],"r":1,"e":"Elle peut être concentrique ou excentrique, la résistance étant proportionnelle à la force du patient.","s":0},{"q":"L'avantage majeur de l'isocinétique est :","o":["Une résistance variable proportionnelle à la force développée à chaque instant","Un coût réduit","Une praticabilité partout","L'absence de matériel"],"r":0,"e":"C'est ce qui permet de solliciter le muscle au maximum de ses possibilités sur toute l'amplitude.","s":0},{"q":"Le principe d'action retardée signifie que :","o":["Les résultats apparaissent en différé, par surcompensation","L'effort doit être différé","Le muscle se contracte avec retard","La récupération est immédiate"],"r":0,"e":"C'est ce qui justifie la planification des cycles d'entraînement et des périodes de récupération.","s":0},{"q":"Le principe de spécificité énonce que :","o":["Seuls les systèmes sollicités s'adaptent","Tous les systèmes s'adaptent simultanément","L'adaptation est générale","La surcharge suffit"],"r":0,"e":"L'entraînement doit donc respecter les besoins propres du muscle visé.","s":0},{"q":"Le principe de maintien ou réversibilité énonce que :","o":["Les gains sont définitifs","Si le muscle n'est pas exercé, il revient à son état initial","La force se maintient six mois","Seule la masse se perd"],"r":1,"e":"C'est l'argument central de la poursuite d'un entretien après la phase de gain.","s":0},{"q":"Selon l'ACSM, l'exercice est :","o":["Toute activité physique spontanée","Sous-catégorie d'activité physique planifiée, structurée, répétitive et intentionnelle","Sport de loisir","Travail manuel"],"r":1,"e":"Définition ACSM : planifié + structuré + répétitif + intentionnel.","s":1},{"q":"Composantes liées à la santé visées par l'exercice :","o":["Force (puissance/endurance)","Souplesse","Capacité aérobie","Composition corporelle","Couleur de peau"],"r":[0,1,2,3],"e":"4 composantes santé : force, souplesse, aérobie, composition.","s":1},{"q":"Aptitudes améliorées par l'exercice :","o":["Agilité","Coordination","Équilibre","Temps de réaction","Vitesse","Mémorisation"],"r":[0,1,2,3,4],"e":"5 aptitudes : agilité, coordination, équilibre, temps de réaction, vitesse.","s":1},{"q":"Combien de piliers comporte l'exercice thérapeutique ?","o":["3","4","5","7"],"r":2,"e":"5 piliers : Mobilité, Souplesse, Force, Pliométrie, RSM.","s":1},{"q":"Le 1er pilier de l'exercice thérapeutique est :","o":["Force","Souplesse","Mobilité","Pliométrie"],"r":2,"e":"Ordre : Mobilité → Souplesse → Force → Pliométrie → RSM.","s":1},{"q":"Le 5e pilier est :","o":["Force","Reprogrammation sensorimotrice (RSM/TSM)","Aérobie","Endurance"],"r":1,"e":"RSM = pilier 5, le plus avancé.","s":1},{"q":"L'exercice se distingue de l'activité physique générale par :","o":["L'intensité","Le caractère planifié, structuré et intentionnel","La durée","La compétition"],"r":1,"e":"Activité physique = tout mouvement. Exercice = sous-catégorie organisée.","s":1},{"q":"La force comprend :","o":["Vitesse seule","Puissance et endurance","Souplesse","Coordination"],"r":1,"e":"Force = capacité de tension ; comprend puissance + endurance.","s":1},{"q":"L'agilité fait partie des :","o":["Composantes liées à la santé","Aptitudes","Voies énergétiques","Tissus contractiles"],"r":1,"e":"Agilité = aptitude motrice (pas une composante santé).","s":1},{"q":"L'objectif global de l'exercice thérapeutique est :","o":["Performance sportive uniquement","Maintenir ou améliorer l'état de santé / capacités fonctionnelles","Compétition","Esthétique"],"r":1,"e":"Exercice thérapeutique = visée santé/fonction.","s":1},{"q":"La mobilité est centrée sur :","o":["L'amplitude articulaire (physiologie articulaire)","La force musculaire","La résistance cardio","La coordination fine"],"r":0,"e":"Mobilité = ROM, physiologie articulaire.","s":1},{"q":"La souplesse cible :","o":["Os","Fibre musculaire (longueur, alignement)","Liquide synovial","Cartilage"],"r":1,"e":"Souplesse = effet direct sur la fibre musculaire.","s":1},{"q":"La pliométrie utilise :","o":["Étirement lent","Pré-étirement rapide → cycle allongement/raccourcissement","Mouvement isométrique","Aucun étirement"],"r":1,"e":"Pliométrie : SSC (Stretch-Shortening Cycle).","s":1},{"q":"La RSM vise :","o":["La force","La qualité du mouvement (contrôle moteur, proprioception)","Le volume musculaire","L'esthétique"],"r":1,"e":"RSM = reprogrammation sensorimotrice, contrôle qualité.","s":1},{"q":"Pour la population générale, la répartition glucides est :","o":["20%","50%","80%","100%"],"r":1,"e":"Pop générale : glucides 50%, lipides 30%, protéines 15%.","s":1},{"q":"Pour le sportif, la répartition glucides est :","o":["20-30%","40%","60-70% (glycogène musculaire)","90%"],"r":2,"e":"Sportif : glucides 60-70%, protéines 12%.","s":1},{"q":"Recommandations nutritionnelles générales :","o":["Privilégier glucides complexes (digestion lente)","Lipides insaturés préférés","Fibres pour le transit","Sel modéré","Alcool en quantité","Hydratation"],"r":[0,1,2,3,5],"e":"Alcool = calories vides + diurétique → déshydratation.","s":1},{"q":"Avant une épreuve, privilégier des aliments :","o":["Lourds et copieux","Faciles à digérer","Très épicés","Riches en lipides"],"r":1,"e":"Aliments faciles à digérer pour ne pas surcharger.","s":1},{"q":"Ordre de digestion (le plus rapide en premier) :","o":["Lipides → protéines → glucides","Glucides complexes → protéines → lipides","Sucres → glucides complexes → protéines → lipides","Aléatoire"],"r":2,"e":"Sucres simples → glucides complexes → protéines → lipides.","s":1},{"q":"Préhydratation 10-15 min avant l'effort :","o":["100 mL","300 mL","600-800 mL","2 L"],"r":2,"e":"Préhydratation 600-800 mL (adultes).","s":1},{"q":"Pendant l'effort, hydratation :","o":["Aucune","Petites quantités toutes les 10-15 min","2 L d'un coup","Boisson alcoolisée"],"r":1,"e":"Petites quantités fractionnées toutes les 10-15 min.","s":1},{"q":"La réhydratation post-effort est :","o":["Inutile","Un aspect essentiel de la récupération","Réservée aux sportifs élite","Toujours par perfusion"],"r":1,"e":"Récupération = réhydratation essentielle.","s":1},{"q":"Rôles de l'eau dans l'exercice :","o":["Refroidissement corporel","Transport des nutriments","Maintien du volume sanguin","Production d'ATP","Réserve calorique"],"r":[0,1,2],"e":"L'eau ne produit pas d'ATP directement et ne stocke pas de calories.","s":1},{"q":"L'alcool agit comme :","o":["Hydratant","Diurétique (favorise la déshydratation)","Anti-inflammatoire","Anabolisant"],"r":1,"e":"Alcool = diurétique → ↑ pertes hydriques.","s":1},{"q":"Apports en lipides recommandés (pop. générale) :","o":["5%","30% (insaturés préférés)","60%","Aucun"],"r":1,"e":"Lipides ~30%, max 10% saturés.","s":1},{"q":"Protéines chez le sportif :","o":["1%","12%","30%","50%"],"r":1,"e":"Sportif : protéines 12%. Attention au fer et au calcium.","s":1},{"q":"Si problème d'HTA, l'apport en sel doit être :","o":["Libre","Augmenté","Modéré","Doublé"],"r":2,"e":"Sel : modération (encore plus si HTA).","s":1},{"q":"Les fibres alimentaires sont essentielles pour :","o":["L'énergie","Le transit intestinal","La force musculaire","La concentration"],"r":1,"e":"Fibres = transit intestinal.","s":1},{"q":"L'exercice thérapeutique doit-il être planifié ?","o":["Non, improvisation préférée","Oui, conformément à la définition ACSM (planifié, structuré, répétitif, intentionnel)","Seulement pour les sportifs","Uniquement en cas de douleur"],"r":1,"e":"Toujours planifié et structuré.","s":1},{"q":"Lequel n'est PAS un pilier ?","o":["Mobilité","Souplesse","Aérobie","Force","Pliométrie","RSM"],"r":2,"e":"L'aérobie est une voie énergétique, pas un pilier. Les 5 piliers : mobilité, souplesse, force, pliométrie, RSM.","s":1},{"q":"La définition ACSM de l'exercice le décrit comme une sous-catégorie d'activité physique qui est :","o":["Planifiée, structurée, répétitive et intentionnelle","Spontanée et quotidienne","Professionnelle","Exclusivement aérobie"],"r":0,"e":"C'est cette intentionnalité planifiée qui le distingue de l'activité physique générale.","s":1},{"q":"La capacité aérobie fait partie, selon l'ACSM :","o":["Des aptitudes","Des composantes liées à la santé","Des cinq piliers","Des qualités psychomotrices"],"r":1,"e":"Force, souplesse, capacité aérobie et composition corporelle sont les composantes liées à la santé ; agilité, coordination, équilibre, temps de réaction et vitesse sont les aptitudes.","s":1},{"q":"La composition corporelle est classée par l'ACSM parmi :","o":["Les aptitudes","Les composantes liées à la santé","Les piliers de l'exercice thérapeutique","Les facteurs de souplesse"],"r":1,"e":"Elle y figure aux côtés de la force, de la souplesse et de la capacité aérobie.","s":1},{"q":"Le temps de réaction est classé parmi :","o":["Les composantes liées à la santé","Les aptitudes","Les piliers de l'exercice thérapeutique","Les mécanismes énergétiques"],"r":1,"e":"Agilité, coordination, équilibre, temps de réaction et vitesse constituent les aptitudes.","s":1},{"q":"La force, dans les composantes liées à la santé, recouvre :","o":["La puissance et l'endurance","La seule force maximale","La vitesse","La coordination"],"r":0,"e":"Elle constitue l'un des cinq piliers de l'exercice thérapeutique et l'une des composantes liées à la santé.","s":1},{"q":"Le pilier « mobilité » vise :","o":["À maintenir ou améliorer l'amplitude articulaire, avec un effet direct sur la physiologie articulaire","À allonger les fibres musculaires","À augmenter la puissance","À reprogrammer le contrôle moteur"],"r":0,"e":"La souplesse, elle, agit directement sur la fibre musculaire.","s":1},{"q":"Le pilier « souplesse » agit directement sur :","o":["La physiologie articulaire","La fibre musculaire","Le système nerveux central","La composition corporelle"],"r":1,"e":"Elle vise l'amplitude articulaire par l'allongement de la fibre, ainsi que l'amélioration de la production motrice et la relaxation.","s":1},{"q":"Le pilier « pliométrie » repose sur :","o":["Un pré-étirement activant le cycle allongement/raccourcissement","Un maintien postural prolongé","Une mobilisation passive","Un étirement statique"],"r":0,"e":"Ses mouvements sont rapides et puissants, pour un coût métabolique réduit.","s":1},{"q":"Le pilier « reprogrammation sensorimotrice » vise :","o":["La quantité de force produite","La qualité du mouvement, avec un effet direct sur la physiologie neuromusculaire et le contrôle moteur","L'amplitude articulaire","La composition corporelle"],"r":1,"e":"C'est le cinquième pilier, développé par Vladimir Janda sous le nom d'entraînement sensorimoteur.","s":1},{"q":"L'ordre des cinq piliers tel que le cours les énonce est :","o":["Mobilité, souplesse, force, pliométrie, reprogrammation sensorimotrice","Force, mobilité, souplesse, RSM, pliométrie","Souplesse, force, mobilité, pliométrie, RSM","Pliométrie, force, mobilité, souplesse, RSM"],"r":0,"e":"Cette progression va du plus articulaire au plus neuromusculaire.","s":1},{"q":"L'acronyme FITT-VP, utilisé pour la prescription d'exercice, commence par :","o":["Force, intensité, temps, type","Fréquence, intensité, temps, type","Fonction, intensité, tolérance, technique","Fréquence, itération, temps, tâche"],"r":1,"e":"Les lettres V et P y ajoutent le volume et la progression.","s":1},{"q":"La pliométrie ne doit être introduite que si la zone concernée est :","o":["Encore œdématiée","Exempte d'œdème et de douleur, avec amplitude, force et souplesse normales","Immobilisée","Douloureuse mais mobile"],"r":1,"e":"Elle se situe en phase finale de récupération, après les autres piliers.","s":1},{"q":"L'agilité et la coordination se distinguent des composantes liées à la santé parce qu'elles relèvent :","o":["De la performance, donc des aptitudes","De la composition corporelle","Du système cardiovasculaire","De l'amplitude articulaire"],"r":0,"e":"Cette distinction structure toute la définition ACSM de l'exercice.","s":1},{"q":"Le caractère « structuré » de l'exercice, selon l'ACSM, signifie qu'il :","o":["Est organisé selon des paramètres définis, et non laissé au hasard","Se pratique en salle","Fait intervenir du matériel","Est encadré par un professionnel"],"r":0,"e":"Planification, structure, répétition et intentionnalité forment les quatre attributs de la définition.","s":1},{"q":"Le caractère « répétitif » de l'exercice implique :","o":["Une exécution unique","Une répétition nécessaire pour produire l'adaptation recherchée","Une monotonie imposée","Un travail exclusivement analytique"],"r":1,"e":"Sans répétition, aucune adaptation durable des systèmes sollicités n'est possible.","s":1},{"q":"L'objectif global de l'exercice, dans la définition ACSM, est :","o":["L'amélioration ou le maintien des composantes liées à la santé et des aptitudes","La seule performance sportive","La seule perte de poids","La seule prévention des chutes"],"r":0,"e":"L'exercice thérapeutique en constitue l'application clinique, organisée en cinq piliers.","s":1},{"q":"La mobilité, parmi les cinq piliers, se travaille selon le cours par :","o":["La thérapie manuelle en mobilité passive et l'exercice en mobilité active","Les seuls étirements","La seule pliométrie","Le seul travail en charge"],"r":0,"e":"La mobilité passive comprend elle-même les composantes accessoire et physiologique.","s":1},{"q":"L'équilibre, cité parmi les aptitudes, résulte de l'intégration :","o":["Des systèmes vestibulaire, visuel et proprioceptif","Du seul système vestibulaire","De la seule vision","De la seule force musculaire"],"r":0,"e":"C'est cette intégration que la reprogrammation sensorimotrice cherche à restaurer.","s":1},{"q":"La vitesse figure, dans la classification ACSM :","o":["Parmi les composantes liées à la santé","Parmi les aptitudes","Parmi les piliers","Parmi les voies énergétiques"],"r":1,"e":"Elle y côtoie l'agilité, la coordination, l'équilibre et le temps de réaction.","s":1},{"q":"L'exercice thérapeutique se distingue de l'exercice en général par :","o":["Son organisation en cinq piliers appliqués à une visée de rééducation","Son intensité plus élevée","Sa durée plus longue","L'absence de planification"],"r":0,"e":"Mobilité, souplesse, force, pliométrie et reprogrammation sensorimotrice en constituent le cadre.","s":1},{"q":"Les exercices de mobilité visent à :","o":["↑ la force musculaire","Maintenir/améliorer l'amplitude articulaire (physiologie articulaire)","↓ la masse osseuse","Augmenter la VO2max"],"r":1,"e":"Mobilité : effet direct sur l'amplitude et la physiologie articulaire.","s":2},{"q":"L'immobilisation peut être bénéfique pour :","o":["Le repos après blessure (cicatrisation)","Toujours néfaste","Renforcer le muscle","Augmenter la mobilité"],"r":0,"e":"Repos = bénéfique pour la cicatrisation initiale.","s":2},{"q":"Effets systémiques nuisibles de l'immobilisation :","o":["Musculo-squelettique","Cardiovasculaire","Respiratoire","Tégumentaire","Endocrinien"],"r":[0,1,2,3],"e":"4 grands systèmes affectés : MSK, CV, respi, tégumentaire.","s":2},{"q":"Effets MSK de l'immobilisation :","o":["↓ masse osseuse (ostéopénie)","Atrophie musculaire","↓ ROM","↑ masse graisseuse","↑ masse osseuse"],"r":[0,1,2,3],"e":"Tous sauf ↑ masse osseuse (qui diminue).","s":2},{"q":"Effets cardiovasculaires de l'immobilisation :","o":["↓ volume sanguin","↓ débit cardiaque","↑ retour veineux","Hypotension orthostatique","Thromboses veineuses profondes"],"r":[0,1,3,4],"e":"Retour veineux diminué, pas augmenté.","s":2},{"q":"Effets respiratoires de l'immobilisation :","o":["Pneumonies","Embolie pulmonaire","Asthme","BPCO"],"r":[0,1],"e":"Pneumonies et EP fréquentes. Asthme et BPCO sont chroniques préexistantes.","s":2},{"q":"L'effet local nuisible de l'immobilisation est :","o":["Renforcement musculaire","Modifications tissulaires (capsule, ligaments, tendons)","Augmentation de la ROM","Aucun"],"r":1,"e":"Local : capsule, ligaments, tendons s'altèrent (rétraction).","s":2},{"q":"Le tégumentaire peut être affecté par :","o":["Augmentation de la peau","Escarres","Cicatrisation accrue","Aucun problème"],"r":1,"e":"Immobilisation → escarres.","s":2},{"q":"Avantages de la mobilité :","o":["Indépendance et fonctionnalité","↑ et maintien de l'amplitude","Stimule la circulation/retour veineux","Charge nécessaire à l'os (prévention ostéoporose)","Prévient les escarres","Augmentation de la raideur capsulaire"],"r":[0,1,2,3,4],"e":"5 avantages majeurs. La raideur capsulaire résulte de l'immobilisation ; la mobilité la combat.","s":2},{"q":"Idées clés pour la mobilité active :","o":["Mouvement libre","Qualité du mouvement (schéma)","Amplitude","Force maximale","Répétition"],"r":[0,1,2,4],"e":"La force max n'est pas un objectif de la mobilité.","s":2},{"q":"En thérapie manuelle, la mobilité est :","o":["Active","Passive (accessoire + physiologique)","Volontaire","Réflexe"],"r":1,"e":"Thérapie manuelle = mobilité passive.","s":2},{"q":"En exercice, la mobilité est :","o":["Passive","Active (volontaire)","Réflexe","Imposée"],"r":1,"e":"Exercice = mobilité active.","s":2},{"q":"L'ostéoporose se prévient par :","o":["L'immobilisation","La charge mécanique sur l'os","Le repos","L'alcool"],"r":1,"e":"L'os a besoin de charges pour maintenir sa densité (loi de Wolff).","s":2},{"q":"L'hypotension orthostatique survient :","o":["Au repos","Au passage couché → debout après alitement prolongé","En position assise","En décubitus"],"r":1,"e":"Alitement → ↓ volume sanguin → hypotension orthostatique au levée.","s":2},{"q":"Les thromboses veineuses profondes (TVP) sont favorisées par :","o":["Mouvement","Stase veineuse (immobilisation)","Exercice","Hydratation"],"r":1,"e":"Stase veineuse = facteur principal de TVP (triade de Virchow).","s":2},{"q":"L'embolie pulmonaire est :","o":["Une infection","Complication d'une TVP, urgence vitale","Une allergie","Une rétention urinaire"],"r":1,"e":"EP : migration d'un thrombus de la TVP vers les artères pulmonaires.","s":2},{"q":"L'amplitude se perd à quelle vitesse en immobilisation ?","o":["Très lentement","Rapidement (atrophie musculaire, raccourcissement)","Jamais","Variable selon l'humeur"],"r":1,"e":"Pertes rapides : muscle (5% force/jour) + raccourcissement capsulo-ligamentaire.","s":2},{"q":"Pour prévenir les escarres lors d'immobilisation :","o":["Maintenir la même position","Redistribuer les pressions (mobilité, changements de position)","Aucune mesure","Compression continue"],"r":1,"e":"Redistribuer pressions par mobilité et changements de position.","s":2},{"q":"La mobilité active est :","o":["Réalisée par l'évaluateur","Réalisée volontairement par le patient","Sous anesthésie","Sans contrôle moteur"],"r":1,"e":"Active = par le patient lui-même.","s":2},{"q":"La mobilité passive est :","o":["Réalisée par le patient","Réalisée par l'évaluateur (segment proximal stabilisé)","Aucune mobilité","Mouvement réflexe"],"r":1,"e":"Passive = réalisée par l'évaluateur sans participation active.","s":2},{"q":"Un mouvement analytique cible :","o":["Plusieurs articulations en même temps","Une articulation/segment précis","Tout le corps","Aucune cible"],"r":1,"e":"Analytique = ciblé, articulation/segment isolé.","s":2},{"q":"Un mouvement fonctionnel intègre :","o":["Une seule articulation","Plusieurs articulations dans une tâche cohérente","Aucune articulation","Du repos"],"r":1,"e":"Fonctionnel = tâche globale, multi-articulaire (ex : se lever).","s":2},{"q":"L'atrophie musculaire en alitement :","o":["Touche le muscle striée","Touche surtout les muscles posturaux (type I) puis tous","Aucun effet musculaire","Augmente la force"],"r":1,"e":"Atrophie touche surtout les fibres lentes posturales d'abord.","s":2},{"q":"Quels facteurs limitent la perte de ROM en immobilisation ?","o":["Restriction stricte","Mobilisation précoce et régulière","Pression élevée","Compression durable"],"r":1,"e":"Mobilisation précoce préserve l'amplitude.","s":2},{"q":"L'augmentation de la masse graisseuse en immobilisation est due à :","o":["Renforcement","Baisse de la dépense énergétique sans baisse calorique","Alimentation seule","Activité"],"r":1,"e":"↓ DE sans ↓ alimentation → bilan calorique positif → ↑ graisse.","s":2},{"q":"L'objectif principal de la mobilité chez la personne alitée :","o":["Performance sportive","Maintenir l'indépendance et la fonctionnalité","Esthétique","Réduction du sommeil"],"r":1,"e":"Indépendance et fonctionnalité = priorité.","s":2},{"q":"Le mouvement libre désigne :","o":["Mouvement contre résistance","Mouvement sans résistance externe ni contrainte","Mouvement passif","Aucun mouvement"],"r":1,"e":"Libre = sans résistance externe.","s":2},{"q":"Indications principales de la mobilité :","o":["Post-immobilisation","Maladies chroniques","Personnes âgées","Sportif sain","Pré-opératoire"],"r":[0,1,2,4],"e":"Le sportif sain en bonne santé pratique mais c'est moins un objectif de soin.","s":2},{"q":"La mobilité contre-indications :","o":["Aucune","Fractures non consolidées, hémorragies actives","Toutes pathologies","Douleur légère"],"r":1,"e":"CI : fractures non consolidées, hémorragies, lésions instables.","s":2},{"q":"L'objectif premier de la mobilité après une chirurgie est :","o":["Renforcement maximal","Restaurer l'amplitude articulaire perdue, éviter les adhérences","Compétition","Esthétique"],"r":1,"e":"Post-chirurgie : récupérer ROM, prévenir adhérences.","s":2},{"q":"La mobilité se définit dans le cours comme un ensemble d'exercices visant à :","o":["Maintenir ou améliorer l'amplitude articulaire, avec des effets directs sur la physiologie articulaire","Allonger les fibres musculaires","Augmenter la puissance","Restaurer le contrôle moteur"],"r":0,"e":"C'est ce qui la distingue de la souplesse, dont l'effet porte directement sur la fibre musculaire.","s":2},{"q":"Parmi les effets musculo-squelettiques nuisibles de l'immobilisation, le cours cite :","o":["Une diminution de la masse osseuse, une atrophie musculaire, une diminution d'amplitude et une augmentation de la masse graisseuse","Une hypertrophie musculaire","Une augmentation de la densité osseuse","Une augmentation de l'amplitude"],"r":0,"e":"La diminution de masse osseuse conduit à l'ostéopénie puis à l'ostéoporose.","s":2},{"q":"Parmi les effets cardiovasculaires de l'immobilisation figurent :","o":["Une diminution du volume sanguin, du volume systolique, du débit cardiaque et du retour veineux","Une augmentation du débit cardiaque","Une hypertension","Une bradycardie isolée"],"r":0,"e":"S'y ajoutent l'hypotension orthostatique et les thromboses veineuses profondes.","s":2},{"q":"Les complications respiratoires de l'immobilisation citées sont :","o":["Les pneumonies et l'embolie pulmonaire","L'asthme","La bronchite chronique","L'apnée du sommeil"],"r":0,"e":"L'atteinte tégumentaire se manifeste, elle, par les escarres.","s":2},{"q":"Les effets locaux nuisibles de l'immobilisation concernent :","o":["Les tissus : capsule, ligaments et tendons","Le système cardiovasculaire","Le système respiratoire","La peau uniquement"],"r":0,"e":"Les effets systémiques touchent, eux, les appareils musculo-squelettique, cardiovasculaire, respiratoire et tégumentaire.","s":2},{"q":"L'immobilisation présente un effet bénéfique dans le cas :","o":["Du repos après blessure, pour la cicatrisation","De la prévention de l'ostéoporose","De l'entretien musculaire","De la circulation veineuse"],"r":0,"e":"C'est son seul bénéfice cité, à mettre en balance avec l'ensemble de ses effets nuisibles.","s":2},{"q":"Parmi les avantages de la mobilité, le cours cite le fait :","o":["De redistribuer la pression sur les surfaces et de prévenir les escarres","D'augmenter la masse musculaire","D'améliorer la capacité aérobie","De réduire la douleur nociceptive"],"r":0,"e":"S'y ajoutent l'indépendance fonctionnelle, l'entretien de l'amplitude, la stimulation circulatoire et la charge nécessaire à l'os.","s":2},{"q":"La mobilité apporte à l'os :","o":["La charge nécessaire à la prévention de l'ostéoporose","Un repos protecteur","Une décharge","Une immobilisation relative"],"r":0,"e":"L'immobilisation entraîne au contraire une diminution de la masse osseuse.","s":2},{"q":"Parmi les idées clés de la mobilité active figure :","o":["La qualité du mouvement, c'est-à-dire son schéma","La résistance maximale","La vitesse d'exécution maximale","L'apnée"],"r":0,"e":"S'y ajoutent le mouvement libre, l'amplitude, le caractère analytique et fonctionnel, général et spécifique, et la répétition.","s":2},{"q":"La mobilité active se travaille selon un mouvement :","o":["Analytique et fonctionnel, général et spécifique","Exclusivement analytique","Exclusivement fonctionnel","Exclusivement passif"],"r":0,"e":"Cette double lecture permet de relier le travail segmentaire à la tâche.","s":2},{"q":"En thérapie manuelle, la mobilité passive comprend :","o":["Les composantes accessoire et physiologique","La seule composante physiologique","La seule composante accessoire","Le renforcement"],"r":0,"e":"L'exercice relève, lui, de la mobilité active.","s":2},{"q":"L'hypotension orthostatique après immobilisation prolongée relève :","o":["Des effets musculo-squelettiques","Des effets cardiovasculaires","Des effets respiratoires","Des effets tégumentaires"],"r":1,"e":"Elle accompagne la diminution du volume sanguin, du volume systolique et du retour veineux.","s":2},{"q":"Les escarres relèvent des effets :","o":["Musculo-squelettiques","Cardiovasculaires","Respiratoires","Tégumentaires"],"r":3,"e":"La mobilité les prévient en redistribuant la pression sur les surfaces d'appui.","s":2},{"q":"L'augmentation de la masse graisseuse en immobilisation figure parmi les effets :","o":["Musculo-squelettiques","Cardiovasculaires","Tégumentaires","Locaux"],"r":0,"e":"Elle y accompagne la diminution de la masse maigre et de la force.","s":2},{"q":"La mobilité stimule notamment :","o":["La circulation et le retour veineux","La sécrétion hormonale","La digestion","La thermorégulation"],"r":0,"e":"C'est l'un des arguments de la mobilisation précoce chez le patient alité.","s":2},{"q":"Les thromboses veineuses profondes sont classées par le cours parmi les effets :","o":["Musculo-squelettiques","Cardiovasculaires","Respiratoires","Locaux"],"r":1,"e":"L'embolie pulmonaire, qui peut en résulter, est classée parmi les effets respiratoires.","s":2},{"q":"La mobilité contribue à l'indépendance du patient parce qu'elle :","o":["Maintient la fonctionnalité","Augmente la force maximale","Améliore la capacité aérobie","Réduit la douleur"],"r":0,"e":"Indépendance et fonctionnalité figurent en tête des avantages cités.","s":2},{"q":"Le mouvement libre, parmi les idées clés de la mobilité active, s'oppose :","o":["Au mouvement assisté ou contraint","Au mouvement analytique","Au mouvement fonctionnel","À la répétition"],"r":0,"e":"Il figure avec la qualité du mouvement, l'amplitude, le caractère analytique/fonctionnel et la répétition.","s":2},{"q":"L'atrophie musculaire liée à l'immobilisation se traduit par :","o":["Une diminution de la force et de la masse maigre","Une augmentation de la force","Une augmentation de la masse maigre","Une hypertrophie compensatrice"],"r":0,"e":"Elle s'accompagne d'une augmentation de la masse graisseuse.","s":2},{"q":"La perte d'amplitude articulaire en immobilisation est classée parmi les effets :","o":["Systémiques musculo-squelettiques","Cardiovasculaires","Locaux tissulaires uniquement","Tégumentaires"],"r":0,"e":"Les effets locaux tissulaires concernent, eux, la capsule, les ligaments et les tendons.","s":2},{"q":"La pliométrie correspond à :","o":["Étirement lent prolongé","Mouvements rapides et puissants utilisant un pré-étirement","Renforcement isométrique","Aucun étirement"],"r":1,"e":"Pliométrie = pré-étirement + contraction explosive.","s":3},{"q":"Le cycle activé par la pliométrie est :","o":["Cycle de Krebs","Cycle d'allongement/raccourcissement (SSC)","Cycle cardiaque","Cycle veineux"],"r":1,"e":"SSC = Stretch-Shortening Cycle.","s":3},{"q":"Caractéristiques de la pliométrie :","o":["↑ puissance et vitesse en intervalles courts","Coût métabolique réduit","Phase finale de récupération","Toujours en début de rééducation","Méthode aérobie pure"],"r":[0,1,2],"e":"Phase finale de récupération + ↑ puissance/vitesse en courts intervalles.","s":3},{"q":"Prérequis avant pliométrie :","o":["Exempt d'œdème","Exempt de douleur","ROM normale","Force et souplesse normales","Avoir 50 ans","Pas de prérequis"],"r":[0,1,2,3],"e":"4 prérequis : pas d'œdème, pas de douleur, ROM normale, force et souplesse normales.","s":3},{"q":"Modèle MÉCANIQUE de la pliométrie :","o":["Énergie électrique","Énergie élastique stockée dans le complexe muscle-tendon par étirement rapide, libérée à la contraction","Énergie chimique pure","Aucun stockage"],"r":1,"e":"Modèle mécanique = composante élastique des tendons.","s":3},{"q":"Modèle NEUROPHYSIOLOGIQUE de la pliométrie :","o":["Inhibition réflexe","Stimulation du fuseau musculaire → action réflexe → ↑ activité agoniste","Activation OTG","Inhibition réciproque pure"],"r":1,"e":"Fuseau réagit à l'étirement → réflexe myotatique → contraction agoniste.","s":3},{"q":"La pliométrie est utilisée pour :","o":["Récupération initiale post-traumatique","↑ puissance et explosivité","Étirement passif","Aucun objectif"],"r":1,"e":"↑ puissance, explosivité, performance sportive.","s":3},{"q":"Exemple typique d'exercice pliométrique :","o":["Squat lent","Drop jump, box jump, bondissements","Étirement maintenu","Marche lente"],"r":1,"e":"Drop jump, box jump, bondissements = pliométrie classique.","s":3},{"q":"Si la phase de couplage (étirement → contraction) est trop longue :","o":["Effet maximal","Énergie élastique perdue (chaleur) → effet diminué","Aucun effet","Effet inversé"],"r":1,"e":"Phase de couplage très brève (ms) sinon énergie dissipée.","s":3},{"q":"Le fuseau musculaire est sensible à :","o":["La température","L'étirement (vitesse et amplitude)","La pression sanguine","La lumière"],"r":1,"e":"Fuseau = récepteur d'étirement (vitesse + amplitude).","s":3},{"q":"Le réflexe myotatique est :","o":["Une contraction réflexe en réponse à un étirement","Une relaxation réflexe","Un tremblement","Un mouvement volontaire"],"r":0,"e":"Réflexe myotatique = contraction réflexe protectrice à l'étirement.","s":3},{"q":"La pliométrie nécessite une base de :","o":["Endurance pure","Force et souplesse","Aucune base","Seulement de l'agilité"],"r":1,"e":"Pliométrie en fin de récupération : nécessite force et souplesse comme base.","s":3},{"q":"La pliométrie est CONTRE-INDIQUÉE en :","o":["Phase de récupération avancée","Phase aiguë post-traumatique (œdème, douleur)","Performance sportive","Préparation physique"],"r":1,"e":"CI en phase aiguë : risque de récidive lésionnelle.","s":3},{"q":"Pourquoi le coût métabolique de la pliométrie est-il réduit ?","o":["Effort très faible","Réutilisation de l'énergie élastique stockée","Aucun travail réel","Anaérobie pure"],"r":1,"e":"Réutilisation énergie élastique = économie métabolique.","s":3},{"q":"Pour un sport de saut, la pliométrie :","o":["Inutile","Très utile pour ↑ détente","Toujours nocive","Pour faibles uniquement"],"r":1,"e":"Pliométrie idéale pour sports de saut.","s":3},{"q":"Pliométrie verticale typique :","o":["Marche","Squat jump, box jump","Course lente","Étirement"],"r":1,"e":"Squat/box jump = pliométrie verticale.","s":3},{"q":"Pliométrie horizontale typique :","o":["Étirement","Bondissements, foulées bondissantes","Squat","Pliage debout"],"r":1,"e":"Bondissements = pliométrie horizontale.","s":3},{"q":"L'efficacité de la pliométrie dépend de :","o":["Durée du cycle d'allongement/raccourcissement (couplage court)","Couleur des vêtements","Bruit ambiant","Aucun facteur"],"r":0,"e":"Couplage court (< 250 ms idéalement) = efficacité optimale.","s":3},{"q":"L'organe tendineux de Golgi (OTG) :","o":["Active la contraction","Détecte la tension tendineuse → inhibe la contraction (protection)","Stocke l'énergie","Aucun rôle"],"r":1,"e":"OTG = sécurité : inhibe la contraction si tension excessive.","s":3},{"q":"Type de fibres principalement sollicitées en pliométrie :","o":["Type I lentes","Type II rapides","Aucune","Toutes identiquement"],"r":1,"e":"Type II rapides (IIa et IIb) pour explosivité.","s":3},{"q":"En physiothérapie de rééducation post-blessure, la pliométrie intervient :","o":["Dès la phase aiguë","En phase finale de récupération (préparation au retour au sport)","Jamais","Avant tout exercice"],"r":1,"e":"Pliométrie = retour à la fonction sportive, phase tardive.","s":3},{"q":"Risque principal d'une pliométrie mal dosée :","o":["Pas de risque","Récidive lésionnelle, tendinopathies","Hypertension","Vertiges"],"r":1,"e":"Surcharge → lésion musculo-tendineuse (Achille, rotulien).","s":3},{"q":"La progression en pliométrie suit :","o":["Aléatoire","Bilatéral → unilatéral, faible → haute intensité, faible → grande hauteur","Inverse","Sans logique"],"r":1,"e":"Progression rigoureuse : du bilatéral peu intense vers unilatéral intense.","s":3},{"q":"Bénéfice neuromusculaire principal :","o":["↓ force","↑ recrutement des unités motrices rapides","Aucun bénéfice","Diminution explosivité"],"r":1,"e":"↑ recrutement UM rapides → explosivité.","s":3},{"q":"Différence pliométrie vs musculation classique :","o":["Aucune","Pliométrie utilise le SSC (pré-étirement rapide) ; musculation = surcharge lente","Identique","Inverse"],"r":1,"e":"Pliométrie = SSC ; musculation = surcharge progressive.","s":3},{"q":"Le temps de couplage idéal en pliométrie :","o":["1 sec","< 250 ms","5 sec","30 sec"],"r":1,"e":"< 250 ms = SSC court, efficace.","s":3},{"q":"En pliométrie, la phase excentrique :","o":["Inutile","Étirement rapide stockant l'énergie élastique","Aucun étirement","Concentrique"],"r":1,"e":"Phase excentrique = étirement rapide → stockage.","s":3},{"q":"En pliométrie, la phase concentrique :","o":["Aucun mouvement","Contraction explosive utilisant l'énergie élastique stockée","Allongement","Repos"],"r":1,"e":"Phase concentrique = explosion utilisant l'énergie stockée.","s":3},{"q":"La pliométrie améliore aussi :","o":["Rien","Coordination intermusculaire, recrutement neuromusculaire","Endurance cardio","Souplesse passive"],"r":1,"e":"Bénéfices neuromusculaires multiples.","s":3},{"q":"L'intégration de la pliométrie dans un programme :","o":["Quotidienne intensive","Modérée, progressive, espacée (récupération nécessaire)","Pas d'intégration","Aléatoire"],"r":1,"e":"Volumes contrôlés, récupération entre séances (impact articulaire).","s":3},{"q":"La pliométrie se définit comme un ensemble d'exercices :","o":["Lents et contrôlés","Rapides et puissants, utilisant un pré-étirement du muscle","Isométriques","Passifs"],"r":1,"e":"Ce pré-étirement active le cycle d'allongement/raccourcissement.","s":3},{"q":"La pliométrie augmente puissance et vitesse :","o":["Sur des intervalles courts","Sur des efforts prolongés","Sans limite de durée","Uniquement en endurance"],"r":0,"e":"Son coût métabolique est par ailleurs réduit, ce qui la distingue d'un travail en résistance classique.","s":3},{"q":"La pliométrie se situe dans la progression thérapeutique :","o":["En phase initiale","En phase finale de récupération","Avant la mobilité","Pendant l'immobilisation"],"r":1,"e":"Elle suppose une zone exempte d'œdème et de douleur, avec amplitude, force et souplesse normales.","s":3},{"q":"Parmi les prérequis à la pliométrie, le cours exige :","o":["Une zone exempte d'œdème et de douleur","Une force supérieure à la normale","Une amplitude supérieure à la normale","Un œdème résiduel toléré"],"r":0,"e":"S'y ajoutent une amplitude, une force et une souplesse normales.","s":3},{"q":"Dans le modèle mécanique de la pliométrie, l'énergie élastique est augmentée par :","o":["Un étirement lent","Un étirement rapide des composants musculo-tendineux","Une contraction isométrique","Un raccourcissement"],"r":1,"e":"Si cet étirement est suivi d'une contraction, l'énergie stockée est libérée et augmente la production totale de force.","s":3},{"q":"Dans le modèle neurophysiologique, l'étirement rapide stimule :","o":["L'organe tendineux de Golgi","Le fuseau musculaire","Les mécanorécepteurs cutanés","Le système vestibulaire"],"r":1,"e":"Il en résulte une action réflexe du muscle, une augmentation de l'activité de l'agoniste et donc de la force produite.","s":3},{"q":"Le cycle activé par le pré-étirement porte le nom de :","o":["Cycle d'allongement/raccourcissement","Cycle de Krebs","Cycle réflexe myotatique inverse","Cycle de co-contraction"],"r":0,"e":"Il est expliqué par deux modèles complémentaires : mécanique et neurophysiologique.","s":3},{"q":"Le coût métabolique réduit de la pliométrie s'explique par :","o":["La restitution d'énergie élastique stockée, qui n'exige pas de production métabolique supplémentaire","Une intensité faible","Des séries longues","L'absence de contraction"],"r":0,"e":"C'est l'un des trois arguments du cours, avec l'augmentation de puissance et de vitesse sur intervalles courts.","s":3},{"q":"L'énergie élastique stockée lors de la phase d'étirement :","o":["Est libérée si une contraction suit","Est dissipée dans tous les cas","Ne peut pas être restituée","Provient du métabolisme aérobie"],"r":0,"e":"C'est le cœur du modèle mécanique de la pliométrie.","s":3},{"q":"L'action réflexe décrite dans le modèle neurophysiologique augmente :","o":["L'activité du muscle agoniste","L'activité de l'antagoniste","L'inhibition de l'agoniste","La relaxation"],"r":0,"e":"Le fuseau musculaire, stimulé par l'étirement rapide, en est le point de départ.","s":3},{"q":"La pliométrie sollicite avant tout la qualité :","o":["D'endurance aérobie","De puissance","De souplesse","De mobilité articulaire"],"r":1,"e":"Elle augmente puissance et vitesse sur des intervalles courts.","s":3},{"q":"Le pré-étirement, dans la pliométrie, doit être :","o":["Lent et progressif","Rapide","Maintenu longuement","Passif"],"r":1,"e":"C'est la rapidité de l'étirement qui augmente l'énergie élastique et stimule le fuseau musculaire.","s":3},{"q":"La pliométrie s'inscrit, parmi les cinq piliers de l'exercice thérapeutique :","o":["En quatrième position, après la force","En première position","Avant la mobilité","À la place de la reprogrammation sensorimotrice"],"r":0,"e":"L'ordre est mobilité, souplesse, force, pliométrie, reprogrammation sensorimotrice.","s":3},{"q":"Les deux modèles explicatifs de la pliométrie sont :","o":["Le modèle mécanique et le modèle neurophysiologique","Le modèle métabolique et le modèle cardiovasculaire","Le modèle statique et le modèle dynamique","Le modèle local et le modèle global"],"r":0,"e":"Le premier repose sur l'énergie élastique, le second sur le fuseau musculaire et l'action réflexe.","s":3},{"q":"La normalité de la souplesse est exigée avant la pliométrie parce que :","o":["Le pré-étirement rapide sollicite le muscle en allongement","Elle diminue la force","Elle augmente le coût métabolique","Elle ralentit le mouvement"],"r":0,"e":"Amplitude, force et souplesse normales et absence d'œdème et de douleur constituent les prérequis cités.","s":3},{"q":"La production totale de force en pliométrie résulte :","o":["De la contraction volontaire seule","De la contraction volontaire augmentée de l'énergie élastique libérée et de l'action réflexe","Du seul réflexe","De la seule énergie élastique"],"r":1,"e":"Les deux modèles s'additionnent, l'un mécanique et l'autre neurophysiologique.","s":3},{"q":"La pliométrie agit sur les composants :","o":["Musculo-tendineux","Osseux","Capsulaires","Cutanés"],"r":0,"e":"C'est l'élasticité de ces composants qui stocke l'énergie lors de l'étirement rapide.","s":3},{"q":"Le caractère « puissant » des mouvements pliométriques signifie qu'ils associent :","o":["Force et vitesse","Force et endurance","Amplitude et lenteur","Résistance et isométrie"],"r":0,"e":"La puissance est précisément le produit de la force par la vitesse.","s":3},{"q":"L'exigence d'une amplitude normale avant la pliométrie tient au fait que :","o":["Le mouvement rapide s'effectue sur toute l'amplitude disponible","L'amplitude n'a pas d'importance","La pliométrie augmente l'amplitude","L'amplitude est travaillée en même temps"],"r":0,"e":"Une amplitude limitée exposerait à une contrainte en fin de course lors d'un mouvement rapide.","s":3},{"q":"Le fuseau musculaire, dans le modèle neurophysiologique, est sensible :","o":["À la tension tendineuse","À l'étirement rapide","À la température","À la compression articulaire"],"r":1,"e":"Sa stimulation déclenche l'action réflexe qui augmente la force produite.","s":3},{"q":"La RSM vise principalement :","o":["La force","La qualité du mouvement (physiologie neuromusculaire, contrôle moteur)","La VO2max","La masse musculaire"],"r":1,"e":"RSM = effet direct sur la physiologie neuromusculaire et le contrôle moteur.","s":4},{"q":"Les propriocepteurs incluent :","o":["Mécanorécepteurs articulaires (capsule, ligaments)","Récepteurs musculaires (fuseau, motoneurone gamma)","Récepteurs musculaires cutanés","Cônes et bâtonnets","Glandes endocrines"],"r":[0,1,2],"e":"Propriocepteurs : articulaires + musculaires + cutanés.","s":4},{"q":"Rôle des propriocepteurs :","o":["Régulation de la TA","Indiquer la position des segments dans l'espace et le temps","Sécrétion hormonale","Aucun rôle"],"r":1,"e":"Fondamentaux pour le contrôle moteur.","s":4},{"q":"Le cycle vicieux de l'instabilité commence par :","o":["Maladie cardiaque","Dysfonctionnement musculo-squelettique → ↓ proprioception","Stress mental","Hypoglycémie"],"r":1,"e":"Dysfonction MSK → ↓ proprio → perte d'activation/stabilisation → schéma moteur altéré.","s":4},{"q":"Stabilité STRUCTURELLE (passive) :","o":["Système sensorimoteur","Capsule, ligaments, congruence articulaire","Cerveau","Cœur"],"r":1,"e":"Passive = anatomie passive (capsule, ligaments, surfaces).","s":4},{"q":"Stabilité FONCTIONNELLE (active) :","o":["Anatomie pure","Système sensorimoteur, activation neuromusculaire, mécanismes locaux + globaux","Aucune","Liée uniquement à la posture"],"r":1,"e":"Active = dynamique, dépend des muscles et du SN.","s":4},{"q":"Stabilisation LOCALE :","o":["Réflexe","Circuit entre mécanorécepteurs articulaires et muscles","Réaction réflexe + vitesse de contraction > force","Stabilisation par chaînes globales","Schémas de co-contraction"],"r":[0,1,2,4],"e":"Locale : réflexe, vitesse > force, co-contraction. Globale = quadrants.","s":4},{"q":"Stabilisation GLOBALE :","o":["Réflexe articulaire isolé","Chaînes neuromusculaires : quadrant supérieur (scapulo-thoracique), quadrant inférieur (lombo-pelvienne)","Aucune","Cardiaque"],"r":1,"e":"Globale = stabilisation proximale par chaînes.","s":4},{"q":"Le quadrant supérieur correspond à :","o":["Lombo-pelvien","Scapulo-thoracique","Cervico-céphalique","Plantaire"],"r":1,"e":"Quadrant supérieur = stabilité scapulo-thoracique.","s":4},{"q":"Le quadrant inférieur correspond à :","o":["Scapulo-thoracique","Lombo-pelvien","Cervical","Pied uniquement"],"r":1,"e":"Quadrant inférieur = stabilité lombo-pelvienne.","s":4},{"q":"Les 3 systèmes intégrés pour l'équilibre :","o":["Vestibulaire","Visuel","Proprioceptif","Cardiaque","Digestif"],"r":[0,1,2],"e":"3 piliers de l'équilibre : vestibulaire + visuel + proprioceptif.","s":4},{"q":"Réactions d'équilibre automatiques :","o":["TT (tibio-tarsienne)","Hanche","Pas","Suspension","Genou"],"r":[0,1,2,3],"e":"4 réactions : TT, hanche, pas, suspension.","s":4},{"q":"Le TSM (entraînement sensorimoteur) a été développé par :","o":["George Maitland","Vladimir Janda (1928-2002)","Carl Kaltenborn","Robert Lovett"],"r":1,"e":"Janda = TSM, philosophie équilibre > force.","s":4},{"q":"Selon Janda, dans les activités fonctionnelles :","o":["La force prime","L'équilibre et la stabilisation réflexe sont plus importants que la force","L'aérobie prime","La souplesse seule prime"],"r":1,"e":"Janda : équilibre/stabilisation réflexe > force pure pour le quotidien.","s":4},{"q":"Avantages du TSM :","o":["↑ activité EMG","↑ équilibre et stabilité posturale","↑ proprioception","↓ chutes et récidives","Prévient les blessures sportives","↑ VO2max"],"r":[0,1,2,3,4],"e":"Pas d'effet direct sur la VO2max.","s":4},{"q":"3 points clés du TSM :","o":["Posture (pieds, lombaires, cervicales neutres)","Respiration (diaphragmatique)","Contrôle du centre de gravité","Apnée volontaire","Force maximale"],"r":[0,1,2],"e":"3 piliers : posture + respiration + contrôle CG.","s":4},{"q":"Le TSM commence à quel niveau ?","o":["Avec partenaire","Fonctionnel","Statique","Dynamique"],"r":2,"e":"Progression : Statique → Dynamique → Fonctionnel → Avec partenaire.","s":4},{"q":"Niveau STATIQUE :","o":["Mouvements MS/MI","Maintien équilibre sur surfaces instables, transferts de poids, yeux fermés","Mouvements fonctionnels","Activités en binôme"],"r":1,"e":"Statique : maintien sur surfaces instables progressives.","s":4},{"q":"Niveau DYNAMIQUE :","o":["Maintien statique","Mouvements MS et/ou MI tout en maintenant l'équilibre, bandes/ballons/poids","Sans matériel","Activités exclusivement assises"],"r":1,"e":"Dynamique : ajout de mouvements + matériel d'instabilité.","s":4},{"q":"Niveau FONCTIONNEL :","o":["Statique pur","Mouvements fonctionnels (squat, fente, step) sur surfaces instables","Sans charge","Inutile"],"r":1,"e":"Fonctionnel : tâches motrices complexes.","s":4},{"q":"Matériel typique du TSM :","o":["Surfaces en mousse","Planches d'équilibre","BOSU","Trampoline","Tapis de course","Haltères lourds"],"r":[0,1,2,3],"e":"4 matériels d'instabilité progressive. Pas tapis de course ni haltères lourds.","s":4},{"q":"Surfaces en mousse — code couleur de difficulté :","o":["Rouge → bleu → jaune","Verte → bleue → noire (difficulté croissante)","Aléatoire","Aucun code"],"r":1,"e":"Verte (plus dure) → bleue → noire (plus instable).","s":4},{"q":"L'instabilité progressive est obtenue par :","o":["Modification progressive de la BS (base de soutien) et du CG","Augmentation des charges","Ajout d'haltères uniquement","Sans variation"],"r":0,"e":"Progression : ↓ BS, déplacement CG, instabilité augmentée.","s":4},{"q":"Mécanismes locaux de stabilisation :","o":["Stabilisation articulaire réflexe","Circuit mécanorécepteurs → muscles péri-articulaires","Schémas de co-contraction","Stabilisation lombo-pelvienne globale","Réaction du quadrant supérieur"],"r":[0,1,2],"e":"Locaux : réflexes péri-articulaires. Globaux = chaînes.","s":4},{"q":"Le motoneurone gamma intervient dans :","o":["Le cœur","La régulation du fuseau musculaire (sensibilité à l'étirement)","La sécrétion d'adrénaline","La vision"],"r":1,"e":"Gamma = sensibilité du fuseau musculaire.","s":4},{"q":"Une dysfonction MSK altère la proprioception parce que :","o":["Aucun lien","Modifie l'afférence des mécanorécepteurs articulaires","Active uniquement les yeux","Sans rapport avec le SN"],"r":1,"e":"Lésion articulaire → ↓ informations proprioceptives → schémas moteurs altérés.","s":4},{"q":"Le TSM avec partenaire est :","o":["Niveau initial","Niveau avancé : activités en binôme/groupe sur surfaces instables","Inutile","Réservé aux enfants"],"r":1,"e":"Avec partenaire = niveau final, activités complexes en binôme.","s":4},{"q":"Le TSM aide à :","o":["Augmenter la force pure","↑ niveaux d'activité EMG, schémas d'activation, temps de réaction","Réduire la digestion","↓ tension artérielle"],"r":1,"e":"Bénéfices neuromusculaires (EMG, activation, vitesse).","s":4},{"q":"Pour la prévention des récidives, le TSM est :","o":["Inutile","Très efficace pour ↓ chutes et récidives","Dangereux","Sans preuve"],"r":1,"e":"Études soutiennent l'efficacité du TSM pour la prévention.","s":4},{"q":"Sur surface instable, la posture neutre des pieds, lombaires et cervicales est :","o":["Optionnelle","Essentielle (1er point clé Janda)","Inutile","À éviter"],"r":1,"e":"Posture neutre = base de stabilité réflexe.","s":4},{"q":"La reprogrammation sensorimotrice vise à maintenir ou améliorer :","o":["La qualité du mouvement, avec des effets directs sur la physiologie neuromusculaire et le contrôle moteur","L'amplitude articulaire","La longueur des fibres","La puissance"],"r":0,"e":"C'est le cinquième pilier de l'exercice thérapeutique.","s":4},{"q":"Les mécanorécepteurs articulaires siègent :","o":["Dans la capsule et les ligaments","Dans le tendon uniquement","Dans le muscle uniquement","Dans la peau uniquement"],"r":0,"e":"Les récepteurs musculaires, avec le motoneurone gamma, et les récepteurs cutanés complètent le système proprioceptif.","s":4},{"q":"Le rôle des propriocepteurs est d'indiquer :","o":["La position des segments dans l'espace et le temps","La force développée","La température","La douleur"],"r":0,"e":"Ils sont fondamentaux pour le contrôle et la qualité du mouvement.","s":4},{"q":"Le cycle vicieux de l'instabilité débute par :","o":["Un dysfonctionnement musculo-squelettique","Un programme moteur altéré","Un modèle de mouvement anormal","Une perte d'activation musculaire"],"r":0,"e":"Il entraîne une baisse de proprioception, puis une perte d'activation, un programme moteur altéré et un mouvement anormal — qui relance le cycle.","s":4},{"q":"La stabilité structurelle, dite passive, repose sur :","o":["La capsule, les ligaments et la congruence articulaire","Le système sensorimoteur","L'activation neuromusculaire","Les chaînes musculaires"],"r":0,"e":"La stabilité fonctionnelle, active, repose au contraire sur le système sensorimoteur et l'activation neuromusculaire.","s":4},{"q":"La stabilisation articulaire réflexe, mécanisme local, repose sur :","o":["Un circuit réflexe entre mécanorécepteurs articulaires et muscles entourant l'articulation","Les chaînes neuromusculaires proximales","Le système vestibulaire","La force maximale"],"r":0,"e":"Elle se réalise par des schémas de co-contraction.","s":4},{"q":"Dans la stabilisation réflexe locale, ce qui compte le plus est :","o":["La force elle-même","La réaction réflexe et la vitesse de contraction","L'amplitude disponible","L'endurance"],"r":1,"e":"C'est l'un des arguments centraux de Janda : l'équilibre et la stabilisation réflexe priment sur la force dans les activités fonctionnelles.","s":4},{"q":"La stabilisation globale du quadrant supérieur correspond à :","o":["La stabilité scapulo-thoracique","La stabilité lombo-pelvienne","La stabilité de la cheville","La stabilité cervicale"],"r":0,"e":"Le quadrant inférieur correspond, lui, à la stabilité lombo-pelvienne.","s":4},{"q":"Les réactions d'équilibre automatiques citées par le cours sont :","o":["Tibio-tarsienne, hanche, pas et suspension","Cheville et hanche uniquement","Pas et protection","Vestibulaire, visuelle et proprioceptive"],"r":0,"e":"L'équilibre lui-même résulte de l'intégration des systèmes vestibulaire, visuel et proprioceptif.","s":4},{"q":"Vladimir Janda a vécu de :","o":["1928 à 2002","1900 à 1975","1940 à 2010","1950 à 2015"],"r":0,"e":"Il a défendu l'idée que l'équilibre et la stabilisation réflexe importent davantage que la force dans les activités fonctionnelles.","s":4},{"q":"Parmi les avantages de l'entraînement sensorimoteur, le cours cite :","o":["Une augmentation des niveaux d'activité mesurés en EMG","Une augmentation de la masse musculaire","Une augmentation de l'amplitude passive","Une diminution du tonus"],"r":0,"e":"S'y ajoutent l'amélioration des schémas d'activation et des temps de réaction, de l'équilibre, de la proprioception et de la force.","s":4},{"q":"L'entraînement sensorimoteur permet notamment :","o":["De diminuer le risque de chutes et de récidives","D'augmenter la vitesse de course","D'augmenter la capacité aérobie","De réduire la masse grasse"],"r":0,"e":"Il prévient et réduit également les blessures sportives.","s":4},{"q":"Les trois points clés du TSM sont :","o":["Posture, respiration diaphragmatique et contrôle du centre de gravité","Force, vitesse et endurance","Amplitude, souplesse et force","Statique, dynamique et fonctionnel"],"r":0,"e":"La posture concerne les pieds, les lombaires et les cervicales, en position neutre ; le contrôle du centre de gravité s'accompagne de mouvements excentriques.","s":4},{"q":"Le niveau statique du TSM comprend notamment :","o":["Le maintien de l'équilibre sur surfaces instables progressives, les transferts de poids, la fermeture des yeux et l'appui unipodal","L'ajout de mouvements des membres","Des mouvements fonctionnels comme le squat","Des activités en binôme"],"r":0,"e":"Les mouvements de la tête et la variation des bases d'appui s'y ajoutent.","s":4},{"q":"Le niveau dynamique du TSM consiste à :","o":["Ajouter des mouvements des membres supérieurs et/ou inférieurs tout en maintenant l'équilibre","Maintenir une position statique","Réaliser des squats et des fentes","Travailler en binôme"],"r":0,"e":"Bandes, flexbars, ballons et poids légers y sont utilisés.","s":4},{"q":"Le niveau fonctionnel du TSM utilise :","o":["Des mouvements fonctionnels comme le squat, la fente et le step, sur surfaces instables progressives","Le seul maintien statique","Des mouvements des membres en position stable","Des activités de groupe"],"r":0,"e":"Le niveau avec partenaire ajoute ensuite des activités dynamiques en binôme ou en groupe.","s":4},{"q":"Le matériel du TSM comprend :","o":["Surfaces en mousse, planches d'équilibre, BOSU et trampoline","Haltères et barres","Élastiques uniquement","Tapis de course"],"r":0,"e":"Les surfaces en mousse sont codées par couleur — verte, bleue, noire — selon la difficulté.","s":4},{"q":"La progression complète du TSM est :","o":["Statique → dynamique → fonctionnel → avec partenaire","Fonctionnel → dynamique → statique","Dynamique → statique → fonctionnel","Avec partenaire → fonctionnel → statique"],"r":0,"e":"Chaque niveau s'accompagne de surfaces instables progressives.","s":4},{"q":"La respiration recommandée pendant le TSM est :","o":["Diaphragmatique","En apnée","Thoracique haute","Forcée"],"r":0,"e":"Elle figure parmi les trois points clés, avec la posture neutre et le contrôle du centre de gravité.","s":4},{"q":"La stabilité fonctionnelle repose sur des mécanismes :","o":["Locaux et globaux","Locaux uniquement","Globaux uniquement","Purement passifs"],"r":0,"e":"Les mécanismes locaux relèvent de la stabilisation articulaire réflexe, les globaux des chaînes neuromusculaires proximales.","s":4},{"q":"Les exercices de souplesse visent à :","o":["↑ la force","Maintenir/améliorer l'amplitude articulaire avec effet sur la fibre musculaire","↓ la masse osseuse","↑ la VO2max"],"r":1,"e":"Souplesse = amplitude + effet direct sur la fibre musculaire.","s":5},{"q":"La souplesse est la capacité à :","o":["Sauter haut","Effectuer des mouvements amples, autonomes ou sous influence externe","Tenir longtemps","Marcher loin"],"r":1,"e":"Souplesse = mouvements amples (autonomes ou assistés).","s":5},{"q":"Facteurs influençant la souplesse :","o":["Mobilité/stabilité","Âge / sexe","Hérédité","Entraînement / activité","Modifications post-traumatiques ou inactivité","Couleur des vêtements"],"r":[0,1,2,3,4],"e":"5 facteurs (sauf couleur des vêtements).","s":5},{"q":"L'étirement STATIQUE consiste à :","o":["Bouger en grand mouvement","Maintenir des postures impliquant un alignement musculaire","Sauter","Vibrer"],"r":1,"e":"Statique = maintien d'une posture.","s":5},{"q":"L'étirement DYNAMIQUE :","o":["Capacité à effectuer des mouvements de grande amplitude","Maintien fixe","Aucun mouvement","Vibration"],"r":0,"e":"Dynamique = mouvements amples actifs.","s":5},{"q":"L'étirement PASSIF :","o":["Modification autonome","Forces extérieures induisant la modification de la fibre","Aucune force","Étirement à vélocité"],"r":1,"e":"Passif : forces externes (kiné, gravité, partenaire).","s":5},{"q":"L'étirement ACTIF :","o":["Externe","Modification autonome (par le patient)","Sans contraction","Avec poids"],"r":1,"e":"Actif : par le patient sans aide externe.","s":5},{"q":"Avantages des étirements :","o":["↑ amplitude articulaire","↑ activation agoniste/antagoniste","↑ accumulation d'énergie élastique","↓ stress articulaire","↑ vascularisation musculaire","↓ risque lésionnel","Augmentation immédiate de la force maximale"],"r":[0,1,2,3,4,5],"e":"6 avantages majeurs des étirements. Un étirement statique prolongé diminue transitoirement la force et la puissance : c'est pourquoi on le place plutôt après l'effort.","s":5},{"q":"Effets sur le tissu CONTRACTILE :","o":["Aucun effet","↑ longueur/alignement des fibres musculaires","Casse les fibres","Atrophie"],"r":1,"e":"Tissu contractile : ↑ longueur/alignement des fibres.","s":5},{"q":"Effets sur le tissu CONJONCTIF :","o":["Faiblesse structurelle","Capacité de déformation accrue sans faiblesse","Rupture","Calcification"],"r":1,"e":"Tissu conjonctif : ↑ déformabilité, pas de faiblesse induite.","s":5},{"q":"Position recommandée pour l'étirement :","o":["Tendu, anxieux","Détendu, posture équilibrée et confortable","En apnée","Avec contraction maximale"],"r":1,"e":"Détendu + posture confortable favorisent l'étirement.","s":5},{"q":"Température recommandée :","o":["Froide","Adéquate (éviter le froid qui ↓ propriétés viscoélastiques)","Très chaude","Indifférente"],"r":1,"e":"Le froid ↓ les propriétés viscoélastiques → moins d'efficacité.","s":5},{"q":"L'étirement provoque :","o":["Une douleur intense","Une gêne, pas une douleur","Aucune sensation","Un spasme"],"r":1,"e":"Gêne = OK ; douleur = signe de lésion potentielle.","s":5},{"q":"L'effet sur l'énergie élastique :","o":["↓","↑ accumulation","Aucun","Annulation"],"r":1,"e":"Étirements → ↑ stockage d'énergie élastique.","s":5},{"q":"L'étirement permet :","o":["De passer rapidement du passif à l'actif","De rester passif uniquement","D'éliminer toute contraction","Aucun changement"],"r":0,"e":"Capacité à passer du passif à l'actif rapidement.","s":5},{"q":"Effet sur les contraintes articulaires :","o":["↑ stress","↓ forces de stress articulaire","Aucun effet","Compression accrue"],"r":1,"e":"Étirements → ↓ stress articulaire.","s":5},{"q":"Effet sur la vascularisation musculaire :","o":["↓","↑","Aucun","Variable"],"r":1,"e":"Étirements → ↑ vascularisation locale.","s":5},{"q":"Le risque de lésions musculo-tendineuses avec étirements :","o":["↑","↓","Inchangé","Imprédictible"],"r":1,"e":"Étirements → ↓ risque lésionnel global.","s":5},{"q":"Pour un mouvement de grande amplitude rapide, on utilise :","o":["Étirement statique","Étirement dynamique","Aucun étirement","Massage"],"r":1,"e":"Dynamique = entraînement à l'amplitude en mouvement.","s":5},{"q":"Pour induire la relaxation, on préfère :","o":["Dynamique rapide","Statique long","PNF intense","Vibration"],"r":1,"e":"Statique long et soutenu → relaxation.","s":5},{"q":"Le moment de la séance pour les étirements dépend :","o":["Toujours en début","Toujours en fin","Des objectifs (différents moments selon l'objectif)","D'aucune logique"],"r":2,"e":"Selon l'objectif : échauffement (dynamique), récupération (statique), etc.","s":5},{"q":"Un étirement actif est généralement :","o":["Plus risqué que passif","Plus sûr et autonome","Identique au passif","Inutile"],"r":1,"e":"Actif = patient contrôle la tension → plus sûr.","s":5},{"q":"L'effet activation agoniste/antagoniste :","o":["↓","↑ activation du couple","Aucun changement","Inversion"],"r":1,"e":"Étirements → ↑ activation du couple agoniste/antagoniste.","s":5},{"q":"Pour un objectif de souplesse à long terme :","o":["1 séance occasionnelle","Régularité (plusieurs fois par semaine)","Étirement violent","Vibration"],"r":1,"e":"La régularité est clé pour les gains à long terme.","s":5},{"q":"L'étirement passif est typiquement effectué par :","o":["Le patient seul","Le kinésithérapeute","Un appareil","Aucun"],"r":1,"e":"Passif : forces externes (kinésithérapeute, gravité).","s":5},{"q":"L'étirement statique impacte surtout :","o":["La force pure","La longueur tissulaire","La vitesse","Le poids"],"r":1,"e":"Statique : modification durable de la longueur tissulaire.","s":5},{"q":"Avant un sport explosif, on privilégie :","o":["Étirements statiques longs (qui peuvent ↓ la performance)","Étirements dynamiques","Aucun étirement","Massage profond"],"r":1,"e":"Dynamique avant sport (statique long peut ↓ explosivité).","s":5},{"q":"L'âge a un impact sur la souplesse :","o":["Aucun","↓ avec l'âge (mais maintenable par l'entraînement)","↑ avec l'âge","Sans relation"],"r":1,"e":"Souplesse ↓ avec l'âge, mais entraînement compense.","s":5},{"q":"L'inactivité prolongée induit :","o":["Souplesse maximale","↓ souplesse par modifications tissulaires","Aucun effet","↑ performance"],"r":1,"e":"Inactivité → raccourcissement musculaire → ↓ souplesse.","s":5},{"q":"Les femmes sont en général :","o":["Moins souples que les hommes","Plus souples que les hommes (différences hormonales/anatomiques)","Identiques","Plus souples uniquement à la naissance"],"r":1,"e":"Souplesse globalement plus élevée chez la femme (laxité ligamentaire, hormones).","s":5},{"q":"Les exercices de souplesse visent, outre l'amplitude articulaire :","o":["À améliorer la production motrice et à induire une relaxation","À augmenter la puissance","À augmenter la masse musculaire","À améliorer la capacité aérobie"],"r":0,"e":"Leur effet porte directement sur la fibre musculaire, contrairement à la mobilité qui agit sur la physiologie articulaire.","s":5},{"q":"La souplesse se définit comme la capacité à effectuer des mouvements amples :","o":["De façon autonome ou sous influence externe","De façon autonome uniquement","Sous influence externe uniquement","À vitesse constante"],"r":0,"e":"Elle s'accompagne d'une augmentation de la longueur et de l'alignement des fibres musculaires.","s":5},{"q":"Parmi les facteurs influençant la souplesse, le cours cite :","o":["La mobilité/stabilité, l'âge, le sexe, l'hérédité, l'entraînement et les modifications post-traumatiques ou d'inactivité","La seule hérédité","Le seul entraînement","La seule température"],"r":0,"e":"Cette pluralité explique les grandes différences interindividuelles.","s":5},{"q":"L'étirement dynamique se définit comme :","o":["Le maintien de postures alignant le muscle","La capacité à effectuer des mouvements de grande amplitude","Une force extérieure modifiant la fibre","Une modification autonome de la fibre"],"r":1,"e":"L'étirement statique consiste, lui, à maintenir des postures impliquant un alignement musculaire.","s":5},{"q":"L'étirement passif se définit comme :","o":["Une modification autonome de la fibre","Des forces extérieures induisant la modification de la fibre","Un maintien de posture","Un mouvement de grande amplitude"],"r":1,"e":"L'étirement actif correspond, lui, à une modification autonome de la fibre.","s":5},{"q":"Parmi les avantages de la souplesse, le cours cite :","o":["L'augmentation de l'accumulation d'énergie élastique","L'augmentation de la masse musculaire","L'augmentation de la force maximale","L'amélioration du débit cardiaque"],"r":0,"e":"S'y ajoutent l'augmentation de l'amplitude, de l'activation du couple agoniste/antagoniste et de la vascularisation musculaire.","s":5},{"q":"La souplesse améliore la capacité à :","o":["Passer rapidement du passif à l'actif","Maintenir une contraction isométrique longue","Produire une force maximale","Augmenter la fréquence cardiaque"],"r":0,"e":"Elle permet également d'induire la relaxation et de diminuer les forces de stress articulaire.","s":5},{"q":"L'effet de l'étirement sur le tissu contractile est :","o":["Une augmentation de la longueur et de l'alignement des fibres musculaires","Une diminution de la longueur","Une rupture des fibres","Une hypertrophie"],"r":0,"e":"Sur le tissu conjonctif intramusculaire et tendineux, l'effet est une capacité de déformation accrue.","s":5},{"q":"L'effet de l'étirement sur le tissu conjonctif se fait :","o":["Avec un affaiblissement structurel","Sans induction de faiblesse structurelle","Par rupture des fibres de collagène","Par diminution de la déformabilité"],"r":1,"e":"Cette précision du cours répond à la crainte classique d'un tendon fragilisé par l'étirement.","s":5},{"q":"Le froid, dans le contexte de l'étirement :","o":["Augmente les propriétés viscoélastiques","Diminue les propriétés viscoélastiques","Est sans effet","Améliore l'amplitude"],"r":1,"e":"C'est pourquoi le cours recommande une température adéquate avant d'étirer.","s":5},{"q":"L'étirement doit provoquer :","o":["Une douleur franche","Une gêne, mais pas une douleur","Aucune sensation","Une brûlure"],"r":1,"e":"Cette distinction constitue le repère de dosage principal de la séance d'étirement.","s":5},{"q":"La position recommandée pour l'étirement est :","o":["Patient détendu, posture équilibrée et confortable","Patient en contraction active","Patient en appui unipodal","Patient en apnée"],"r":0,"e":"Le relâchement conditionne l'accès au tissu contractile plutôt que la lutte contre une contraction de défense.","s":5},{"q":"Le moment de la séance où placer les étirements :","o":["Est toujours le début","Est toujours la fin","Dépend des objectifs","Est indifférent"],"r":2,"e":"Le cours indique explicitement des moments différents selon les objectifs poursuivis.","s":5},{"q":"La souplesse diminue les forces :","o":["De stress articulaire","De contraction musculaire","De réaction du sol","De cisaillement tendineux uniquement"],"r":0,"e":"Elle diminue aussi le risque de lésions musculo-tendineuses et augmente la vascularisation musculaire.","s":5},{"q":"L'augmentation de l'activation du couple agoniste/antagoniste par la souplesse traduit :","o":["Un effet neuromusculaire, et non uniquement tissulaire","Un effet purement mécanique","Une hypertrophie","Un effet cardiovasculaire"],"r":0,"e":"Cet effet complète l'allongement des fibres et la déformabilité du tissu conjonctif.","s":5},{"q":"Les modifications post-traumatiques influencent la souplesse au même titre que :","o":["L'inactivité","La fréquence cardiaque","La capacité aérobie","La composition corporelle"],"r":0,"e":"Les deux figurent dans le même item de la liste des facteurs influençant la souplesse.","s":5},{"q":"L'étirement statique se caractérise par :","o":["Le maintien de postures impliquant un alignement musculaire","Des mouvements de grande amplitude","Une force externe","Une contraction-relâchement"],"r":0,"e":"Il s'oppose à l'étirement dynamique dans la classification par description du mouvement.","s":5},{"q":"La classification des étirements du cours distingue :","o":["Statique, dynamique, passif et actif","Statique et balistique seulement","Passif et PNF seulement","Actif et isométrique"],"r":0,"e":"Les deux premiers décrivent le mouvement, les deux suivants l'origine de la force appliquée.","s":5},{"q":"L'augmentation de la vascularisation musculaire figure parmi :","o":["Les avantages des étirements","Les facteurs influençant la souplesse","Les effets sur le tissu conjonctif","Les idées clés de la séance"],"r":0,"e":"Elle y côtoie la diminution du risque de lésions musculo-tendineuses.","s":5},{"q":"La souplesse se définit sur le plan tissulaire par :","o":["Une augmentation de la longueur et de l'alignement des fibres musculaires","Une augmentation du nombre de fibres","Une augmentation de la section du muscle","Une diminution du tissu conjonctif"],"r":0,"e":"C'est l'effet direct sur la fibre qui la distingue de la mobilité.","s":5},{"q":"L'étymologie de « goniométrie » signifie :","o":["Articulation + mesure","Angle + mesure","Mouvement + mesure","Force + mesure"],"r":1,"e":"Du grec : gonion (angle) + metron (mesure).","s":6},{"q":"La goniométrie est indiquée dans quelles situations ?","o":["Postopératoire (suture méniscale)","Douleur chronique (coude)","Après un AVC","Après hospitalisation prolongée avec alitement","Pour un patient asymptomatique"],"r":[0,1,2,3],"e":"Indications : postop, douleur chronique, AVC, alitement. Pas pour un patient asymptomatique sans plainte.","s":6},{"q":"La goniométrie se réalise :","o":["Avant tout examen","Après l'examen subjectif, l'observation et la palpation","Sans examen préalable","Uniquement au laboratoire"],"r":1,"e":"Examen subjectif → observation → palpation → goniométrie.","s":6},{"q":"Parmi les objectifs de la goniométrie :","o":["Déterminer la présence de lésions","Établir un diagnostic kinésithérapique","Évaluer les progrès","Adapter les orthèses/prothèses","Diagnostiquer un cancer"],"r":[0,1,2,3],"e":"4 objectifs principaux. Le diagnostic de cancer relève de la médecine.","s":6},{"q":"Les articulations fibreuses incluent :","o":["Synchondrose","Symphyse","Suture plate, squameuse, dentelée, syndesmose","Articulation synoviale"],"r":2,"e":"Fibreuses : sutures et syndesmoses. Cartilagineuses : synchondrose/symphyse.","s":6},{"q":"Les articulations synoviales contiennent :","o":["Du tissu osseux uniquement","Cartilage articulaire, cavité, capsule, liquide synovial, ligaments","Du tissu fibreux uniquement","De la moelle osseuse"],"r":1,"e":"Articulations synoviales : 5 éléments + parfois disques/ménisques/membranes.","s":6},{"q":"Le glissement est un déplacement :","o":["Axial autour d'un axe","Linéaire","Angulaire","De compression"],"r":1,"e":"Glissement = déplacement linéaire (translation).","s":6},{"q":"Le roulement correspond à :","o":["Un déplacement linéaire","Un déplacement axial","Un déplacement angulaire","Une rotation pure"],"r":2,"e":"Roulement = déplacement angulaire. Rotation = axiale autour d'un axe fixe.","s":6},{"q":"Que se passe-t-il pour l'amplitude lorsqu'il y a combinaison glissement + roulement ?","o":["Elle diminue","Elle reste identique","Elle augmente","Elle s'inverse"],"r":2,"e":"La combinaison glissement + roulement augmente l'amplitude articulaire.","s":6},{"q":"L'AROM correspond à :","o":["Amplitude active produite volontairement","Amplitude passive par l'évaluateur","Amplitude active assistée","Amplitude maximale"],"r":0,"e":"AROM = Active Range Of Motion, produite volontairement sans assistance.","s":6},{"q":"Normalement, on observe :","o":["PROM < AROM","PROM > AROM","PROM = AROM","Aucune relation"],"r":1,"e":"PROM > AROM car indépendante de la force musculaire et de la cognition.","s":6},{"q":"Une douleur en AROM oriente vers une atteinte :","o":["Des tissus contractiles (muscles, tendons)","De la capsule uniquement","Des ligaments uniquement","Du cartilage uniquement"],"r":0,"e":"AROM teste les structures contractiles : muscles et tendons.","s":6},{"q":"Le PROM permet d'évaluer :","o":["Les surfaces articulaires","La capsule","Les ligaments","Les fascias et la peau","La force musculaire"],"r":[0,1,2,3],"e":"PROM évalue les tissus non contractiles. La force se teste avec AROM/résistance.","s":6},{"q":"Le plan sagittal divise le corps :","o":["En antérieur et postérieur","En droite et gauche","En supérieur et inférieur","En interne et externe"],"r":1,"e":"Plan sagittal (médian) : droite/gauche. Axe médial-latéral.","s":6},{"q":"Dans quel plan se produit la flexion ?","o":["Frontal","Transversal","Sagittal","Aucun"],"r":2,"e":"Flexion et extension = plan sagittal, axe médial-latéral.","s":6},{"q":"L'abduction et l'adduction se font dans le plan :","o":["Sagittal","Frontal","Transversal","Axial"],"r":1,"e":"Frontal (coronal), axe antéro-postérieur.","s":6},{"q":"Les rotations médiale/latérale se produisent dans le plan :","o":["Sagittal","Frontal","Transversal (axial)","Aucun"],"r":2,"e":"Plan transversal autour de l'axe vertical.","s":6},{"q":"La position de référence pour toute mesure ROM est :","o":["Position de repos","Position fonctionnelle","Position anatomique","Position de Trendelenburg"],"r":2,"e":"Position anatomique (ou neutre pour les rotations).","s":6},{"q":"Facteurs influençant la ROM :","o":["Âge","Sexe","IMC","Heure de la journée","Couleur des vêtements","Expérience de l'évaluateur"],"r":[0,1,2,3,5],"e":"Tous sauf la couleur des vêtements.","s":6},{"q":"L'hypomobilité est :","o":["Une augmentation de l'amplitude","Une diminution substantielle de l'amplitude","Une absence complète de mouvement","Un mouvement instable"],"r":1,"e":"Hypomobilité = ↓ ROM par rapport aux valeurs de référence.","s":6},{"q":"Causes de l'hypomobilité :","o":["Douleur","Raccourcissement musculaire","Inflammation","Immobilisation","Marfan"],"r":[0,1,2,3],"e":"Marfan → hypermobilité par laxité. Les autres causent l'hypomobilité.","s":6},{"q":"L'hypermobilité est typiquement associée à :","o":["L'arthrose","Le syndrome de Marfan","La capsulite rétractile","L'ostéoporose"],"r":1,"e":"Marfan → laxité tissulaire → hypermobilité ligamentaire.","s":6},{"q":"Qui a décrit les types d'end-feel ?","o":["Mulligan, Maitland, McKenzie","Cyriax, Kaltenborn, Paris","Janda, Lewit, Jull","Kendall, Daniels, Worthingham"],"r":1,"e":"Cyriax, Kaltenborn, Paris sont les auteurs majeurs.","s":6},{"q":"Un end-feel souple normal correspond à :","o":["Étirement musculaire","Approximation des tissus mous","Contact os-os","Spasme"],"r":1,"e":"Ex : flexion du genou (mollet contre cuisse).","s":6},{"q":"Un end-feel ferme normal correspond à :","o":["Approximation des tissus mous","Étirement des tissus non contractiles","Contact os-os","Spasme protecteur"],"r":1,"e":"Étirement capsulaire/ligamentaire (ex : flexion hanche genou tendu).","s":6},{"q":"Un end-feel dur normal correspond à :","o":["Tissus mous","Tissus non contractiles","Contact os contre os","Spasme"],"r":2,"e":"Ex : extension du coude (olécrane vs fosse olécranienne).","s":6},{"q":"L'end-feel « vide » indique :","o":["Une articulation normale","Une pathologie grave (inflammation aiguë, bursite, fracture)","Une raideur capsulaire","Une simple hypomobilité"],"r":1,"e":"End-feel vide = douleur intense empêche le mouvement. CI à la mobilisation.","s":6},{"q":"Un end-feel « spasme » signe :","o":["Une déchirure musculaire","Une réaction protectrice à la douleur","Une fracture","Une luxation"],"r":1,"e":"Spasme = arrêt brutal par contraction réflexe protectrice.","s":6},{"q":"Un end-feel « ressort » (mola) évoque :","o":["Une articulation normale","Un corps libre intra-articulaire ou lésion méniscale","Une raideur ligamentaire","Une bursite"],"r":1,"e":"End-feel ressort = rebond. Mobilisation contre-indiquée.","s":6},{"q":"L'arthrocinématique étudie :","o":["Le mouvement osseux global","Les mouvements intra-articulaires entre surfaces","Les forces musculaires","La conduction nerveuse"],"r":1,"e":"Arthrocinématique = mouvements entre les surfaces articulaires (glissement/roulement/rotation).","s":6},{"q":"Parmi les situations d'indication de la goniométrie, le cours cite :","o":["Le postopératoire, la douleur chronique, l'après-AVC et l'hospitalisation prolongée avec alitement","Le seul postopératoire","Le bilan sportif","Le dépistage scolaire"],"r":0,"e":"La suture méniscale et la sternotomie médiane sont les exemples postopératoires donnés.","s":6},{"q":"Parmi les objectifs de la goniométrie, le cours cite :","o":["La fabrication d'orthèses et prothèses et l'adaptation des équipements","La mesure de la force","L'évaluation de l'endurance","Le dosage de l'effort"],"r":0,"e":"S'y ajoutent le diagnostic, le pronostic, le suivi des progrès, la modification du traitement, la motivation et l'étude de l'efficacité des techniques.","s":6},{"q":"Les articulations fibreuses comprennent :","o":["La suture plate, la suture squameuse, la suture dentelée et la syndesmose","La synchondrose et la symphyse","Le cartilage articulaire et la capsule","Les disques et les ménisques"],"r":0,"e":"Synchondrose et symphyse sont cartilagineuses ; les synoviales comportent cartilage, cavité, capsule, liquide synovial et ligaments.","s":6},{"q":"Les trois types de mouvements possibles d'un segment osseux sont :","o":["Glissement, rotation et roulement","Flexion, extension et rotation","Translation, compression et traction","Abduction, adduction et circumduction"],"r":0,"e":"Le glissement est un déplacement linéaire, la rotation un déplacement axial autour d'un axe fixe et le roulement un déplacement angulaire.","s":6},{"q":"Dans le corps, la combinaison glissement + roulement :","o":["Augmente l'amplitude articulaire","Diminue l'amplitude","Bloque le mouvement","Est sans effet"],"r":0,"e":"Glissements, rotations et roulements s'y combinent systématiquement.","s":6},{"q":"L'amplitude de mouvement se définit comme :","o":["L'arc en degrés entre le début et la fin du mouvement dans un plan donné","La force maximale développée","La vitesse du mouvement","Le nombre de répétitions possibles"],"r":0,"e":"Elle se décline en AROM active, PROM passive et AAROM active assistée.","s":6},{"q":"L'AAROM, amplitude active assistée :","o":["Est mesurée systématiquement","N'est habituellement pas mesurée","Remplace la PROM","Est toujours supérieure à la PROM"],"r":1,"e":"Elle correspond au mouvement produit par le patient avec assistance.","s":6},{"q":"L'AROM dépend notamment :","o":["De la force et de la cognition","De la seule capsule","Des seuls ligaments","De la seule capsule et des fascias"],"r":0,"e":"La PROM, indépendante de la force, est normalement supérieure à l'AROM.","s":6},{"q":"Une douleur en PROM oriente vers :","o":["Un étirement ou un pincement de tissus non contractiles","Une contraction de tissus contractiles","Une atteinte purement nerveuse","Une simulation"],"r":0,"e":"La PROM évalue les surfaces articulaires, la capsule, les ligaments, les fascias et la peau.","s":6},{"q":"Le plan frontal est orienté :","o":["Verticalement, divisant antérieur et postérieur","Verticalement, divisant droite et gauche","Horizontalement","Obliquement"],"r":0,"e":"Son axe est antéro-postérieur ; s'y produisent abduction, adduction et déviations radiale et cubitale.","s":6},{"q":"L'axe du plan sagittal est :","o":["Médial-latéral","Antéro-postérieur","Vertical crânio-caudal","Oblique"],"r":0,"e":"Flexion et extension s'y produisent ; le plan transversal a un axe vertical crânio-caudal.","s":6},{"q":"La pronation et la supination se produisent dans le plan :","o":["Sagittal","Frontal","Transversal","Oblique"],"r":2,"e":"S'y produisent également les rotations médiale et latérale et les abduction-adduction horizontales.","s":6},{"q":"Parmi les facteurs influençant l'amplitude articulaire, le cours cite :","o":["L'heure de la journée et l'expérience de l'évaluateur","La seule pathologie","Le seul âge","La seule force musculaire"],"r":0,"e":"S'y ajoutent l'âge, le sexe, l'IMC, le caractère actif ou passif, les activités, la position de test et le type d'instrument.","s":6},{"q":"Parmi les causes d'hypomobilité, le cours cite :","o":["La douleur, le raccourcissement musculaire ou capsulaire, l'inflammation et les suites d'immobilisation","La laxité des tissus mous","L'hypotonie","Le syndrome de Marfan"],"r":0,"e":"S'y ajoutent les maladies orthopédiques, métaboliques et neurologiques, la perte de mouvement volontaire, les déformations osseuses et l'hypertonicité.","s":6},{"q":"Parmi les causes d'hypermobilité, le cours cite :","o":["La laxité des tissus mous, les anomalies des surfaces articulaires, le traumatisme, le syndrome de Marfan, l'hypotonie et l'hyperlaxité","Le raccourcissement capsulaire","L'hypertonicité","L'inflammation"],"r":0,"e":"Elle se définit par une augmentation de l'amplitude au-delà des valeurs de référence.","s":6},{"q":"Les auteurs cités pour la description de l'end-feel sont :","o":["Cyriax, Kaltenborn et Paris","Kendall et McCreary","Daniels et Worthingham","Lovett et Janda"],"r":0,"e":"L'end-feel désigne la barrière perçue par l'évaluateur, caractéristique de la structure qui limite l'amplitude.","s":6},{"q":"Un end-feel ferme anormal évoque :","o":["Un œdème ou une synovite","Une augmentation du tonus ou un raccourcissement capsulaire, musculaire ou ligamentaire","Une chondromalacie","Une inflammation aiguë"],"r":1,"e":"Un end-feel souple anormal évoque œdème et synovite, un dur anormal chondromalacie, arthrose, fragments libres ou fracture.","s":6},{"q":"Devant un end-feel « ressort » (mola), le cours précise que :","o":["La mobilisation est contre-indiquée","La mobilisation doit être intensifiée","Il s'agit d'un end-feel normal","Il traduit une simple appréhension"],"r":0,"e":"Il évoque un corps libre intra-articulaire ou une lésion méniscale ; il ne faut par ailleurs pas confondre un end-feel avec une interruption due à l'inquiétude.","s":6},{"q":"La cinématique, telle que définie dans ce cours, décrit le mouvement :","o":["Sans considérer les forces","En intégrant les forces","À partir de la seule force musculaire","À partir de l'électromyographie"],"r":0,"e":"L'arthrocinématique en constitue l'application aux surfaces articulaires : glissement, rotation et roulement.","s":6},{"q":"Le plan transversal est orienté :","o":["Verticalement","Horizontalement, divisant supérieur et inférieur","Obliquement","Selon l'axe médial-latéral"],"r":1,"e":"Son axe est vertical, crânio-caudal ; le plan sagittal divise droite et gauche et le plan frontal antérieur et postérieur.","s":6},{"q":"Le goniomètre demi-cercle (0-180°) est :","o":["Moins utilisé","Plus utilisé et plus facile","Réservé aux experts","Obsolète"],"r":1,"e":"Le demi-cercle 0-180° est le plus utilisé en clinique.","s":7},{"q":"Types de goniomètres :","o":["Plastique","Métallique","Cercle complet 360°","Demi-cercle 0-180°","Goniomètre à gravité (inclinomètre)","Magnétique"],"r":[0,1,2,3,4],"e":"Multiples types existent. Pas de version magnétique standard.","s":7},{"q":"Un goniomètre universel comporte combien de parties ?","o":["2","3 (corps, bras fixe, bras mobile)","4","5"],"r":1,"e":"3 parties : corps (axe), bras fixe, bras mobile.","s":7},{"q":"Les incréments typiques d'un goniomètre sont :","o":["1° ou 2°","5° ou 10°","15° ou 20°","30° ou 45°"],"r":1,"e":"5° ou 10° généralement. Identifier la ligne médiane pour la lecture.","s":7},{"q":"Un goniomètre à gravité s'appelle aussi :","o":["Dynamomètre","Inclinomètre","Pédomètre","Plurimètre"],"r":1,"e":"Inclinomètre : utilise la gravité comme référence.","s":7},{"q":"La fiabilité de la goniométrie est :","o":["Faible","Bonne avec reproductibilité intra/inter-observateurs","Toujours mauvaise","Indépendante de la méthode"],"r":1,"e":"Valeurs intra- et inter-observateurs reproductibles si méthode standardisée.","s":7},{"q":"Quelle est la première étape de la procédure ?","o":["Mobiliser","Aligner","Expliquer au patient","Enregistrer"],"r":2,"e":"Ordre : Expliquer → positionner → localiser → aligner → mobiliser → enregistrer.","s":7},{"q":"Combien d'étapes la procédure goniométrique compte-t-elle ?","o":["3","4","6","8"],"r":2,"e":"6 étapes : expliquer, positionner, localiser, aligner, mobiliser, enregistrer.","s":7},{"q":"L'articulation doit être placée à :","o":["45° de départ","90° de départ","0° de départ","Position de confort uniquement"],"r":2,"e":"Position 0° (anatomique ou neutre) comme point de départ standardisé.","s":7},{"q":"L'évaluateur doit se positionner :","o":["Le plus loin possible","Près de l'articulation à évaluer","Toujours debout","Derrière le patient"],"r":1,"e":"Proximité = bonne mécanique corporelle et précision de mesure.","s":7},{"q":"Critères du bon positionnement :","o":["Sûr, détendu, confortable","Mouvement complet et sans entrave","Articulation à 0°","En tension maximale","Standardisé (mêmes positions à chaque mesure)"],"r":[0,1,2,4],"e":"La tension maximale n'est pas un critère ; au contraire, on cherche stress minimal.","s":7},{"q":"Les bras du goniomètre doivent être alignés avec :","o":["Les segments distaux uniquement","Les points de référence anatomiques","La table d'examen","Les vêtements du patient"],"r":1,"e":"Alignement sur les points anatomiques identifiés par observation et palpation.","s":7},{"q":"Le corps du goniomètre doit être placé :","o":["À l'extrémité distale","Sur l'axe du mouvement, proche du segment proximal","Au milieu du segment","Sur l'os controlatéral"],"r":1,"e":"L'axe peut bouger ; rester proche du proximal facilite la mesure.","s":7},{"q":"Pour éviter l'erreur de parallaxe :","o":["Fermer un œil","Regarder de loin","Centrer le regard sur la lecture","Mesurer rapidement"],"r":2,"e":"Regard centré = lecture sans erreur de parallaxe.","s":7},{"q":"Quel segment doit être stabilisé ?","o":["Le distal","Le proximal","Aucun","Les deux simultanément"],"r":1,"e":"Stabiliser le segment proximal (par la table ou le kiné).","s":7},{"q":"En cas de stabilisation manuelle complexe :","o":["Abandonner la mesure","Demander une 2e personne","Faire sans stabiliser","Utiliser un bandage"],"r":1,"e":"2e personne = solution standard si stabilisation manuelle complexe.","s":7},{"q":"Les repères anatomiques s'identifient par :","o":["Observation et palpation","Radio uniquement","Demande au patient","Hasard"],"r":0,"e":"Identification par observation + palpation systématique.","s":7},{"q":"Pour ne pas fausser la mesure, la distance bras-segment doit être :","o":["Aussi grande que possible","Faible","À 5 cm","À 10 cm"],"r":1,"e":"Distance bras-segment faible = précision.","s":7},{"q":"Lors d'une mesure passive, le mouvement est effectué :","o":["Très rapidement","Lentement et minutieusement","Avec rebond","En vibration"],"r":1,"e":"Détermination de l'end-feel demande lenteur et précision.","s":7},{"q":"Informations obligatoires à enregistrer :","o":["Nom et âge","Date et lieu","Type de goniomètre","Amplitudes (côté, mouvement)","Couleur des yeux"],"r":[0,1,2,3],"e":"Tous sauf la couleur des yeux.","s":7},{"q":"À noter en plus :","o":["Informations subjectives (douleur)","Informations objectives (spasmes)","Modification du positionnement","Pression artérielle"],"r":[0,1,2],"e":"Pas la TA en routine goniométrique.","s":7},{"q":"On marque en rouge :","o":["Les amplitudes normales","Les amplitudes modifiées (anormales)","Toutes les mesures","Aucune mesure"],"r":1,"e":"Convention : valeurs anormales = rouge ; normales = noir.","s":7},{"q":"Pour interpréter les résultats, la référence essentielle est :","o":["Le sexe du patient","Le côté controlatéral","La date","Le poids"],"r":1,"e":"Comparaison au côté sain (controlatéral) + valeurs de référence.","s":7},{"q":"Objectif idéal de rééducation :","o":["Atteindre 180° partout","Récupérer l'amplitude du membre non blessé","Atteindre la moitié de la normale","Aucun objectif fixe"],"r":1,"e":"Comparer et viser l'amplitude du membre non blessé.","s":7},{"q":"Le diagramme de mouvement utilise les symboles :","o":["A, B, C","D, R, S (Douleur, Résistance, Spasme)","X, Y, Z","O, N, P"],"r":1,"e":"D = douleur, R = résistance, E/S = spasme. Comportement le long de l'amplitude.","s":7},{"q":"La contraction utilisée en fin d'amplitude pour le test est :","o":["Isotonique concentrique","Isotonique excentrique","Isométrique","Isocinétique"],"r":2,"e":"Isométrique en fin d'amplitude.","s":7},{"q":"Le mouvement passif lors de la mesure est :","o":["Réalisé par le patient","Réalisé par l'évaluateur, le bras mobile suit","Réalisé par les deux simultanément","Inutile"],"r":1,"e":"Mouvement passif = l'évaluateur mobilise ; le bras mobile du goniomètre suit.","s":7},{"q":"On standardise les mesures successives en :","o":["Mesurant à des moments aléatoires","Variant les positions","Utilisant les mêmes positions et le même moment de la journée","Changeant d'évaluateur à chaque fois"],"r":2,"e":"Standardisation pour la fiabilité dans le temps.","s":7},{"q":"Un patient avec hyperextension de 5° au coude se note :","o":["Extension : -5°","Extension : +5° (hyperextension)","Flexion : -5°","Flexion : 5°"],"r":1,"e":"Hyperextension = + (au-delà de la position 0).","s":7},{"q":"Le format le plus utilisé pour la notation des amplitudes est :","o":["0-180° (zéro neutre)","180-0°","0-360°","90-270°"],"r":0,"e":"Méthode du zéro neutre = standard international.","s":7},{"q":"Parmi les types de goniomètres, le cours distingue notamment :","o":["Plastique ou métallique, cercle complet ou demi-cercle, grand ou petit, manuel ou électronique","Uniquement plastique ou métallique","Uniquement manuel","Uniquement électronique"],"r":0,"e":"Le goniomètre à gravité, ou inclinomètre, complète cette liste.","s":7},{"q":"Parmi les méthodes alternatives à la goniométrie, le cours cite :","o":["La photographie, la radiographie, les smartphones et l'estimation visuelle","L'échographie","L'électromyographie","La dynamométrie"],"r":0,"e":"Le goniomètre demi-cercle reste le plus utilisé et le plus facile d'emploi.","s":7},{"q":"Le goniomètre universel se compose :","o":["Du corps ou axe, du bras fixe et du bras mobile","De deux bras seulement","D'un cadran et d'une aiguille","D'un axe et d'un bras"],"r":0,"e":"Il faut être attentif à l'échelle et aux incréments, généralement de 5 ou 10°, pour éviter les erreurs de lecture.","s":7},{"q":"La fiabilité de la goniométrie est décrite comme :","o":["Reproductible et cohérente en intra- et inter-observateurs, permettant des évaluations universelles","Faible","Limitée à un seul examinateur","Dépendante du seul instrument"],"r":0,"e":"Cette fiabilité suppose toutefois la standardisation des positions et du moment de la journée.","s":7},{"q":"La première étape de la procédure goniométrique est :","o":["Expliquer à l'utilisateur, en démontrant si nécessaire","Localiser les repères anatomiques","Aligner les bras du goniomètre","Mobiliser le segment"],"r":0,"e":"Suivent le positionnement et la stabilisation, la localisation des repères, l'alignement, la mobilisation et l'enregistrement.","s":7},{"q":"L'articulation doit être placée, au départ de la mesure, à :","o":["0°","45°","90°","La position de confort"],"r":0,"e":"Le positionnement doit être sûr, détendu et confortable, et permettre un mouvement complet et sans entrave.","s":7},{"q":"L'évaluateur doit se placer :","o":["Près de l'articulation, pour la mécanique corporelle et la prévention des douleurs","Le plus loin possible","Face au patient systématiquement","Derrière le patient"],"r":0,"e":"La position peut être adaptée si nécessaire, mais doit alors être notée au dossier.","s":7},{"q":"Le corps du goniomètre doit être aligné avec :","o":["Le segment distal","L'axe du mouvement","Le bras fixe","La ligne de gravité"],"r":1,"e":"Comme cet axe peut se déplacer, il faut garder le corps du goniomètre proche du segment proximal.","s":7},{"q":"L'erreur de parallaxe s'évite en :","o":["Centrant le regard sur la lecture","Éloignant le goniomètre","Utilisant un grand goniomètre","Mesurant deux fois"],"r":0,"e":"C'est une erreur de lecture liée à l'angle d'observation du cadran.","s":7},{"q":"La stabilisation porte sur :","o":["Le segment proximal, par la table d'examen ou le kinésithérapeute","Le segment distal","Les deux segments","Le tronc uniquement"],"r":0,"e":"Elle évite les mouvements combinés et les compensations ; si elle est complexe, une deuxième personne est requise.","s":7},{"q":"Les repères anatomiques s'identifient :","o":["Par observation et palpation","Par radiographie","Par mesure de longueur","Par estimation visuelle seule"],"r":0,"e":"Les bras du goniomètre s'alignent ensuite sur les segments proximal et distal.","s":7},{"q":"La distance entre le bras du goniomètre et le segment doit être :","o":["Faible, pour ne pas fausser la mesure","Importante, pour bien voir","Indifférente","D'au moins 10 cm"],"r":0,"e":"Le mouvement est passif, le bras mobile suivant le déplacement du segment.","s":7},{"q":"Parmi les informations obligatoires à consigner figurent :","o":["Nom, âge et sexe de l'utilisateur, nom du kinésithérapeute, date, lieu et type de goniomètre","Le seul résultat chiffré","Le seul nom du patient","La seule date"],"r":0,"e":"S'y ajoutent les amplitudes avec le côté et le mouvement, ainsi que les informations subjectives et objectives.","s":7},{"q":"On marque en rouge, dans l'enregistrement :","o":["Les amplitudes modifiées","Toutes les amplitudes","Les amplitudes normales","Le nom du patient"],"r":0,"e":"La modification du positionnement doit également être consignée.","s":7},{"q":"Parmi les informations objectives à noter figurent :","o":["Les spasmes","La douleur ressentie","L'anxiété","La motivation"],"r":0,"e":"La douleur relève, elle, des informations subjectives.","s":7},{"q":"La référence essentielle pour interpréter un résultat goniométrique est :","o":["La comparaison avec le côté controlatéral","La seule valeur de référence théorique","La moyenne de la population","La mesure précédente"],"r":0,"e":"Les valeurs variant selon les individus, la comparaison controlatérale précède la comparaison aux valeurs de référence.","s":7},{"q":"L'objectif de rééducation, en goniométrie, est de travailler :","o":["Jusqu'à atteindre l'amplitude du membre non blessé","Jusqu'à la valeur théorique maximale","Jusqu'à la douleur","Jusqu'à 90° dans tous les cas"],"r":0,"e":"C'est la conséquence directe du principe de comparaison controlatérale.","s":7},{"q":"La standardisation des mesures successives passe par :","o":["Les mêmes positions et le même moment de la journée","Le même examinateur uniquement","Le même instrument uniquement","La même température"],"r":0,"e":"C'est ce qui garantit la fiabilité intra- et inter-observateurs.","s":7},{"q":"Lors de la mesure, le mouvement du segment est :","o":["Actif","Passif, le bras mobile suivant le mouvement","Actif assisté","Résisté"],"r":1,"e":"Cette passivité évite que la force ou la coopération du patient n'influencent la mesure.","s":7},{"q":"Les incréments d'un goniomètre exigent une attention particulière car :","o":["Généralement de 5 ou 10°, ils exposent à des erreurs de lecture","Ils varient d'un patient à l'autre","Ils modifient l'amplitude réelle","Ils dépendent du plan mesuré"],"r":0,"e":"Il faut également identifier la ligne médiane de l'instrument avant la lecture.","s":7},{"q":"L'immobilisation sélective suppose l'utilisation de :","o":["Un plâtre rigide complet","Un bandage fonctionnel sur les tissus mous et articulations lésées","Une attelle métallique permanente","Un fauteuil roulant"],"r":1,"e":"L'immobilisation sélective = bandage fonctionnel : soutien sélectif sans immobilisation complète.","s":8},{"q":"Quels sont les effets recherchés de l'immobilisation sélective ?","o":["Soutien et protection sélective des tissus","Diminution de la douleur","Diminution de l'œdème","Augmentation de la force musculaire","Stabilité articulaire"],"r":[0,1,2,4],"e":"Soutien, ↓ douleur, ↓ œdème, stabilité. L'IS n'augmente pas directement la force musculaire.","s":8},{"q":"L'immobilisation sélective est :","o":["Un substitut au programme de rééducation","Un complément du programme de rééducation","Un traitement à elle seule","Une alternative à la chirurgie"],"r":1,"e":"C'est un COMPLÉMENT, jamais un substitut aux programmes de rééducation.","s":8},{"q":"Comment agit l'immobilisation sélective ?","o":["Compression → réduit l'œdème","Soutient ligaments, tendons et muscles","Limite les mouvements articulaires indésirables","Augmente les mouvements douloureux","Protège les structures lésées en position fonctionnelle"],"r":[0,1,2,4],"e":"L'IS limite (pas augmente) les mouvements douloureux.","s":8},{"q":"La phase aiguë de la régénération tissulaire dure :","o":["0 à 3 jours","3 jours à 6 semaines","6 semaines à 6 mois","6 mois à 1 an"],"r":0,"e":"Aiguë (inflammation) = 0-3j ; subaiguë (réparation) = 3j-6sem ; chronique (remodelage) = 6sem-6mois.","s":8},{"q":"La phase inflammatoire de la cicatrisation dure :","o":["1 jour","Premiers 4 à 5 jours","2 semaines","1 mois"],"r":1,"e":"Phase inflammatoire = préparation de la zone, 4 à 5 premiers jours.","s":8},{"q":"La phase fibroblastique / réparation peut durer jusqu'à :","o":["1 semaine","3 semaines","3 mois","1 an"],"r":1,"e":"Phase fibroblastique : reconstruction, formation de tissu cicatriciel — jusqu'à 3 semaines.","s":8},{"q":"Le protocole PEACE & LOVE (Dubois & Esculier, 2019) correspond à :","o":["Un protocole chirurgical","Une approche de prise en charge des lésions des tissus mous","Un type de bandage","Un test diagnostique"],"r":1,"e":"PEACE & LOVE : Protection, Elevation, Avoid antiinflammatories, Compression, Education / Load, Optimism, Vascularisation, Exercise.","s":8},{"q":"Quels facteurs influencent la cicatrisation ?","o":["Âge","État de santé général","Tabac, alcool, caféine","Nutrition","Couleur des cheveux","Diabète mellitus, BPCO, néoplasies"],"r":[0,1,2,3,5],"e":"Tous sauf la couleur des cheveux. Type de tissu, âge, santé, psychologique, hygiène de vie, nutrition, comorbidités.","s":8},{"q":"Les effets des bandages fonctionnels sont :","o":["Mécanique (limite les mouvements excessifs)","Proprioceptif (récepteurs cutanés et articulaires)","Psychologique (sensation de sécurité et confort)","Anti-inflammatoire pharmacologique","Hormonal"],"r":[0,1,2],"e":"3 effets : mécanique, proprioceptif, psychologique.","s":8},{"q":"Avant l'application d'un bandage fonctionnel, il faut :","o":["Hydrater la peau abondamment","Laver, sécher, épiler la peau et retirer huiles/crèmes","Appliquer une pommade anti-inflammatoire","Bander immédiatement sans préparation"],"r":1,"e":"Préparer la peau : laver, sécher, épiler (sens descendant), retirer huiles/crèmes pour adhérence.","s":8},{"q":"Lors de l'application, l'articulation doit être placée :","o":["En position d'étirement maximum","En position fonctionnelle, avec stress minimal sur la structure lésée","En position de contraction maximale","Sans aucune position particulière"],"r":1,"e":"Position fonctionnelle, ligaments en raccourcissement, stress minimal.","s":8},{"q":"Lors de l'application des bandes, on les superpose :","o":["À 1/3","À moitié (1/2) pour éviter lacunes et glissement","Aux 3/4","Pas de superposition"],"r":1,"e":"Superposition à moitié : évite lacunes et glissement.","s":8},{"q":"Quels signes d'alerte doivent être expliqués au patient ?","o":["Démangeaisons et fatigue","Rougeur, chaleur, démangeaisons","Vertiges et nausées","Aucun signe particulier"],"r":1,"e":"Rougeur, chaleur et sensation de peau irritée (démangeaisons) = signes à surveiller.","s":8},{"q":"Que faut-il ÉVITER lors d'un bandage fonctionnel ?","o":["Traction excessive de la peau","Lacunes et plis dans le bandage","Bandages circonférentiels continus","Utiliser le même point d'ancrage chez les patients fréquents","Préparer la peau correctement"],"r":[0,1,2,3],"e":"À éviter : traction excessive, plis (ampoules), circonférentiel continu, même ancrage répété (irritation).","s":8},{"q":"Pour retirer un bandage fonctionnel, on utilise :","o":["Un couteau","Tape Remover et ciseaux à bouts ronds","Une lame de rasoir","Une simple traction"],"r":1,"e":"Tape Remover + ciseaux à bouts ronds, en soutenant la peau.","s":8},{"q":"Combien de temps faut-il habituellement laisser un bandage fonctionnel ?","o":["1 heure","6 heures","24 heures","1 semaine"],"r":2,"e":"Retrait après 24h dans la plupart des cas. Réévaluer fréquemment l'état de la peau.","s":8},{"q":"Après retrait, on évite l'exposition solaire pendant :","o":["12h","48h à 72h","1 semaine","1 mois"],"r":1,"e":"Éviter exposition solaire 48-72h car peau fragilisée.","s":8},{"q":"Quelles sont les contre-indications absolues à l'immobilisation sélective ?","o":["Fractures","Troubles circulatoires graves","Syndromes des loges","Lésions cutanées / plaies ouvertes","Intolérance à l'adhésif","Légère fatigue"],"r":[0,1,2,3,4],"e":"5 CI : fractures, troubles circulatoires graves, syndromes compartimentaux, lésions cutanées, intolérance adhésive.","s":8},{"q":"Quels matériaux font partie des bandages utilisés ?","o":["Tape (rigide)","Bandage élastique","Bandage conventionnel","Pré-tape","Coussins compressifs","Acide hyaluronique"],"r":[0,1,2,3,4],"e":"Tous sauf l'acide hyaluronique (qui est un produit injectable).","s":8},{"q":"Parmi les accessoires nécessaires :","o":["Spray adhésif","Tape remover","Coupe-ongles / appareil à raser","Ciseaux à bouts ronds","Crème hydratante","Stéthoscope"],"r":[0,1,2,3,4],"e":"Le stéthoscope n'est pas nécessaire pour l'immobilisation sélective.","s":8},{"q":"Le Kinesio Tape (bande neuromusculaire) a une élasticité de :","o":["50-70%","100%","140-150%","200%"],"r":2,"e":"Élasticité de 140 à 150% — caractéristique distincte du tape rigide.","s":8},{"q":"Le Kinesio Tape agit sur :","o":["La peau (récepteurs sensoriels)","Le fascia","Le système circulatoire","Le système lymphatique","Le muscle","L'articulation (biomécanique)","La consolidation osseuse d'une fracture"],"r":[0,1,2,3,4,5],"e":"6 niveaux d'action (Wu et al., 2015) : peau, fascia, circulation, lymphatique, muscle, articulation. Le Kinesio Tape agit sur les tissus mous et la perception ; il n'immobilise rien et n'influence pas la consolidation osseuse.","s":8},{"q":"Une découpe en « I Strip » se caractérise par :","o":["Tension dispersée sur les côtés","Tension focalisée dans la zone thérapeutique, directement sur le tissu cible","Tension nulle","Tension répartie en éventail"],"r":1,"e":"I Strip : tension focalisée sur la zone cible.","s":8},{"q":"La découpe en « Fan Cut » est utilisée principalement pour :","o":["Force musculaire","Drainage lymphatique","Stabilité ligamentaire","Compression intense"],"r":1,"e":"Fan Cut : tension dispersée par les bandes, idéale pour le drainage lymphatique.","s":8},{"q":"Pour une INHIBITION musculaire (surmenage, lésion aiguë, spasme), on applique le Kinesio Tape :","o":["Origine → Insertion, tension 25-50%","Insertion → Origine, tension 15-25%","Sans tension","Perpendiculairement"],"r":1,"e":"Inhibition = direction Insertion→Origine, tension faible 15-25%.","s":8},{"q":"Pour une FACILITATION (lésion chronique, rééducation), on applique le Kinesio Tape :","o":["Origine → Insertion, tension 25-50%","Insertion → Origine, tension 5-10%","Sans tension","En boucle fermée"],"r":0,"e":"Facilitation = direction Origine→Insertion, tension élevée 25-50%.","s":8},{"q":"La durée maximale recommandée pour porter un Kinesio Tape est de :","o":["12 heures","24 heures","3 à 5 jours","2 semaines"],"r":2,"e":"Kinesio Tape : 3 à 5 jours maximum.","s":8},{"q":"Précautions à prendre avec le Kinesio Tape :","o":["Diabète","Pathologies rénales","Pathologie cardiaque","Peau fragile","Cheveux longs"],"r":[0,1,2,3],"e":"4 précautions : diabète, pathologies rénales, cardiaques et peau fragile.","s":8},{"q":"Quels mythes faut-il déconstruire à propos du Kinesio Tape ?","o":["Les couleurs ont un effet thérapeutique (chromothérapie)","Les bandes contiennent des substances anti-inflammatoires","Son efficacité est largement prouvée","Action purement sensitive sur la peau","Il faut adopter une attitude critique"],"r":[0,1,2],"e":"3 MYTHES : chromothérapie, anti-inflammatoires, efficacité largement prouvée. L'action est sensitive ; attitude critique requise.","s":8},{"q":"Parmi les objectifs d'utilisation de l'immobilisation sélective, le cours cite :","o":["La prévention des lésions, le traitement des lésions, la complémentarité avec d'autres stratégies et la promotion d'une meilleure fonction","La seule prévention","Le seul traitement","La seule antalgie"],"r":0,"e":"Elle complète notamment la marche, l'entraînement fonctionnel, la reprogrammation sensori-motrice et le massage.","s":8},{"q":"Parmi les mécanismes d'action de l'immobilisation sélective figure :","o":["La protection des structures lésées dans une position fonctionnelle","L'augmentation de la force","L'augmentation de l'amplitude","La stimulation de l'inflammation"],"r":0,"e":"S'y ajoutent la compression réduisant l'œdème, le soutien des ligaments, tendons et muscles, et la limitation des mouvements indésirables.","s":8},{"q":"Les décisions cliniques en immobilisation sélective se fondent sur :","o":["La physiologie de la régénération tissulaire et les objectifs d'intervention","Le seul confort du patient","La seule douleur","Le protocole du service"],"r":0,"e":"Il s'agit de contrôler l'inflammation, stabiliser, créer les conditions de réparation, diminuer douleur et œdème et maintenir mobilité et force des segments non affectés.","s":8},{"q":"La phase chronique de la régénération tissulaire s'étend de :","o":["0 à 3 jours","3 jours à 6 semaines","6 semaines à 6 mois","6 mois à 1 an"],"r":2,"e":"Elle correspond au remodelage ; la phase aiguë couvre 0 à 3 jours et la subaiguë 3 jours à 6 semaines.","s":8},{"q":"La phase de remodelage de la cicatrisation se caractérise par :","o":["Le remodelage de la fibrose avec remplacement progressif et nouvelle organisation des cellules et de la matrice","La préparation de la zone affectée","La formation initiale du tissu cicatriciel","La réaction vasculaire"],"r":0,"e":"Les fibroblastes n'ont pas toujours la capacité de reproduire exactement l'architecture du tissu original.","s":8},{"q":"Dans PEACE, la lettre A signifie :","o":["Activité","Éviter les anti-inflammatoires (Avoid anti-inflammatories)","Application","Analgésie"],"r":1,"e":"PEACE réunit Protection, Élévation, Avoid anti-inflammatories, Compression et Éducation ; LOVE ajoute Load, Optimism, Vascularisation et Exercise.","s":8},{"q":"Dans LOVE, la lettre O signifie :","o":["Œdème","Optimisme","Observation","Orthèse"],"r":1,"e":"Le protocole est dû à Dubois & Esculier (2019).","s":8},{"q":"Parmi les facteurs influençant la cicatrisation, le cours cite :","o":["Le type de tissu, l'âge, l'état de santé général, l'état psychologique, les habitudes de vie, la nutrition et les pathologies associées","Le seul âge","La seule nutrition","Le seul type de tissu"],"r":0,"e":"Tabac, alcool et caféine figurent parmi les habitudes de vie ; diabète, BPCO et néoplasies parmi les pathologies.","s":8},{"q":"L'effet proprioceptif des bandages fonctionnels repose sur :","o":["La stimulation des récepteurs cutanés et articulaires","La limitation mécanique","Le sentiment de sécurité","La compression"],"r":0,"e":"L'effet mécanique limite les mouvements excessifs et l'effet psychologique procure sécurité et confort.","s":8},{"q":"Parmi les précautions avant application figure :","o":["Vérifier les antécédents d'intolérance à l'adhésif ou au spray","Mouiller la peau","Appliquer une crème hydratante","Chauffer la zone"],"r":0,"e":"La peau doit être lavée, séchée et épilée si nécessaire, et débarrassée des huiles et crèmes.","s":8},{"q":"Lors de l'application, les ligaments doivent être placés :","o":["En position d'étirement","En position de raccourcissement","En position neutre indifférente","En tension maximale"],"r":1,"e":"L'articulation est placée en position fonctionnelle, avec un stress minimal.","s":8},{"q":"Les bandes doivent être superposées :","o":["À moitié, pour éviter lacunes et glissement","Au quart","Bord à bord","Sans recouvrement"],"r":0,"e":"Chaque bande doit être appliquée avec un objectif précis, de façon douce mais ferme.","s":8},{"q":"Les signes d'alerte à expliquer au patient sont :","o":["Rougeur, chaleur et démangeaisons","Douleur et raideur","Fièvre et frissons","Œdème et ecchymose"],"r":0,"e":"Ils imposent le retrait du bandage et la réévaluation de l'état cutané.","s":8},{"q":"Parmi les erreurs à éviter, le cours cite :","o":["La traction excessive de la peau, les lacunes et plis, les bandages circonférentiels continus et le même point d'ancrage répété","Le recouvrement des bandes","L'utilisation de pré-tape","L'application à température ambiante"],"r":0,"e":"La traction excessive provoque des lésions cutanées et les plis des ampoules.","s":8},{"q":"L'exposition solaire doit être évitée après retrait pendant :","o":["24 heures","48 à 72 heures","1 semaine","1 mois"],"r":1,"e":"Le bandage lui-même se retire après 24 heures dans la plupart des cas.","s":8},{"q":"Parmi les contre-indications à l'immobilisation sélective figurent :","o":["Les fractures, les troubles circulatoires graves, les syndromes des loges, les lésions cutanées et l'intolérance à l'adhésif","L'œdème","La douleur","L'instabilité articulaire"],"r":0,"e":"Le syndrome des loges est aggravé par toute compression supplémentaire.","s":8},{"q":"L'élasticité du Kinesio Tape est de :","o":["100 à 110 %","120 à 130 %","140 à 150 %","180 à 200 %"],"r":2,"e":"Elle permet une totale liberté de mouvement tout en soutenant les tissus mous.","s":8},{"q":"Selon Wu et al. (2015), le Kinesio Tape agit notamment sur :","o":["La peau et ses récepteurs sensoriels, le fascia, les systèmes circulatoire et lymphatique, le muscle et la biomécanique articulaire","Le seul muscle","La seule peau","Le seul système lymphatique"],"r":0,"e":"Il prolonge ainsi l'effet de la thérapie manuelle.","s":8},{"q":"Pour une facilitation musculaire, le Kinesio Tape s'applique :","o":["De l'insertion vers l'origine, à tension faible","De l'origine vers l'insertion, à tension élevée de 25 à 50 %","Sans tension","En circonférentiel"],"r":1,"e":"L'inhibition s'applique de l'insertion vers l'origine avec une tension faible de 15 à 25 %, en cas de surmenage, lésion aiguë ou spasme.","s":8},{"q":"Parmi les mythes à déconstruire à propos du Kinesio Tape, le cours cite :","o":["L'effet des couleurs par chromothérapie et la présence de substances anti-inflammatoires","Son élasticité","Sa durée de port","Ses précautions d'emploi"],"r":0,"e":"Son action est purement sensitive, et son efficacité reste questionnable faute de preuves scientifiques solides — d'où l'attitude critique recommandée.","s":8},{"q":"Une mobilisation passive est basée sur :","o":["Les mouvements accessoires","Les mouvements physiologiques (à faible vitesse)","La force musculaire","Le réflexe ostéo-tendineux"],"r":1,"e":"Mobilisation passive = basée sur les mouvements physiologiques angulaires.","s":9},{"q":"Un mouvement accessoire est :","o":["Volontaire et mesurable","Petit, intra-articulaire, non volontaire","Une amplitude active maximale","Un test musculaire"],"r":1,"e":"Mouvements accessoires : glissements, tractions, intra-articulaires.","s":9},{"q":"Si ↓ mouvements accessoires :","o":["↑ mouvements physiologiques","↓ mouvements physiologiques → douleur","Aucun effet","↑ stabilité articulaire"],"r":1,"e":"↓ accessoires → ↓ physiologiques → douleur.","s":9},{"q":"Directions des mouvements accessoires :","o":["Longitudinale","Transversale","Antéro-postérieure","Rotation","Tangentielle"],"r":[0,1,2,3],"e":"4 directions : longitudinale, transversale, AP, rotation.","s":9},{"q":"L'ostéocinématique étudie :","o":["Les mouvements intra-articulaires","Les mouvements globaux des os (mesurables au goniomètre)","Le métabolisme osseux","Les forces musculaires"],"r":1,"e":"Ostéocinétique = mouvements physiologiques angulaires.","s":9},{"q":"Types de mouvements arthrocinématiques :","o":["Roulement","Glissement","Rotation","Compression","Traction","Pronation"],"r":[0,1,2,3,4],"e":"5 types : roulement, glissement, rotation, compression, traction. Pronation = ostéocinétique.","s":9},{"q":"Lors d'un roulement :","o":["Un point sur série de points","Série de points sur série de points (balle qui roule)","Compression pure","Translation parallèle"],"r":1,"e":"Roulement = série de points en contact avec série de points (balle qui roule).","s":9},{"q":"Plus les surfaces sont congruentes, plus il y a :","o":["Roulement","Glissement","Compression","Traction"],"r":1,"e":"Surfaces congruentes → glissement prédominant.","s":9},{"q":"La compression articulaire avec contraction musculaire :","o":["Crée toujours une lésion","Apporte stabilité et nutrition cartilagineuse","Augmente le mouvement","Provoque une luxation"],"r":1,"e":"Compression + contraction = stabilité, prévention de lésions, nutrition cartilage.","s":9},{"q":"La traction articulaire :","o":["Rapproche les surfaces","Écarte les 2 surfaces, allonge la capsule, soulage la douleur","Bloque le mouvement","Crée une luxation"],"r":1,"e":"Traction = écartement, allongement capsulaire, antalgique.","s":9},{"q":"Selon Kaltenborn, surface mobile CONVEXE :","o":["Glissement dans le sens du mouvement","Glissement dans le sens opposé au mouvement","Aucun glissement","Roulement uniquement"],"r":1,"e":"Convexe sur concave → glissement opposé.","s":9},{"q":"Selon Kaltenborn, surface mobile CONCAVE :","o":["Glissement opposé","Glissement dans le même sens que le mouvement","Pas de glissement","Roulement libre"],"r":1,"e":"Concave sur convexe → glissement même sens.","s":9},{"q":"En flexion de hanche en DD, la tête fémorale (convexe) :","o":["Glisse AP (opposé à la flexion)","Glisse PA","Ne glisse pas","Tourne sur elle-même"],"r":0,"e":"Convexe sur concave → glissement antéro-postérieur (opposé).","s":9},{"q":"En extension du genou (assis), le tibia (concave) :","o":["Glisse AP","Glisse PA (même sens que l'extension)","Glisse latéralement","Reste fixe"],"r":1,"e":"Concave sur convexe → glissement postéro-antérieur (même sens).","s":9},{"q":"Indications de la mobilisation accessoire :","o":["Douleur, spasmes musculaires","Hypomobilité réversible","Adhérences, rétraction capsulo-ligamentaire","Subluxation/mauvais alignement","Œdème articulaire","Fracture aiguë"],"r":[0,1,2,3,4],"e":"Fracture aiguë = CI. Les autres = indications.","s":9},{"q":"Buts de la mobilisation accessoire :","o":["Modulation de la douleur","↑ amplitude de mouvement","Traitement des dysfonctionnements biomécaniques","Renforcement musculaire direct"],"r":[0,1,2],"e":"Pas un objectif de renforcement musculaire.","s":9},{"q":"Effet neurophysiologique de la mobilisation accessoire :","o":["Stimulation des mécanorécepteurs → inhibition nociceptive","Augmentation de la force","Réparation tissulaire directe","Compression neuronale"],"r":0,"e":"Oscillations → stimulent mécanorécepteurs → inhibition de la nociception (porte de Melzack).","s":9},{"q":"Effet nutritionnel de la mobilisation accessoire :","o":["Augmente l'appétit","Favorise circulation du liquide synovial → nutrition cartilage","Apporte calcium","Renforce les os"],"r":1,"e":"Mouvements doux → mobilisation du liquide synovial → nutrition des zones avasculaires.","s":9},{"q":"Effet mécanique :","o":["Casse les adhérences","Maintien de l'extensibilité tensile des structures ligamentaires/articulaires","Éclate le cartilage","Augmente la fibrose"],"r":1,"e":"Maintien de l'extensibilité, force tensile ; évite la prolifération fibro-adipeuse.","s":9},{"q":"Contre-indications RELATIVES :","o":["Hypermobilité","Grossesse (relaxine ↑)","Ostéoporose","Modifications vasculaires","Lésions ligamentaires aiguës","Fractures non consolidées"],"r":[0,1,2,3,4],"e":"Fracture non consolidée = CI absolue.","s":9},{"q":"Contre-indications ABSOLUES :","o":["Fractures non consolidées","Arthroplastie totale","Spondylolisthésis","Compression médullaire","Néoplasie/métastases","Ostéomyélite","Grossesse"],"r":[0,1,2,3,4,5],"e":"La grossesse est relative. Les 6 autres = absolues.","s":9},{"q":"En cas d'hypomobilité D4-D5 + hypermobilité douloureuse D9-D10 :","o":["Mobiliser uniquement D9-D10","Mobiliser D4-D5 pour réduire le stress sur D9-D10","Immobiliser le rachis entier","Manipuler D9-D10"],"r":1,"e":"Traiter l'hypomobilité (cause), pas le site douloureux (conséquence).","s":9},{"q":"Grade I de Maitland :","o":["Petite amplitude/oscillation en début d'amplitude","Grande amplitude à la fin","Mouvement maximal","Manipulation"],"r":0,"e":"Grade I : oscillation en début, but analgésique.","s":9},{"q":"Grade II de Maitland :","o":["Petite amplitude en fin","Grande amplitude sans atteindre la limite","Manipulation","Sans amplitude"],"r":1,"e":"Grade II : amplitude plus grande, sans atteindre la limite. Analgésique.","s":9},{"q":"Grade III de Maitland :","o":["Petite amplitude au début","Grande amplitude jusqu'à la limite (forçant la résistance)","Très petite amplitude","Manipulation rapide"],"r":1,"e":"Grade III : grande amplitude forçant la résistance. Augmente la ROM.","s":9},{"q":"Grade IV de Maitland :","o":["Petite amplitude en fin de mouvement, à la limite","Grande amplitude en début","Mouvement balistique","Sans contact"],"r":0,"e":"Grade IV : petite amplitude en fin, à la limite, forçant la résistance.","s":9},{"q":"Grade V de Maitland :","o":["Manipulation : mouvement rapide, petite amplitude, hors contrôle patient","Mobilisation lente","Sans amplitude","Grade pédiatrique"],"r":0,"e":"Grade V = thrust manipulatif. Cours avancé, technique experte.","s":9},{"q":"Indication des grades I-II :","o":["Augmenter ROM","Analgésie (douleur)","Manipulation","Stabilisation"],"r":1,"e":"I-II = analgésie. III-IV = augmentation ROM.","s":9},{"q":"Indication des grades III-IV :","o":["Analgésie","Augmenter ROM (phase subaiguë/chronique)","Réduire un spasme","Manipulation"],"r":1,"e":"III-IV : forçage de la résistance pour ↑ ROM.","s":9},{"q":"La mobilisation accessoire vise principalement :","o":["Le renforcement","La modulation douleur + ↑ ROM + correction biomécanique","Le drainage lymphatique","La rééducation cardiaque"],"r":1,"e":"3 buts : modulation douleur, ↑ ROM, traitement biomécanique.","s":9},{"q":"La mobilisation articulaire passive s'applique :","o":["Aux articulations et aux tissus mous, à faible vitesse et dans différentes amplitudes","Aux seules articulations","À vitesse rapide","En amplitude maximale uniquement"],"r":0,"e":"Elle repose sur les mouvements physiologiques et le patient peut l'interrompre.","s":9},{"q":"Les mouvements accessoires se caractérisent par le fait :","o":["De ne pas pouvoir être réalisés isolément de façon volontaire","D'être volontairement contrôlés","D'être mesurables à la goniométrie","De se produire autour d'un axe défini"],"r":0,"e":"Ce sont de petits mouvements intra-articulaires nécessaires pour réaliser l'amplitude normale : glissements et tractions.","s":9},{"q":"Les sens des mouvements accessoires sont :","o":["Caudal/céphalique, latéral/médial, antéro/postérieur et postéro/antérieur","Flexion/extension seulement","Interne/externe","Proximal/distal uniquement"],"r":0,"e":"Leurs directions sont longitudinale, transversale, antéro-postérieure et en rotation.","s":9},{"q":"Les mouvements ostéocinétiques se caractérisent par le fait :","o":["D'être volontairement contrôlés et mesurables par goniométrie","D'être intra-articulaires et non volontaires","D'être de faible amplitude","D'être non mesurables"],"r":0,"e":"Ils se produisent dans un plan, autour d'un axe ; les arthrocinématiques sont non volontaires et non mesurables.","s":9},{"q":"Le roulement se définit comme :","o":["Une série de points d'une surface entrant en contact avec une série de points de l'autre","Un point entrant en contact avec une série de points","Une rotation autour d'un axe longitudinal","Un écartement des surfaces"],"r":0,"e":"La surface qui bouge n'influence pas sa direction, contrairement au glissement soumis à la règle convexe-concave.","s":9},{"q":"Le glissement se définit comme :","o":["Une série de points contre une série de points","Un point spécifique entrant en contact avec une série de points de l'autre surface","Une rotation axiale","Une compression"],"r":1,"e":"Plus les surfaces sont congruentes, plus il y a de glissement.","s":9},{"q":"La compression articulaire associée à une contraction musculaire apporte :","o":["Stabilité, prévention des lésions et nutrition du cartilage","Uniquement un soulagement de la douleur","Un allongement capsulaire","Un écartement des surfaces"],"r":0,"e":"Son excès entraîne au contraire une lésion cartilagineuse ; la traction allonge la capsule et soulage la douleur.","s":9},{"q":"Selon la règle de Kaltenborn, une surface mobile convexe glisse :","o":["Dans le même sens que le mouvement physiologique","Dans le sens opposé au mouvement physiologique","Sans glissement","En rotation pure"],"r":1,"e":"Une surface mobile concave glisse, elle, dans le même sens que le mouvement physiologique.","s":9},{"q":"Lors de l'extension du genou en position assise, le tibia concave glisse :","o":["De postérieur vers antérieur, dans le même sens que l'extension","D'antérieur vers postérieur","Latéralement","En rotation"],"r":0,"e":"À la hanche, la tête fémorale convexe glisse au contraire d'antérieur vers postérieur lors de la flexion.","s":9},{"q":"Parmi les indications de la mobilisation accessoire, le cours cite :","o":["La douleur, les spasmes, l'hypomobilité réversible, les adhérences, le mauvais alignement et l'œdème articulaire","La fracture non consolidée","L'hypermobilité","Les signes neurologiques"],"r":0,"e":"Sur œdème articulaire, les mobilisations douces favorisent le drainage et la nutrition du cartilage.","s":9},{"q":"Les trois buts de la mobilisation accessoire sont :","o":["Moduler la douleur, augmenter l'amplitude et traiter les dysfonctionnements liés à l'altération biomécanique articulaire","Renforcer, étirer et stabiliser","Drainer, réchauffer et relâcher","Mobiliser, manipuler et étirer"],"r":0,"e":"Ses effets se répartissent en neurophysiologiques, nutritionnels et mécaniques.","s":9},{"q":"L'effet neurophysiologique de la mobilisation accessoire repose sur :","o":["Des mouvements oscillatoires de faible amplitude stimulant mécanorécepteurs et nocicepteurs, inhibant la transmission nociceptive","La circulation du liquide synovial","Le maintien de l'extensibilité ligamentaire","La compression articulaire"],"r":0,"e":"Cette inhibition s'exerce au niveau de la moelle et du tronc cérébral, et s'accompagne d'une augmentation de la proprioception.","s":9},{"q":"L'effet nutritionnel de la mobilisation accessoire s'explique par :","o":["Des mouvements de traction et glissement de faible amplitude favorisant la circulation du liquide synovial","Une vasodilatation","Une augmentation du débit artériel","Un drainage lymphatique"],"r":0,"e":"Ils nourrissent ainsi les zones non vascularisées du cartilage.","s":9},{"q":"L'effet mécanique de la mobilisation accessoire consiste à :","o":["Maintenir l'extensibilité et la force tensile des structures ligamentaires et articulaires, et éviter la prolifération fibro-adipeuse","Augmenter la force musculaire","Diminuer la douleur","Nourrir le cartilage"],"r":0,"e":"C'est ce qui justifie la mobilisation précoce après immobilisation.","s":9},{"q":"Parmi les contre-indications RELATIVES de la mobilisation accessoire figurent :","o":["L'hypermobilité, la grossesse, l'ostéoporose, les modifications vasculaires et les lésions ligamentaires aiguës","Les fractures non consolidées","Les arthroplasties totales","Les maladies néoplasiques"],"r":0,"e":"La grossesse y figure du fait de l'augmentation de la relaxine et donc de la laxité.","s":9},{"q":"Parmi les contre-indications ABSOLUES figurent :","o":["Les fractures non consolidées, l'arthroplastie totale, le spondylolisthésis, les signes neurologiques, les néoplasies et les infections osseuses","L'ostéoporose","La grossesse","L'hypermobilité"],"r":0,"e":"Les signes neurologiques visés sont la compression médullaire, le syndrome de la queue de cheval et les sténoses.","s":9},{"q":"La modification vasculaire citée comme contre-indication relative concerne :","o":["L'artère vertébrale, du fait du risque de vertiges","L'artère fémorale","Les veines superficielles","Le réseau lymphatique"],"r":0,"e":"Elle impose une prudence particulière lors des mobilisations cervicales.","s":9},{"q":"Devant une hypomobilité en D4-D5 associée à une hypermobilité douloureuse en D9-D10, on traite :","o":["Le segment hypomobile","Le segment hypermobile, siège de la douleur","Les deux simultanément","Ni l'un ni l'autre"],"r":0,"e":"La règle est de traiter l'hypomobilité et non l'hypermobilité, même si cette dernière est le siège des symptômes.","s":9},{"q":"Une diminution des mouvements accessoires entraîne :","o":["Une diminution des mouvements physiologiques et une douleur","Une augmentation de l'amplitude","Aucune conséquence","Une hypermobilité"],"r":0,"e":"C'est précisément ce qui fonde l'intérêt de la mobilisation accessoire dans la récupération d'amplitude.","s":9},{"q":"La traction articulaire a pour effets :","o":["L'allongement de la capsule et le soulagement de la douleur","La stabilité et la nutrition du cartilage","La prévention des lésions","La diminution de l'espace articulaire"],"r":0,"e":"La compression, à l'inverse, diminue l'espace articulaire.","s":9},{"q":"Carl Kaltenborn a apporté :","o":["Le concept de manipulation à thrust","Les fondements biomécaniques et la règle concave-convexe","La rééducation fonctionnelle","La théorie du portillon"],"r":1,"e":"Kaltenborn (1950-80) : règle concave-convexe, mobilisation accessoire biomécanique.","s":10},{"q":"George Maitland était :","o":["Physiothérapeute américain","Physiothérapeute australien (1924-2010)","Orthopédiste anglais","Radiologue"],"r":1,"e":"Maitland australien, premier à systématiser cliniquement la MA.","s":10},{"q":"McKenzie est connu pour :","o":["Mouvements actifs répétés et centralisation des symptômes","Mobilisation accessoire convexe-concave","Manipulation thrust","Drainage lymphatique"],"r":0,"e":"McKenzie : positions, exercices actifs répétés, centralisation.","s":10},{"q":"Mulligan est associé à :","o":["MWM (Mobilisation With Movement)","PNF","Concept Maitland","Test musculaire"],"r":0,"e":"Mulligan = MWM : combinaison mobilisation accessoire + mouvement actif.","s":10},{"q":"Cyriax est associé à :","o":["Mobilisations passives, manipulations, massages transverses profonds (MTP)","Tests fonctionnels","Drainage lymphatique","Reprogrammation"],"r":0,"e":"Cyriax (1940-80) : approche orthopédique, MTP.","s":10},{"q":"Le concept Maitland repose principalement sur :","o":["Le diagnostic médical strict","La réponse du patient au mouvement","Les protocoles rigides","La radiographie"],"r":1,"e":"Évaluation analytique basée sur les symptômes/signes du patient.","s":10},{"q":"Le « Permeable Brick Wall » de Maitland sépare :","o":["Théorique/spéculatif et pratique clinique","Sain et malade","Actif et passif","Cervical et lombaire"],"r":0,"e":"2 compartiments perméables : théorie (anatomie, physio) et clinique (présentation, signes).","s":10},{"q":"L'examen subjectif inclut :","o":["Données personnelles, profession","Diagnostic médical","Antécédents (chirurgie, médicaments)","Symptômes et zones","Comportement des symptômes","Tests musculaires"],"r":[0,1,2,3,4],"e":"Subjectif = verbal/anamnestique. Tests musculaires = objectif.","s":10},{"q":"L'examen objectif inclut :","o":["Évaluation structures (œdème, atrophie)","Reproduction des symptômes","ROM, mouvements accessoires","Antécédents médicaux","Comparaison controlatérale"],"r":[0,1,2,4],"e":"Les antécédents font partie du subjectif.","s":10},{"q":"Sur un body chart, on note la chronologie :","o":["D1 apparaît avant D2","D2 avant D1","Aucune chronologie","Dates de l'année"],"r":0,"e":"D1 = premier symptôme, D2 = second. La chronologie aide au raisonnement clinique.","s":10},{"q":"Une douleur constante :","o":["Disparaît au repos","Toujours présente, même au repos","Apparaît à l'effort","Variations cycliques"],"r":1,"e":"Douleur constante = présente en permanence, y compris au repos.","s":10},{"q":"Une douleur mécanique :","o":["Liée à l'inflammation","Liée au mouvement/position, s'améliore au repos","Constante","Spontanée"],"r":1,"e":"Mécanique : déclenchée par le mouvement, soulagée par le repos.","s":10},{"q":"Une douleur inflammatoire :","o":["Soulagée par le mouvement","S'aggrave avec le mouvement","Plus intense le matin, raideur matinale, réveille la nuit","Indépendante de l'horaire"],"r":2,"e":"Profil inflammatoire : pire le matin, raideur, nocturne. S'améliore avec le mouvement.","s":10},{"q":"Une douleur latente :","o":["Présente au repos","Absente au repos, apparaît à la stimulation","Toujours intense","Toujours chronique"],"r":1,"e":"Latente : silencieuse au repos, déclenchée par mouvement/palpation.","s":10},{"q":"Une douleur nociceptive est :","o":["D'origine SN","Liée à une lésion d'un tissu non neural ; localisée ; répond bien à la mobilisation","Centrale","Sans lésion"],"r":1,"e":"Nociceptive (mécanique) = tissu lésé, localisée, répond à la mob.","s":10},{"q":"Une douleur neuropathique :","o":["Mécanique pure","Lésion du SN : chocs, brûlures, picotements","Sans relation neuro","Toujours bénigne"],"r":1,"e":"Neuropathique = lésion nerveuse, exige prudence.","s":10},{"q":"La douleur nociplastique correspond à :","o":["Lésion tissulaire claire","Altération du traitement central de la douleur, sans lésion","Lésion ligamentaire","Rupture musculaire"],"r":1,"e":"Nociplastique = sensibilisation centrale ; mobilisation seule insuffisante.","s":10},{"q":"Le S de SIN signifie :","o":["Symptôme","Sévérité","Stabilité","Stade"],"r":1,"e":"S = Sévérité (intensité, retentissement).","s":10},{"q":"Le I de SIN signifie :","o":["Intensité","Irritabilité (persistance après stimulus)","Inflammation","Insertion"],"r":1,"e":"I = Irritabilité : symptômes persistent après l'arrêt du stimulus.","s":10},{"q":"Le N de SIN signifie :","o":["Niveau","Nature (processus pathologique, stabilité, facteurs)","Nocturne","Numérique"],"r":1,"e":"N = Nature : processus pathologique, facteurs contributifs.","s":10},{"q":"Une irritabilité élevée oriente vers :","o":["Mobilisations grade III-IV","Mobilisations grade I-II","Manipulation thrust","Pas de traitement"],"r":1,"e":"Irritabilité élevée = grades I-II (analgésiques).","s":10},{"q":"En phase AIGUË, la séquence douleur/résistance est :","o":["Résistance puis douleur","Douleur puis résistance","Simultanées","Aucune"],"r":1,"e":"Aigu : douleur AVANT résistance → I-II.","s":10},{"q":"En phase SUBAIGUË :","o":["Douleur seule","Résistance seule","Douleur ET résistance simultanées","Aucune"],"r":2,"e":"Subaigu : mixte, douleur + résistance simultanées → II-III.","s":10},{"q":"En phase CHRONIQUE :","o":["Douleur seule","Résistance PUIS douleur","Douleur PUIS résistance","Pas de douleur"],"r":1,"e":"Chronique : raideur capsulo-ligamentaire, résistance précède la douleur → III-IV.","s":10},{"q":"Pour soulager la douleur, on choisit un rythme :","o":["Rapide et saccadé","Lent et régulier","Soutenu","Aléatoire"],"r":1,"e":"Lent et régulier → analgésie.","s":10},{"q":"Pour traiter une raideur articulaire :","o":["Lent","Rapide et saccadé","Soutenu","En vibration"],"r":1,"e":"Rapide-saccadé → raideur.","s":10},{"q":"Pour réduire les spasmes musculaires :","o":["Rapide","Soutenu","Lent","Très rapide"],"r":1,"e":"Mobilisation soutenue → spasmes.","s":10},{"q":"L'end-feel « capsulaire/élastique » correspond à :","o":["Contact os-os","Tissus mous","Étirement des tissus non contractiles","Spasme"],"r":2,"e":"Élastique = étirement capsulaire/ligamentaire (épaule, hanche).","s":10},{"q":"Dans un diagramme de mouvement, D1 indique :","o":["Le début de la douleur","La fin du mouvement","Le pic de douleur","La résistance maximale"],"r":0,"e":"D1 = apparition initiale de la douleur dans l'amplitude.","s":10},{"q":"L = limite pathologique. Sur le diagramme, D2, R2, S2 représentent :","o":["Le début","La fin (limitant le mouvement)","Le milieu","Sans signification"],"r":1,"e":"D2/R2/S2 = facteur limitant en fin d'amplitude. D'/R'/S' = fin sans limiter.","s":10},{"q":"Kaltenborn a exercé son influence sur la période :","o":["1940-1980","1950-1980","1924-2010","1980-1990"],"r":1,"e":"Il a apporté les fondements biomécaniques de la mobilisation accessoire et la règle concave-convexe.","s":10},{"q":"Maitland a vécu de :","o":["1924 à 2010","1950 à 2000","1900 à 1980","1930 à 1995"],"r":0,"e":"Il a été le premier à systématiser cliniquement la mobilisation accessoire, en se fondant sur la réponse du patient, à la colonne vertébrale.","s":10},{"q":"Mulligan est associé, sur la période 1980-1990, à :","o":["La mobilisation avec mouvement (MWM)","La centralisation des symptômes","Le massage transverse profond","La règle concave-convexe"],"r":0,"e":"McKenzie est associé aux mouvements actifs répétés et à la centralisation, Cyriax aux mobilisations passives, manipulations et MTP.","s":10},{"q":"Le concept de Maitland est décrit comme :","o":["Le plus facilitateur et structurant","Le plus ancien","Le plus rigide","Le plus biomécanique"],"r":0,"e":"Il met l'accent sur l'évaluation analytique continue et le classement par gravité, irritabilité, nature et stade.","s":10},{"q":"La base physiologique du concept de Maitland comporte trois points, dont :","o":["L'engagement personnel à comprendre l'utilisateur","La standardisation des protocoles","La priorité au diagnostic médical","L'application de techniques fixes"],"r":0,"e":"S'y ajoutent la réflexion théorique et l'évaluation permanente avec réévaluation des données.","s":10},{"q":"Dans le concept de Maitland :","o":["Le raisonnement clinique prime sur les protocoles rigides","Les protocoles priment sur le raisonnement","Seule la biomécanique compte","Seule la douleur guide"],"r":0,"e":"Chaque « brique » du mur constitue un élément d'évaluation.","s":10},{"q":"Le concept de Maitland englobe l'évaluation et le traitement :","o":["Du seul système articulaire","Des systèmes neural et musculaire, au-delà de l'articulaire","Du seul système musculaire","Du seul système neural"],"r":1,"e":"Son objectif est de restaurer la fonction selon la réponse de la douleur au mouvement.","s":10},{"q":"Parmi les éléments de l'examen objectif, le cours cite :","o":["Reproduire les symptômes du patient, ce qu'on appelle le signe comparable","Les antécédents médicaux","Le comportement des symptômes au repos","Les données personnelles"],"r":0,"e":"S'y ajoutent l'évaluation des structures, les tests fonctionnels et posturaux, la détection des dysfonctionnements et la comparaison controlatérale.","s":10},{"q":"Sur un body chart, la chronologie se note :","o":["D1 pour la douleur apparue en premier, D2 ensuite","Par ordre d'intensité","Par ordre anatomique","Par ordre de traitement"],"r":0,"e":"On y note aussi la zone, la profondeur, le type et le comportement des symptômes.","s":10},{"q":"Une douleur intermittente se définit comme :","o":["Toujours présente, même au repos","Apparaissant dans certaines situations et disparaissant au repos","Absente au repos et apparaissant à la stimulation","Plus intense le matin"],"r":1,"e":"La douleur latente est, elle, absente au repos et apparaît à la stimulation par le mouvement ou la palpation.","s":10},{"q":"Une douleur inflammatoire se caractérise par :","o":["Une amélioration par le repos","Une intensité matinale majorée, une raideur matinale, une amélioration par le mouvement et un réveil nocturne","Une apparition à la seule palpation","Une absence au repos"],"r":1,"e":"La douleur mécanique s'améliore au contraire avec le repos et dépend du mouvement ou de la position.","s":10},{"q":"Une douleur neuropathique se manifeste par :","o":["Des chocs, brûlures et picotements, et nécessite de la prudence","Une douleur localisée répondant bien à la mobilisation","Une altération du traitement central sans lésion","Une douleur exclusivement nocturne"],"r":0,"e":"La douleur mixte, comme la lombosciatique, associe composantes nociceptive et neuropathique.","s":10},{"q":"Dans l'acronyme SIN, la lettre N désigne :","o":["La sévérité","L'irritabilité","La nature : processus pathologique, stabilité du problème, facteurs contributifs et comportement d'évitement","La nociception"],"r":2,"e":"La sévérité évalue si la douleur limite le mouvement, l'irritabilité si les symptômes persistent après l'arrêt du stimulus.","s":10},{"q":"Une irritabilité élevée oriente vers des mobilisations de degré :","o":["I-II","II-III","III-IV","V"],"r":0,"e":"La douleur y est facile à provoquer et persistante ; les grades I-II visent l'analgésie.","s":10},{"q":"En phase subaiguë, la séquence douleur/résistance est :","o":["Douleur puis résistance","Douleur et résistance simultanées","Résistance puis douleur","Résistance seule"],"r":1,"e":"Elle traduit une inflammation en régression avec raideur, et oriente vers des degrés II-III.","s":10},{"q":"En phase chronique, la séquence est :","o":["Douleur puis résistance","Simultanée","Résistance puis douleur","Aucune des deux"],"r":2,"e":"Elle traduit une raideur capsulo-ligamentaire avec faible inflammation, donc une limitation structurelle, et oriente vers des degrés III-IV.","s":10},{"q":"La phase aiguë, où la douleur précède la résistance, traduit :","o":["Un tissu enflammé avec sensibilité nociceptive élevée et une limitation douloureuse, non structurelle","Une raideur capsulaire","Une limitation structurelle","Une inflammation en régression"],"r":0,"e":"Elle oriente vers des mobilisations de degré I-II.","s":10},{"q":"Les grades III-IV de Maitland sont indiqués pour :","o":["L'analgésie","L'augmentation de l'amplitude","La manipulation","La seule évaluation"],"r":1,"e":"Les grades I-II visent l'analgésie et le grade V correspond à la manipulation.","s":10},{"q":"L'examen subjectif, selon Maitland, recueille notamment :","o":["Les données personnelles, le diagnostic médical, les antécédents, les symptômes et leur comportement, et le stade","Les seuls symptômes","La seule amplitude articulaire","Les seuls tests fonctionnels"],"r":0,"e":"Les antécédents comprennent les médicaments et les chirurgies ; le comportement porte sur le repos et les facteurs aggravants.","s":10},{"q":"Parmi les objectifs du concept de Maitland, le cours cite :","o":["Diminuer douleur et spasmes et augmenter l'amplitude avec qualité","Augmenter la force maximale","Améliorer la capacité aérobie","Corriger la posture uniquement"],"r":0,"e":"Le tout selon la réponse de la douleur et des symptômes au mouvement.","s":10},{"q":"Fonctions de la colonne vertébrale :","o":["Transmission du poids du corps","Protection de la moelle épinière","Détermination de l'amplitude du tronc","Production de calcium","Échanges gazeux"],"r":[0,1,2],"e":"3 fonctions : transmission, protection moelle, amplitude tronc.","s":11},{"q":"La courbure cervicale est une :","o":["Cyphose","Lordose (concavité postérieure)","Scoliose","Aucune courbure"],"r":1,"e":"Cervicale : lordose physiologique.","s":11},{"q":"La courbure dorsale est une :","o":["Lordose","Cyphose (convexité postérieure)","Inversion","Aucune"],"r":1,"e":"Dorsale : cyphose ; protège les organes thoraciques.","s":11},{"q":"Les courbures vertébrales physiologiques :","o":["Diminuent la résistance aux compressions","Augmentent la résistance aux compressions axiales (Kapandji)","Aucun effet","Augmentent les contraintes"],"r":1,"e":"Courbures = ↑ résistance aux compressions (Kapandji).","s":11},{"q":"Le disque intervertébral existe à partir de :","o":["C1","C2","C7","L1"],"r":1,"e":"Pas de disque C0-C1 ni C1-C2 (articulations à pivot). Premier disque = C2-C3.","s":11},{"q":"Le noyau pulpeux à la naissance contient :","o":["50% d'eau","65%","88%","100%"],"r":2,"e":"88% d'eau à la naissance, baisse à ~65% à 77 ans.","s":11},{"q":"L'anneau fibreux est composé de :","o":["Tissu osseux","Tissu cartilagineux (fibres verticales en périphérie, plus obliques au centre)","Liquide synovial","Muscle"],"r":1,"e":"Anneau fibreux : tissu cartilagineux organisé en lamelles.","s":11},{"q":"Une hernie discale signifie :","o":["Disque qui se déforme, anneau intact","Rupture de l'anneau fibreux, noyau qui sort","Glissement des vertèbres","Ostéophyte"],"r":1,"e":"Hernie : rupture de l'anneau, expulsion du noyau.","s":11},{"q":"Une protrusion discale :","o":["Anneau fibreux rompu","Disque qui se déforme, anneau intact","Disque qui s'épaissit","Disparition du disque"],"r":1,"e":"Protrusion : déformation sans rupture de l'anneau.","s":11},{"q":"Pression intradiscale en décubitus dorsal (unités relatives) :","o":["25","50","100","140"],"r":0,"e":"DD = 25 (basse). Debout = 100. Assis = 140.","s":11},{"q":"Pression intradiscale en position debout :","o":["25","50","100","200"],"r":2,"e":"Debout = 100 (référence).","s":11},{"q":"Pression intradiscale en position assise :","o":["50","100","140","200"],"r":2,"e":"Assis = 140. L'inclinaison antérieure majore davantage.","s":11},{"q":"Sous pression axiale :","o":["100% anneau","100% noyau","75% noyau, 25% anneau","50/50"],"r":2,"e":"75% supportés par le noyau, 25% par l'anneau. Noyau disperse horizontalement.","s":11},{"q":"En flexion du tronc, le noyau :","o":["Reste central","Se déplace vers l'arrière (↑ tension ligaments postérieurs)","Se déplace vers l'avant","Disparaît"],"r":1,"e":"Flexion : noyau postérieur, ligaments postérieurs en tension.","s":11},{"q":"En extension, le noyau :","o":["Se déplace en avant","Se déplace en arrière","Reste central","Vers le haut"],"r":0,"e":"Extension : noyau antérieur, ligaments antérieurs en tension.","s":11},{"q":"En flexion latérale, le noyau se déplace :","o":["Vers la concavité","Vers la convexité","Vers le bas","Aucun déplacement"],"r":1,"e":"Flexion latérale : noyau vers la convexité (côté étiré).","s":11},{"q":"Combinaison à risque maximal de hernie :","o":["Flexion seule","Extension seule","Rotation + flexion + charge","Position debout"],"r":2,"e":"Rotation + flexion + charge = risque discal accru.","s":11},{"q":"Le comportement viscoélastique du disque sous charge constante :","o":["Stabilité","↓ épaisseur progressive (creep), perte d'eau","↑ épaisseur","Calcification"],"r":1,"e":"Creep : ↓ taille pendant la journée par perte d'eau du noyau.","s":11},{"q":"ROM cervicale en flexion :","o":["20°","40°","60°","90°"],"r":1,"e":"Cervicale : flexion ~40°, extension ~75°.","s":11},{"q":"ROM lombaire en flexion :","o":["35°","60°","90°","120°"],"r":1,"e":"Lombaire : flexion ~60°, extension ~35°.","s":11},{"q":"Contenu du foramen de conjugaison :","o":["Artère spinale","Nerf spinal","Tissu adipeux","Moelle épinière","Disque intervertébral"],"r":[0,1,2],"e":"3 éléments : artère spinale, nerf spinal, tissu adipeux.","s":11},{"q":"L'extension diminue :","o":["La dimension verticale du foramen","Augmente le foramen","Aucun effet","Augmente la lordose lombaire"],"r":0,"e":"Extension → ↓ dimension verticale du foramen → risque de compression nerveuse.","s":11},{"q":"La flexion augmente :","o":["Diminue le foramen","Le foramen de conjugaison","Aucun effet","La hernie"],"r":1,"e":"Flexion → ↑ foramen (utilisée pour soulager la sciatique).","s":11},{"q":"L'artère vertébrale entre dans le foramen transverse à :","o":["C1","C3","C6","T1"],"r":2,"e":"Entrée à C6, traverse les foramen transverses jusqu'à C1.","s":11},{"q":"Quels mouvements ↑ la compression de l'artère vertébrale ?","o":["Flexion + rotation","Extension + rotation cervicale","Inclinaison latérale isolée","Décompression axiale"],"r":1,"e":"Extension + rotation cervicales = ↑ compression artère vertébrale.","s":11},{"q":"Les 5D (Harper et al., 2020) incluent :","o":["Dizziness (vertiges)","Diplopie","Dysarthrie","Dysphagie","Drop attacks","Douleur lombaire"],"r":[0,1,2,3,4],"e":"Les 5D : vertiges, diplopie, dysarthrie, dysphagie, drop attacks (pas de douleur lombaire).","s":11},{"q":"Les 3N (Harper et al., 2020) :","o":["Nausées","Numbness (engourdissements)","Nystagmus","Niveau de conscience","Néoplasie"],"r":[0,1,2],"e":"3N : nausées, numbness, nystagmus.","s":11},{"q":"Le test de Klein/artère vertébrale est :","o":["Recommandé systématiquement","Évité en raison des risques ; test négatif n'exclut pas le risque (Thomas & Treleaven, 2020)","Toujours fiable","Sans danger"],"r":1,"e":"Test à éviter ; précautions cliniques globales recommandées.","s":11},{"q":"L'articulation sacro-iliaque est :","o":["Cartilagineuse","Synoviale arthrodie ; absorbe les forces de torsion","Fibreuse","Sphéroïde"],"r":1,"e":"SI = synoviale stable, sujette à blocages, ankylose après 50 ans.","s":11},{"q":"La nutation correspond à :","o":["Promontoire vers arrière/haut","Promontoire vers avant/bas, sommet sacrum vers arrière/haut","Rotation pure","Translation latérale"],"r":1,"e":"Nutation : promontoire vers avant/bas. Contre-nutation = inverse.","s":11},{"q":"La musculature statique du rachis assure :","o":["L'équilibre dynamique des gestes volontaires","Une réaction réflexe contrôlant les déséquilibres segmentaires","La protection médullaire","La transmission du poids"],"r":1,"e":"La musculature dynamique assure, elle, l'équilibre dynamique des gestes volontaires conscients.","s":11},{"q":"Selon Kapandji, les courbures vertébrales :","o":["Augmentent la résistance aux compressions axiales","Diminuent la mobilité","Réduisent la protection médullaire","Sont sans rôle mécanique"],"r":0,"e":"La lordose est une concavité postérieure, la cyphose une convexité postérieure.","s":11},{"q":"Le noyau pulpeux contient, à 77 ans, environ :","o":["88 % d'eau","77 % d'eau","65 % d'eau","50 % d'eau"],"r":2,"e":"Il en contient 88 % à la naissance ; cette déshydratation progressive réduit sa capacité d'amortissement.","s":11},{"q":"Dans l'anneau fibreux, les fibres sont :","o":["Verticales en périphérie et plus obliques au centre","Obliques en périphérie et verticales au centre","Toutes verticales","Toutes horizontales"],"r":0,"e":"Il limite les mouvements et absorbe les forces.","s":11},{"q":"La protrusion discale se distingue de la hernie en ce que :","o":["L'anneau reste intact, le disque se déformant seulement","Le noyau sort vers l'extérieur","L'anneau est rompu","Le disque disparaît"],"r":0,"e":"La hernie correspond à une rupture de l'anneau fibreux avec sortie du noyau.","s":11},{"q":"Selon Andersson & Nachemson (1974), la pression intradiscale en position couchée est de :","o":["25","100","140","75"],"r":0,"e":"Elle vaut 100 debout et 140 assis, et augmente fortement en inclinaison antérieure.","s":11},{"q":"Sous pression axiale, la répartition de la charge est :","o":["50 % noyau et 50 % anneau","75 % noyau et 25 % anneau","25 % noyau et 75 % anneau","100 % anneau"],"r":1,"e":"Le noyau disperse les forces horizontalement.","s":11},{"q":"En flexion latérale, le noyau pulpeux se déplace :","o":["Vers la concavité","Vers la convexité","En avant","En arrière"],"r":1,"e":"En flexion il recule et augmente la tension des ligaments postérieurs, en extension il avance.","s":11},{"q":"La combinaison la plus à risque discal est :","o":["Rotation + flexion + charge","Extension seule","Flexion latérale seule","Rotation seule sans charge"],"r":0,"e":"Les mouvements excessifs ou répétés, surtout en charge, favorisent la formation de hernies.","s":11},{"q":"Le comportement viscoélastique du disque sous charge constante se traduit par :","o":["Une diminution progressive d'épaisseur, ou creep, avec perte d'eau du noyau","Un gonflement","Une rigidification","Aucun changement"],"r":0,"e":"La décharge en position couchée permet ensuite la réabsorption d'eau, ou recovery.","s":11},{"q":"L'amplitude de flexion de la colonne cervicale est, selon ce cours, de :","o":["40°","60°","75°","105°"],"r":0,"e":"Son extension atteint 75° ; la région lombaire fléchit à 60° et s'étend à 35°.","s":11},{"q":"Le foramen de conjugaison est limité en arrière par :","o":["Le disque et les corps vertébraux","Les articulations interapophysaires","Les pédicules","Les lames"],"r":1,"e":"Il est limité en avant par le disque et les corps vertébraux, en bas par les pédicules.","s":11},{"q":"Le foramen de conjugaison contient :","o":["L'artère spinale, le nerf spinal et du tissu adipeux","La moelle épinière","L'artère vertébrale","Le ligament jaune"],"r":0,"e":"Le nerf peut y être comprimé par une protrusion ou hernie, une hypertrophie articulaire, ou la combinaison des deux.","s":11},{"q":"La flexion agit sur le foramen de conjugaison en :","o":["Diminuant sa dimension verticale","Augmentant sa dimension verticale","Le fermant complètement","N'ayant aucun effet"],"r":1,"e":"L'extension le diminue, et la flexion latérale l'augmente du côté opposé tout en le diminuant du même côté.","s":11},{"q":"L'artère vertébrale entre dans le foramen transverse au niveau de :","o":["C1","C4","C6","C7"],"r":2,"e":"Elle passe ensuite derrière les apophyses transverses ; extension et rotation cervicale augmentent sa compression.","s":11},{"q":"Parmi les endroits à risque pour l'artère vertébrale, le cours cite :","o":["Les trous transversaux entre C2 et C6, surtout C1/C2, l'articulation C1/C2, C0/C1 et le trajet initial sous-clavier","Le seul niveau C7","La jonction cervico-dorsale","Le foramen magnum uniquement"],"r":0,"e":"La rotation en C1/C2 rétrécit particulièrement l'espace.","s":11},{"q":"Selon Thomas & Treleaven (2020), le test de l'artère vertébrale :","o":["Doit être évité, et un test négatif n'exclut pas le risque","Est obligatoire avant toute manipulation","Est très spécifique","Remplace l'imagerie"],"r":0,"e":"C'est un test de provocation, dont le rapport bénéfice/risque est défavorable.","s":11},{"q":"Parmi les 5D de Harper et al. (2020) figurent :","o":["Vertiges, diplopie, dysarthrie, dysphagie et drop attacks","Douleur, dyspnée et dysurie","Dyskinésie et dystonie","Déficit, douleur et dysesthésie"],"r":0,"e":"Les drop attacks sont des chutes sans perte de conscience ; les 3N sont nausées, engourdissements et nystagmus.","s":11},{"q":"Les 3N de Harper et al. (2020) désignent :","o":["Nausées, engourdissements (numbness) et nystagmus","Névralgie, neuropathie et nécrose","Nausées, nystagmus et névrite","Nausées, nervosité et nystagmus"],"r":0,"e":"Ils complètent les 5D dans le dépistage d'une atteinte vertébro-basilaire.","s":11},{"q":"Parmi les mouvements accessoires de la colonne dorsale, le cours cite :","o":["Les postéro-antérieurs unilatéraux costo-vertébraux","Les transverses au niveau de C1","Les longitudinaux céphaliques","Les rotations pures"],"r":0,"e":"S'y ajoutent les postéro-antérieurs sur les épineuses, les unilatéraux sur les transverses, les transverses et le longitudinal caudal.","s":11},{"q":"Posture vient du latin :","o":["Postura (position, attitude)","Pondus (poids)","Posto (place)","Postulatum (demande)"],"r":0,"e":"Posture = positura (position/attitude dans l'espace).","s":12},{"q":"La posture est :","o":["Toujours fixe","Pas fixe ; change avec positions, mouvements, le temps","Inchangeable après 25 ans","Dépend uniquement du sexe"],"r":1,"e":"Posture dynamique ; évolue avec l'âge, l'activité, le temps.","s":12},{"q":"La posture statique est caractérisée par :","o":["Mouvements rapides","Action gravitaire, tonus, contrôle automatique","Toujours debout","Aucun engagement musculaire"],"r":1,"e":"Statique : maintien (debout, assis) sous l'action de la gravité.","s":12},{"q":"La posture dynamique implique :","o":["Repos absolu","Accélération/décélération, ajustements anticipatifs et réactifs","Sommeil","Apnée"],"r":1,"e":"Dynamique : mouvement, ajustements posturaux constants.","s":12},{"q":"Critères d'une bonne posture :","o":["Centre de gravité dans la base d'appui","Mouvements efficaces","Charge symétrique sur les articulations","Moindre dépense énergétique","Forme parfaite du visage","Bon fonctionnement des organes thoraciques"],"r":[0,1,2,3,5],"e":"5 critères : CG dans BA, mouvements efficaces, charge symétrique, dépense énergétique minimale, organes thoraciques OK.","s":12},{"q":"Alignement idéal de Kendall (plan latéral) :","o":["Sommet suture coronale","Méat auditif externe","Articulation de l'épaule","Légèrement en arrière du grand trochanter","Légèrement en avant du genou","Au milieu de la jambe"],"r":[0,1,2,3,4],"e":"Tous sauf 'milieu de la jambe' (ce serait imprécis ; on parle de malléole).","s":12},{"q":"Le fil à plomb passe légèrement :","o":["Au-dessus du grand trochanter","En arrière du grand trochanter","En avant du grand trochanter","Au centre"],"r":1,"e":"Légèrement en arrière du grand trochanter (axe coxo-fémoral).","s":12},{"q":"Au niveau du genou, le fil à plomb passe :","o":["En arrière","Légèrement en avant","Au milieu","Au-dessus"],"r":1,"e":"Légèrement en avant du genou (pour maintenir l'extension passive).","s":12},{"q":"Au niveau de la cheville, le fil à plomb passe :","o":["En arrière de la malléole interne","Légèrement en avant de la malléole externe","Au milieu du pied","Sur le talon"],"r":1,"e":"Légèrement en avant de la malléole externe.","s":12},{"q":"Causes des modifications posturales :","o":["Traumatismes","Faiblesse neuromusculaire","Problèmes psycho-émotionnels","Malnutrition / obésité","Couleur des cheveux","Dysmétrie des MI"],"r":[0,1,2,3,5],"e":"5 causes parmi les 6 listées. La couleur des cheveux n'a pas d'incidence.","s":12},{"q":"Combien de plans pour l'évaluation posturale ?","o":["1","2","4 (antérieur, postérieur, latéral G, latéral D)","6"],"r":2,"e":"4 plans : antérieur, postérieur, latéral gauche, latéral droit.","s":12},{"q":"Ordre habituel de l'évaluation :","o":["Aléatoire","Céphalo-caudal ou caudal-céphalique","Toujours latéral d'abord","Toujours postérieur d'abord"],"r":1,"e":"Évaluation systématique de haut en bas (ou inverse).","s":12},{"q":"Au plan antérieur, on évalue :","o":["Symétrie du visage et yeux","Niveau des clavicules","Mamelons et sternum","EIAS et crêtes iliaques","Position des MI (varus/valgus)","Position de la moelle épinière"],"r":[0,1,2,3,4],"e":"Tous sauf la moelle (interne).","s":12},{"q":"L'angle Q normal est :","o":["< 5°","< 15° (10-14° H, 15-17° F)","> 30°","Toujours 0°"],"r":1,"e":"Angle Q : EIAS – centre rotule – tubérosité tibiale. < 15° normal.","s":12},{"q":"Une scoliose POSTURALE :","o":["Courbure > 10° avec rotation","Attitude scoliotique réductible","Toujours évolutive","Avec hémivertèbre"],"r":1,"e":"Posturale : la colonne reste souple, retrouve sa forme. Pas de rotation vraie.","s":12},{"q":"Une scoliose STRUCTURELLE est définie par :","o":["Courbure < 10°","Courbure latérale > 10° + rotation des corps vertébraux ; tendance à évoluer","Réductible aisément","Position temporaire"],"r":1,"e":"Structurelle : > 10° + rotation vertébrale. Tendance évolutive.","s":12},{"q":"L'angle crânio-vertébral C7-Tragus normal :","o":["20-30°","50-55°","70-80°","90-100°"],"r":1,"e":"50-55° normal. < 50° = antériorisation.","s":12},{"q":"Antériorisation de la tête : lobe oreille par rapport à acromion :","o":["En arrière","En avant","Au même niveau","Au-dessus"],"r":1,"e":"Lobe en avant de l'acromion = antériorisation.","s":12},{"q":"Pour 2-3 cm d'avancée de la tête, tension supplémentaire :","o":["1-2 kg","3-5 kg","7-14 kg","30 kg"],"r":2,"e":"7-14 kg de tension musculaire supplémentaire pour 2-3 cm.","s":12},{"q":"Posture cyphotique-lordotique : caractéristiques principales :","o":["↓ cyphose dorsale","↑ cyphose dorsale + ↑ lordose lombaire + inclinaison antérieure du bassin","Rectification lordose","Bassin postérieur"],"r":1,"e":"Cyphose-lordose : ↑ cyphose + ↑ lordose + bascule antérieure du bassin.","s":12},{"q":"Muscles faibles dans la cyphotique-lordotique :","o":["Pectoraux","Abdominaux, fessiers, rhomboïdes, trapèze moyen","Quadriceps","Triceps"],"r":1,"e":"Faibles : abdos, fessiers, rhomboïdes, trapèze moyen (chaînes postérieures et stabilisateurs).","s":12},{"q":"Posture flat back :","o":["↑ lordose","↓ cyphose dorsale + rectification lordose lombaire + inclinaison postérieure bassin","Hyperlordose","Bassin antérieur"],"r":1,"e":"Flat back : courbures rectifiées, bascule postérieure du bassin.","s":12},{"q":"Muscles faibles dans la flat back :","o":["Fléchisseurs hanche et extenseurs lombaires","Abdominaux","Quadriceps","Aucun"],"r":0,"e":"Fléchisseurs hanche + extenseurs lombaires = faibles.","s":12},{"q":"Posture sway-back :","o":["Tête centrée, bassin antérieur","Tête en avant, déviation antérieure bassin, inclinaison postérieure, hyperextension genoux","↑ lordose lombaire","Genoux fléchis"],"r":1,"e":"Sway-back : tête avant, bassin déplacé antérieurement, hyperextension genoux.","s":12},{"q":"Muscles faibles dans la sway-back :","o":["Quadriceps","Fessiers et extenseurs dorsaux","Abdominaux uniquement","Trapèze"],"r":1,"e":"Faibles : fessiers et extenseurs dorsaux.","s":12},{"q":"Équilibre du bassin (latéral) — vers l'avant :","o":["Abdominaux (tirent vers le haut)","Fléchisseurs de la hanche (tirent vers le bas)","Extenseurs du rachis","Fessiers"],"r":[0,1],"e":"Avant : abdos haut + fléchisseurs hanche bas.","s":12},{"q":"Équilibre du bassin — vers l'arrière :","o":["Extenseurs du rachis (vers le haut)","Extenseurs de la hanche (vers le bas)","Fléchisseurs hanche","Abdominaux"],"r":[0,1],"e":"Arrière : extenseurs rachis haut + extenseurs hanche bas.","s":12},{"q":"Le test d'Adam (flexion avant) recherche :","o":["Une hernie discale","Une scoliose structurelle (gibbosité)","La force lombaire","La souplesse"],"r":1,"e":"Adam : flexion avant → asymétrie costale (gibbosité) = scoliose structurelle.","s":12},{"q":"Outils d'évaluation posturale :","o":["Test d'Adam","Photogrammétrie posturale","Miroir avec lignes","Scanner cérébral","Goniomètre"],"r":[0,1,2],"e":"3 outils principaux : Adam, photogrammétrie, miroir avec lignes.","s":12},{"q":"L'ergonomie étudie :","o":["L'anatomie","Les interactions humain-éléments d'un système (optimisation bien-être et performance)","Les médicaments","La biomécanique pure"],"r":1,"e":"Ergonomie : interactions humain-système pour optimiser bien-être et performance.","s":12},{"q":"Le mot posture vient du latin :","o":["Positura, signifiant position ou attitude","Postura, signifiant équilibre","Ponere, signifiant poser","Statura, signifiant stature"],"r":0,"e":"Elle désigne la position que le corps adopte dans l'espace, et la disposition des segments par rapport au centre de gravité.","s":12},{"q":"La posture recherche un alignement des segments :","o":["Avec le moindre coût énergétique et biomécanique","Avec la force maximale","Sans rapport avec la dépense énergétique","Fixe dans le temps"],"r":0,"e":"Elle n'est pas fixe : elle change avec les positions, les mouvements et le temps.","s":12},{"q":"La posture statique se caractérise par :","o":["L'action de la gravité, un alignement maintenu, le tonus et un contrôle automatique","Des accélérations et décélérations","Des ajustements anticipatifs","Le mouvement"],"r":0,"e":"La posture dynamique implique mouvement, accélération/décélération et ajustements anticipatifs et réactifs.","s":12},{"q":"Parmi les critères d'une bonne posture, le cours cite :","o":["Le centre de gravité dans la base d'appui, des mouvements efficaces, une charge symétrique, une moindre dépense énergétique et le bon fonctionnement des organes thoraciques et abdominaux","La seule symétrie visuelle","La seule verticalité","La seule absence de douleur"],"r":0,"e":"Ce dernier critère rappelle que la posture a aussi des conséquences viscérales.","s":12},{"q":"Dans l'alignement idéal de Kendall, la ligne passe au niveau du crâne :","o":["Au sommet de la suture coronale","Légèrement en arrière du sommet de la suture coronale","Légèrement en avant","Au vertex"],"r":1,"e":"Elle passe ensuite par le méat auditif externe, les corps vertébraux cervicaux et lombaires et l'articulation de l'épaule.","s":12},{"q":"Au niveau de la hanche, la ligne d'aplomb de Kendall passe :","o":["Légèrement en arrière du grand trochanter","Légèrement en avant du grand trochanter","Sur le grand trochanter","Au centre du bassin"],"r":0,"e":"Elle passe ensuite légèrement en avant du genou et légèrement en avant de la malléole externe.","s":12},{"q":"Parmi les causes de modifications posturales, le cours cite :","o":["Les traumatismes, la faiblesse neuromusculaire, les problèmes psycho-émotionnels, la malnutrition ou l'obésité et les facteurs environnementaux","La seule faiblesse musculaire","Le seul âge","La seule génétique"],"r":0,"e":"S'y ajoutent le repos inadéquat, la fatigue chronique, la diminution de souplesse, la dysmétrie des membres inférieurs et les cicatrices.","s":12},{"q":"L'évaluation posturale se conduit selon :","o":["Quatre plans : antérieur, postérieur, latéral gauche et latéral droit","Deux plans","Trois plans","Un seul plan"],"r":0,"e":"L'ordre peut être céphalo-caudal ou caudal-céphalique.","s":12},{"q":"Au plan antérieur, on recherche notamment :","o":["Un pectus carinatum ou excavatum et un thorax en tonneau","Les épines iliaques postéro-supérieures","L'alignement des apophyses épineuses","Le tendon d'Achille"],"r":0,"e":"On y évalue aussi la symétrie du visage, le niveau des yeux, des clavicules et des mamelons, les EIAS et la position des membres inférieurs.","s":12},{"q":"Une scoliose structurelle se définit par :","o":["Une courbure latérale supérieure à 10° associée à une rotation des corps vertébraux","Une simple attitude corrigeable","Une courbure inférieure à 10°","Une cyphose majorée"],"r":0,"e":"Elle a tendance à évoluer, à la différence de la scoliose posturale où la colonne reste souple et retrouve sa forme.","s":12},{"q":"L'angle crânio-vertébral C7-tragus est considéré comme normal entre :","o":["40 et 45°","50 et 55°","60 et 65°","30 et 40°"],"r":1,"e":"En dessous de 50°, on parle d'antériorisation de la tête.","s":12},{"q":"L'antériorisation de la tête se repère par :","o":["Le lobe de l'oreille en avant de l'acromion","Le lobe de l'oreille en arrière de l'acromion","L'alignement parfait","La position du menton"],"r":0,"e":"Pour 2 à 3 cm d'avancée, la tension supplémentaire est de 7 à 14 kg.","s":12},{"q":"La posture cyphotique-lordotique associe :","o":["Tête en avant, hyperextension cervicale, cyphose dorsale augmentée, abduction des omoplates, lordose lombaire augmentée, bascule antérieure du bassin et hyperextension des genoux","Une rectification de la lordose","Une bascule postérieure du bassin","Une diminution de la cyphose"],"r":0,"e":"Les muscles faibles y sont les abdominaux, les fessiers, les rhomboïdes et le trapèze moyen.","s":12},{"q":"Dans la posture flat back, les muscles faibles sont :","o":["Les abdominaux et les fessiers","Les fléchisseurs de hanche et les extenseurs lombaires","Les fessiers et les extenseurs dorsaux","Les rhomboïdes"],"r":1,"e":"Elle associe tête en avant, extension cervicale, cyphose diminuée, rectification de la lordose, bascule postérieure du bassin et extension des genoux.","s":12},{"q":"Dans la posture sway-back, les muscles faibles sont :","o":["Les fessiers et les extenseurs dorsaux","Les abdominaux et les rhomboïdes","Les fléchisseurs de hanche","Les extenseurs lombaires"],"r":0,"e":"Elle associe tête en avant, hyperextension cervicale, cyphose augmentée, légère extension lombaire, déviation antérieure du bassin et hyperextension des genoux.","s":12},{"q":"Dans l'équilibre du bassin, les muscles qui le tirent vers l'avant sont :","o":["Les abdominaux vers le haut et les fléchisseurs de hanche vers le bas","Les extenseurs du rachis et de la hanche","Les fessiers seuls","Les abdominaux seuls"],"r":0,"e":"Vers l'arrière, les extenseurs du rachis tirent vers le haut et les extenseurs de hanche vers le bas.","s":12},{"q":"Le test de flexion avant d'Adam recherche :","o":["Une scoliose structurelle","Une cyphose","Une antériorisation de la tête","Une dysmétrie"],"r":0,"e":"Photogrammétrie posturale et miroir avec lignes complètent les outils d'évaluation.","s":12},{"q":"L'ergonomie se définit comme l'étude :","o":["Des interactions entre l'humain et les éléments d'un système, pour optimiser bien-être et performance","De la posture statique seule","Du mobilier de bureau","Des troubles musculo-squelettiques"],"r":0,"e":"Le mobilier, les chaussures et les conditions de travail figurent parmi les facteurs environnementaux de modification posturale.","s":12},{"q":"L'angle Q est considéré comme normal, en évaluation posturale, en dessous de :","o":["10°","15°","20°","25°"],"r":1,"e":"Il s'évalue au plan antérieur, avec la position des membres inférieurs en varus ou valgus.","s":12},{"q":"La posture est décrite comme favorisant :","o":["Le confort et un soutien économique et harmonieux","La force maximale","La souplesse maximale","L'immobilité"],"r":0,"e":"Cela découle de la recherche du moindre coût énergétique et biomécanique.","s":12},{"q":"Que signifie la « force » musculaire selon le cours ?","o":["La taille du muscle au repos","La capacité d'un muscle à générer une tension dans un temps et à une vitesse donnés","La résistance d'un muscle à l'étirement passif","La quantité d'ATP stockée dans le muscle"],"r":1,"e":"La force est une qualité physique de caractéristique neuromusculaire.","s":13},{"q":"Plus le nombre d'unités motrices activées est élevé...","o":["...plus la fatigue diminue","...plus la force développée est importante","...plus la vitesse de contraction diminue","...plus la taille du muscle augmente immédiatement"],"r":1,"e":"Le nombre d'unités motrices recrutées détermine la force produite.","s":13},{"q":"Le test musculaire manuel est né dans le contexte de l'étude de quelle pathologie ?","o":["La sclérose en plaques","La myopathie de Duchenne","La poliomyélite","Les AVC"],"r":2,"e":"Études du début du XXe siècle aux États-Unis. Robert W. Lovett a introduit la méthode utilisant la résistance à la gravité.","s":13},{"q":"Qui a introduit la méthode de test utilisant la résistance à la gravité ?","o":["Henry Kendall","Robert W. Lovett","Daniels & Worthingham","George Maitland"],"r":1,"e":"Lovett a posé les bases du testing manuel utilisant la gravité comme résistance.","s":13},{"q":"La méthode de Daniels & Worthingham teste principalement :","o":["L'activité musculaire groupée dans un mouvement articulaire","L'action d'un muscle spécifique","L'endurance musculaire uniquement","La proprioception articulaire"],"r":0,"e":"Daniels & Worthingham : groupes musculaires. Kendall & McCreary : muscles spécifiques.","s":13},{"q":"Selon la méthode Kendall & McCreary, combien de tests sont nécessaires pour évaluer les abducteurs de la hanche ?","o":["1 test","2 tests","3 tests (moyen fessier, TFL, petit fessier)","4 tests"],"r":2,"e":"Chaque muscle abducteur est isolé : moyen fessier, TFL, petit fessier.","s":13},{"q":"Quel est l'avantage principal de la méthode Daniels & Worthingham ?","o":["Plus précise pour identifier les substitutions","Plus pratique et rapide pour un dépistage","Permet de tester chaque muscle séparément","Évite les compensations"],"r":1,"e":"Daniels & Worthingham est plus rapide, surtout en dépistage.","s":13},{"q":"Les auteurs phares dont provient la plupart des tests musculaires manuels modernes sont :","o":["Cyriax et Maitland","Henry et Florence Kendall","Lovett et McCreary","Janda et Lewit"],"r":1,"e":"Auteurs de Muscles: Testing and Function.","s":13},{"q":"Pour garantir la fiabilité du test musculaire manuel, il faut :","o":["Effectuer chaque test au moins 5 fois","Utiliser un dynamomètre électronique systématiquement","Effectuer les tests de la même manière et au même point de l'amplitude","Toujours tester le côté affecté en premier"],"r":2,"e":"La standardisation est la condition de la reproductibilité.","s":13},{"q":"Lequel de ces facteurs n'influence PAS la reproductibilité d'un test musculaire ?","o":["La méthode utilisée","Le ton de la voix du thérapeute","La fatigue du patient","La couleur des vêtements du patient"],"r":3,"e":"Tous les autres sont listés comme facteurs influençants.","s":13},{"q":"L'amplitude de test correspond à :","o":["L'amplitude maximale du segment dans toutes les directions","L'amplitude spécifique au muscle testé, qui ne coïncide pas forcément avec l'amplitude de mouvement","L'amplitude minimale clinique","L'amplitude active uniquement"],"r":1,"e":"L'amplitude de test est spécifique à chaque muscle.","s":13},{"q":"Comment doit-on positionner les muscles biarticulaires lors du test ?","o":["À leur position d'allongement maximal","À leur position de raccourcissement maximal","À la position intermédiaire de l'amplitude totale du muscle","En appui contre la gravité"],"r":2,"e":"Les biarticulaires sont évalués à la position intermédiaire pour éviter une perte de tension active.","s":13},{"q":"Lors du test, le segment proximal doit être :","o":["Mobilisé activement par le patient","Stabilisé","Étiré au maximum","Maintenu en flexion"],"r":1,"e":"La stabilisation du segment proximal isole le mouvement testé.","s":13},{"q":"Quel type de contraction est requis lors du test musculaire manuel à la fin de l'amplitude ?","o":["Isotonique concentrique","Isotonique excentrique","Isométrique","Isocinétique"],"r":2,"e":"Test isométrique en fin d'amplitude pour mesurer la force statique maximale.","s":13},{"q":"La résistance doit être appliquée :","o":["Avec une seule main, l'autre stabilisant","Avec les deux mains pour mieux contrôler","Toujours sur l'articulation","Très rapidement et brusquement"],"r":0,"e":"Une main pour la résistance, une main pour la stabilisation. Jamais sur l'articulation.","s":13},{"q":"Que signifie un degré 0 ?","o":["Aucune contraction perceptible","Contraction ressentie sans mouvement","Mouvement complet sans gravité","Mouvement complet avec résistance maximale"],"r":0,"e":"Degré 0 = absence totale de contraction.","s":13},{"q":"Que signifie un degré 1 ?","o":["Aucune contraction","Contraction ressentie mais sans mouvement","Mouvement complet contre gravité","Mouvement complet contre résistance modérée"],"r":1,"e":"Degré 1 = contraction perceptible (palpation), pas de mouvement.","s":13},{"q":"Que signifie un degré 3 ?","o":["Mouvement contre résistance maximale","Mouvement avec gravité éliminée","Amplitude complète sans application de résistance (mais contre la gravité)","Aucune contraction"],"r":2,"e":"3 = ROM complète contre gravité, sans résistance externe ajoutée.","s":13},{"q":"Que signifie un degré 5 ?","o":["Position complète sans résistance","Position complète avec résistance modérée","Test complet et résistance maximale","Test impossible à effectuer"],"r":2,"e":"Degré 5 correspond à la force normale, résistance maximale.","s":13},{"q":"Comment doivent être notés les degrés inférieurs à 3 ?","o":["En noir","En rouge","En bleu","En vert"],"r":1,"e":"Convention : < 3 en rouge, ≥ 3 en noir.","s":13},{"q":"Pour tester un muscle faible qui ne peut pas vaincre la gravité, on utilise :","o":["Une position contre la gravité avec résistance","Une position dans le plan horizontal (gravité éliminée)","Une position pendante","Une posture en suspension"],"r":1,"e":"Plan horizontal pour éliminer l'effet gravitaire chez le muscle faible (degrés 0-2).","s":13},{"q":"Lequel de ces facteurs PEUT diminuer la force musculaire ?","o":["L'augmentation de la masse maigre","L'entraînement régulier","La douleur","L'hydratation correcte"],"r":2,"e":"Atrophie, atteinte SN, douleur, fatigue, lésion musculaire diminuent la force.","s":13},{"q":"Chez la personne âgée, on observe une perte de fibres préférentiellement :","o":["De type I (lentes)","De type II (rapides)","De type III","Toutes au même rythme"],"r":1,"e":"Atteinte préférentielle des fibres de type II → ralentissement, perte d'explosivité.","s":13},{"q":"Les conséquences neuromusculaires du vieillissement incluent :","o":["Augmentation du nombre de motoneurones","Diminution du nombre et de la taille des unités motrices","Augmentation de la vitesse de conduction","Hypertrophie des axones"],"r":1,"e":"Réduction des UM et de leur taille, diamètre axonal réduit, conduction plus lente.","s":13},{"q":"Quel objectif n'est PAS un objectif typique du test musculaire ?","o":["Aide au diagnostic différentiel","Pronostic","Suivi du traitement","Mesure de la consommation d'oxygène"],"r":3,"e":"Le test musculaire ne mesure pas la VO2.","s":13},{"q":"Quel est l'inconvénient principal de la méthode Kendall & McCreary ?","o":["Elle est moins fiable","Elle prend plus de temps et nécessite une connaissance précise de l'orientation des muscles","Elle ne permet pas de détecter les substitutions","Elle ne peut pas être utilisée en clinique"],"r":1,"e":"Kendall = précis mais long, requérant des connaissances anatomiques pointues.","s":13},{"q":"Avant le test, on doit :","o":["Faire courir le patient pour échauffer le muscle","Expliquer la procédure et démontrer ce qu'on attend du patient","Donner un anti-douleur","Tester d'abord le membre douloureux sans préavis"],"r":1,"e":"Communication et préparation = base de la coopération.","s":13},{"q":"Lors du test, l'utilisation de leviers longs :","o":["Est recommandée autant que possible","Est interdite","Est utilisée uniquement chez l'enfant","N'a pas d'incidence"],"r":0,"e":"Levier long = meilleure mécanique, sauf si la fixation proximale est impossible.","s":13},{"q":"Quelle compétence n'est PAS essentielle chez l'observateur ?","o":["Connaissances anatomiques","Compétences techniques","Expérience clinique","Capacité à courir un marathon"],"r":3,"e":"L'observateur a besoin de compétences cognitives et techniques.","s":13},{"q":"Lequel de ces effets fait partie des adaptations positives à l'exercice chez la personne âgée ?","o":["Diminution du volume musculaire","Réduction des unités motrices","Adaptations neuronales et remodelage musculaire","Atrophie sélective des fibres I"],"r":2,"e":"L'exercice induit augmentation du volume musculaire, remodelage et adaptations neuronales.","s":13},{"q":"La force se définit dans le cours comme la capacité à générer une tension :","o":["Dans un temps donné et à une vitesse donnée","Sans limite de temps","Indépendamment de la vitesse","À vitesse maximale uniquement"],"r":0,"e":"C'est une qualité physique de caractéristique neuromusculaire.","s":13},{"q":"Le test musculaire évalue trois capacités :","o":["Activer les muscles squelettiques, provoquer un mouvement, stabiliser et soutenir","Force, endurance et puissance","Amplitude, force et souplesse","Coordination, équilibre et vitesse"],"r":0,"e":"Le muscle joue en effet, outre le mouvement, un rôle de soutien des structures squelettiques.","s":13},{"q":"Le cours énonce qu'un muscle doit être :","o":["Le plus long possible","Suffisamment long pour la mobilité normale mais suffisamment court pour contribuer à la stabilité articulaire","Le plus court possible","De longueur indifférente"],"r":1,"e":"C'est ce double impératif qui fonde l'évaluation de la longueur autant que de la force.","s":13},{"q":"Les trois utilisations cliniques du test musculaire sont :","o":["Diagnostic, pronostic et traitement","Dépistage, prévention et suivi","Recherche, enseignement et clinique","Force, endurance et puissance"],"r":0,"e":"Le diagnostic vise le différentiel des troubles neuromusculaires et musculo-squelettiques.","s":13},{"q":"Le test musculaire manuel est né :","o":["Aux États-Unis au début des années 1900, lors d'une étude sur la poliomyélite","En Europe dans les années 1950","Au Japon dans les années 1970","En Australie dans les années 1980"],"r":0,"e":"Robert W. Lovett y a introduit la méthode utilisant la résistance à la gravité.","s":13},{"q":"La méthode Daniels & Worthingham teste :","o":["L'action d'un muscle spécifique","L'activité musculaire groupée, par le mouvement articulaire","La seule endurance","La seule amplitude"],"r":1,"e":"Kendall & McCreary testent, eux, l'action d'un muscle spécifique — d'où trois tests séparés pour les abducteurs de hanche.","s":13},{"q":"L'inconvénient principal de la méthode Kendall & McCreary est :","o":["Son manque de spécificité","Sa durée et l'exigence d'une connaissance précise de l'orientation musculaire","Son imprécision","Son coût"],"r":1,"e":"Daniels & Worthingham est au contraire plus pratique et rapide pour un dépistage, mais moins spécifique.","s":13},{"q":"Les auteurs de Muscles: Testing and Function sont :","o":["Henry et Florence Kendall","Daniels et Worthingham","Lovett et Cyriax","Janda et Kaltenborn"],"r":0,"e":"La plupart des tests musculaires modernes en proviennent.","s":13},{"q":"La fiabilité inter- et intra-examinateurs n'est garantie que si les tests sont réalisés :","o":["De la même manière et au même point de l'amplitude à chaque fois","Par le même examinateur","Avec le même instrument","Au même moment de la journée"],"r":0,"e":"Le problème central reste la variable « cadre de référence » utilisée pour l'évaluation.","s":13},{"q":"Parmi les facteurs de variabilité liés à la technique, le cours cite :","o":["Le point et la ligne d'application de la résistance, son amplitude, sa vitesse, la durée de contraction, les instructions et le ton de la voix","La seule méthode employée","La seule fatigue du patient","La seule expérience de l'observateur"],"r":0,"e":"S'y ajoutent des facteurs liés au patient et à l'observateur.","s":13},{"q":"Parmi les facteurs liés au patient figurent :","o":["La coopération, la fatigue, les influences perturbatrices comme la douleur et l'anxiété, et l'interaction thérapeute-patient","Les connaissances anatomiques","La compétence technique","L'expérience clinique"],"r":0,"e":"Les trois derniers items relèvent des facteurs liés à l'observateur.","s":13},{"q":"L'amplitude de test se distingue de l'amplitude de mouvement en ce qu'elle :","o":["Est spécifique au muscle testé et ne coïncide pas nécessairement avec l'amplitude de mouvement","Est toujours plus grande","Est toujours plus petite","Est identique"],"r":0,"e":"L'amplitude de mouvement est l'espace parcouru de la position neutre à la position extrême.","s":13},{"q":"Les muscles biarticulaires sont testés :","o":["En amplitude complète","À la position intermédiaire de l'amplitude totale","En position raccourcie maximale","En position allongée maximale"],"r":1,"e":"Les muscles mono-articulaires doivent, eux, compléter l'amplitude articulaire.","s":13},{"q":"Le positionnement du patient pour le test peut être :","o":["En décubitus dorsal, ventral ou latéral, selon ce qui permet la meilleure fixation","Exclusivement assis","Exclusivement debout","Indifférent"],"r":0,"e":"La stabilisation porte sur le segment proximal à la zone testée.","s":13},{"q":"Lorsque les muscles sont faibles, la zone testée est placée :","o":["Contre la gravité","En plan horizontal, gravité éliminée","En position déclive","En charge"],"r":1,"e":"La position contre gravité s'emploie pour la plupart des muscles du tronc et certains muscles des extrémités.","s":13},{"q":"La contraction demandée lors du test est :","o":["Isotonique concentrique","Isométrique, à la fin de l'amplitude testée","Excentrique","Isocinétique"],"r":1,"e":"Elle permet une comparaison reproductible en un point précis de l'amplitude.","s":13},{"q":"Concernant les leviers, le cours recommande de les prendre :","o":["Longs autant que possible, et courts si les muscles ne permettent pas une fixation importante","Toujours courts","Toujours longs","Indifféremment"],"r":0,"e":"Le levier long augmente le moment résistant et affine la discrimination des grades élevés.","s":13},{"q":"Avant le test, la checklist prévoit notamment :","o":["De déterminer passivement l'amplitude de mouvement du segment","De mesurer la force au dynamomètre","De faire un échauffement complet","De réaliser un bilan goniométrique complet"],"r":0,"e":"S'y ajoutent l'explication, l'exposition de la zone, le placement en position initiale, la stabilisation, la palpation et la surveillance des substitutions.","s":13},{"q":"La résistance doit être, selon le cours :","o":["Douce, ferme et graduée","Maximale d'emblée","Brève et brutale","Maintenue longuement"],"r":0,"e":"Il ne faut ni la maintenir trop longtemps ni la répéter, afin d'éviter la fatigue.","s":13},{"q":"Le degré 2 de Lovett correspond à :","o":["Aucune contraction","Une contraction palpable sans mouvement","Une amplitude complète sans gravité","Une amplitude complète contre gravité"],"r":2,"e":"Le degré 3 correspond à l'amplitude complète contre gravité sans résistance, le 4 avec résistance modérée et le 5 avec résistance maximale.","s":13}]};
